INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25276, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "坎儿井", "is_correct": true, "explanation": "正确。“挖了一条坎儿井”指在地下挖出的水渠，与句意相符。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼不是人在地下挖出来的，与“挖”的动作不符。"}, {"text": "绳子", "is_correct": false, "explanation": "语义：绳子是编成或搓成的，不是挖出来的。"}, {"text": "裤子", "is_correct": false, "explanation": "搭配：“挖”不搭配“裤子”，裤子不是挖掘的对象。"}], "explanations": {"坎儿井": "正确。“挖了一条坎儿井”指在地下挖出的水渠，与句意相符。", "鱼": "语义：鱼不是人在地下挖出来的，与“挖”的动作不符。", "绳子": "语义：绳子是编成或搓成的，不是挖出来的。", "裤子": "搭配：“挖”不搭配“裤子”，裤子不是挖掘的对象。"}, "sentence_index": 0, "correct_answer": "坎儿井"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在书上读到过坎儿井，它每天载着乘客穿过城市。", "explanation": "这里应该用〈地铁〉。地铁是载着乘客穿过城市的交通工具；坎儿井是引水灌溉的水渠，不能载客。"}, {"text": "坎儿井把生活污水排出去。", "explanation": "这里应该用〈下水道〉。坎儿井是用来引水灌溉的，不是排污的管道。"}, {"text": "坎儿井里存着冬天的菜。", "explanation": "这里应该用〈地窖〉。坎儿井是引水的水渠，不用来存放蔬菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '039c40f7-075a-413f-97af-51810b361236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25276, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "坎儿井", "is_correct": true, "explanation": "正确。坎儿井是地下的水渠，水清凉干净，与句意相符。"}, {"text": "电线", "is_correct": false, "explanation": "语义：电线是输电用的导线，里面没有可以饮用的水，“又凉又干净的水”说不通。"}, {"text": "帽子", "is_correct": false, "explanation": "语义：帽子不是储水的地方，“帽子里的水又凉又干净”说不通。"}, {"text": "衣柜", "is_correct": false, "explanation": "搭配：衣柜不是储水的地方，“衣柜里的水”不成立。"}], "explanations": {"坎儿井": "正确。坎儿井是地下的水渠，水清凉干净，与句意相符。", "电线": "语义：电线是输电用的导线，里面没有可以饮用的水，“又凉又干净的水”说不通。", "帽子": "语义：帽子不是储水的地方，“帽子里的水又凉又干净”说不通。", "衣柜": "搭配：衣柜不是储水的地方，“衣柜里的水”不成立。"}, "sentence_index": 6, "correct_answer": "坎儿井"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "坎儿井是一种在山顶上修的高塔。", "explanation": "这里应该用〈烽火台〉。烽火台是建在山顶、用来传递军情的高台；坎儿井是地下挖的水渠，不是地面上的高塔。"}, {"text": "坎儿井把烟排到天上。", "explanation": "这里应该用〈烟囱〉。烟囱是排烟的管道；坎儿井是引水的水渠，不能排烟。"}, {"text": "坎儿井让火车穿过山。", "explanation": "这里应该用〈隧道〉。隧道是为让火车穿过山体挖的通道；坎儿井是引水的水渠，不能让火车通过。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '039c40f7-075a-413f-97af-51810b361236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25276, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老人们在地下修了一张坎儿井。", "corrected_sentence": "老人们在地下修了一条坎儿井。", "error_description": "量词错误：坎儿井是长长的地下水渠，量词应为“条”；“张”用于纸、桌子等平面的东西，不能用于坎儿井。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '039c40f7-075a-413f-97af-51810b361236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25276, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去新疆参观过一只坎儿井。", "corrected_sentence": "他去新疆参观过一条坎儿井。", "error_description": "量词错误：坎儿井的量词应为“条”，“只”用于动物等，不能用于坎儿井，应为“参观过一条坎儿井”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '039c40f7-075a-413f-97af-51810b361236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
