INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25278, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "水流动时产生的力量，可以用来发电或推动东西。", "primary_collocate": null, "pronunciation": "shuǐ lì", "ipa": "ʂweɪ˨˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "河水很急，水力推着小船往下走。", "target_word": "水力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人用水力推动水车磨面粉。", "target_word": "水力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器靠水力转动。", "target_word": "水力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水的水力很大，连石头都冲走了。", "target_word": "水力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水车是利用水力把水送到田里的。", "target_word": "水力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小溪水少，水力不够，水车转不动。", "target_word": "水力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把木轮放进河里，让水力带它转。", "target_word": "水力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水力越大，磨坊里的石磨转得越快。", "target_word": "水力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座磨坊用的是水力，不用电。", "target_word": "水力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水从高处流下，水力特别大。", "target_word": "水力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "水力发电", "label": "复合"}, {"form": "水力资源", "label": "复合"}], "register": "中性", "sense_fingerprint": "水流动时产生的、可推动物体的力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae977bd1-2422-4850-971e-89db1614974a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25278, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "水力", "is_correct": true, "explanation": "水力（shuǐ lì）指水流动时产生的力量，是这个词的正确读音。"}, {"text": "水里", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，意思是在水中。"}, {"text": "水梨", "is_correct": false, "explanation": "lí（第二声）与 lì（第四声）声调不同，意思是一种水果。"}, {"text": "税利", "is_correct": false, "explanation": "shuì（第四声）与 shuǐ（第三声）声调不同，意思是税收和利润。"}], "explanations": {"水力": "水力（shuǐ lì）指水流动时产生的力量，是这个词的正确读音。", "水里": "lǐ（第三声）与 lì（第四声）声调不同，意思是在水中。", "水梨": "lí（第二声）与 lì（第四声）声调不同，意思是一种水果。", "税利": "shuì（第四声）与 shuǐ（第三声）声调不同，意思是税收和利润。"}, "sentence_index": null, "correct_answer": "水力"}, "level_3": {"options": [{"text": "水力", "is_correct": true, "explanation": "水力指水流产生的、能推动物体的力量，正好推动小船。"}, {"text": "水质", "is_correct": false, "explanation": "语义：水质指水的好坏，不是能推动小船的力量。"}, {"text": "水温", "is_correct": false, "explanation": "语义：水温指水的冷热，不能推动小船。"}, {"text": "水深", "is_correct": false, "explanation": "搭配：“推”要求能推动物体的力量或人，“水深”是状态，不能作施事。"}], "explanations": {"水力": "水力指水流产生的、能推动物体的力量，正好推动小船。", "水质": "语义：水质指水的好坏，不是能推动小船的力量。", "水温": "语义：水温指水的冷热，不能推动小船。", "水深": "搭配：“推”要求能推动物体的力量或人，“水深”是状态，不能作施事。"}, "sentence_index": 0, "correct_answer": "水力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的水力很大，一拳就打碎了木板。", "explanation": "这里应该用〈力量〉。水力特指水流动时产生的力量，人的力气要用力量。"}, {"text": "河里的水力很急，把木排冲得很远。", "explanation": "这里应该用〈水流〉。水力指力量，形容水流的快慢要用水流。"}, {"text": "这个村子去年修了水力。", "explanation": "这里应该用〈水利〉。修的是水利工程，水力是力量，不能说“修”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25278, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水力", "is_correct": true, "explanation": "水力指水流产生的、能推动物体的力量，能带动木轮转。"}, {"text": "水位", "is_correct": false, "explanation": "语义：水位指水面的高低，不能带动木轮转。"}, {"text": "水质", "is_correct": false, "explanation": "语义：水质指水的好坏，不是能带动物体的力量。"}, {"text": "水量", "is_correct": false, "explanation": "配价：“水量”只能说多少，不能作“带”的施事，让它带动木轮不成立。"}], "explanations": {"水力": "水力指水流产生的、能推动物体的力量，能带动木轮转。", "水位": "语义：水位指水面的高低，不能带动木轮转。", "水质": "语义：水质指水的好坏，不是能带动物体的力量。", "水量": "配价：“水量”只能说多少，不能作“带”的施事，让它带动木轮不成立。"}, "sentence_index": 6, "correct_answer": "水力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的水力来自电池。", "explanation": "这里应该用〈能量〉。水力指水流产生的力量，电池提供的能量不能说水力。"}, {"text": "这阵水力很大，把帽子吹走了。", "explanation": "这里应该用〈风力〉。水力指水流的力量，形容风要用风力。"}, {"text": "这辆摩托车的水力很强，一下子就冲上了坡。", "explanation": "这里应该用〈动力〉。水力只指水流的力量，机器的动力不能说水力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25278, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个磨坊靠一台水力磨面粉。", "corrected_sentence": "这个磨坊靠水力磨面粉。", "error_description": "“水力”是不可数的力量名词，不能用量词“台”计量。应去掉“一台”，说“靠水力磨面粉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25278, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "水力把木排推。", "corrected_sentence": "水力把木排推走了。", "error_description": "错误：把字句中动词“推”后面缺少结果补语或其它成分，不能单独结尾。应说“水力把木排推走了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
