INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25280, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把水送到别的地方。", "primary_collocate": null, "pronunciation": "shū shuǐ", "ipa": "ʂu˥ ʂweɪ˨˩", "syllable_count": 2, "sentences": [{"text": "管子坏了，没法给我们家输水。", "target_word": "输水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根粗管子负责给小区输水。", "target_word": "输水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水厂每天给城里的人家输水。", "target_word": "输水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里新装了管道，可以输水了。", "target_word": "输水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水泵一开，水管就开始输水。", "target_word": "输水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的水渠向山下输水。", "target_word": "输水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条旧渠已经不能输水了。", "target_word": "输水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人在检查管道能不能输水。", "target_word": "输水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们打开阀门，开始向田里输水。", "target_word": "输水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条管道一天二十四小时输水。", "target_word": "输水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "输水管", "label": "复合"}, {"form": "输水了", "label": "体标"}, {"form": "輸水", "label": "繁体"}], "register": "书面", "sense_fingerprint": "管子、水渠或水厂把水送到别处，日常供水场景", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '924b73f8-6511-4651-8db4-395d31541c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25280, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "输水", "is_correct": true, "explanation": "输水（shū shuǐ）：通过管道或渠道把水送到别处。"}, {"text": "熟水", "is_correct": false, "explanation": "shú 与 shū 声调不同，“熟水”指烧开过的水。"}, {"text": "需水", "is_correct": false, "explanation": "xū 与 shū 声母不同（x 与 sh），意思是需要水。"}, {"text": "失水", "is_correct": false, "explanation": "shī 与 shū 韵母不同（i 与 u），意思是失去水分。"}], "explanations": {"输水": "输水（shū shuǐ）：通过管道或渠道把水送到别处。", "熟水": "shú 与 shū 声调不同，“熟水”指烧开过的水。", "需水": "xū 与 shū 声母不同（x 与 sh），意思是需要水。", "失水": "shī 与 shū 韵母不同（i 与 u），意思是失去水分。"}, "sentence_index": null, "correct_answer": "输水"}, "level_3": {"options": [{"text": "输水", "is_correct": true, "explanation": "正确：“没法给我们家输水”指管子无法向家里送水，与管子坏了的语境相符。"}, {"text": "修车", "is_correct": false, "explanation": "语义：“修车”与管子坏了、给家里送水的语境无关。"}, {"text": "放映", "is_correct": false, "explanation": "语义：“放映”指播放影像，与管子和送水的语境不符。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：发芽指植物长出芽，与管子坏了、给家里送水无关。"}], "explanations": {"输水": "正确：“没法给我们家输水”指管子无法向家里送水，与管子坏了的语境相符。", "修车": "语义：“修车”与管子坏了、给家里送水的语境无关。", "放映": "语义：“放映”指播放影像，与管子和送水的语境不符。", "发芽": "语义：发芽指植物长出芽，与管子坏了、给家里送水无关。"}, "sentence_index": 0, "correct_answer": "输水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天用喷壶给院子里的花输水。", "explanation": "这里应该用〈喷〉。输水指用管道、渠道大批量运送水，喷壶少量喷水要说喷水。"}, {"text": "护士给病人输水。", "explanation": "这里应该用〈输液〉。给病人静脉注入液体要说输液，输水指用管道运送水。"}, {"text": "他每天去井边输水。", "explanation": "这里应该用〈挑水〉。输水指通过管道、渠道等大批量送水，一个人用扁担把水挑回家要说挑水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11f4889c-b619-43f4-885a-c7a5a833fda1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25280, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "输水", "is_correct": true, "explanation": "正确：“不能输水了”指旧渠道已无法送水，与渠道的语境相符。"}, {"text": "行走", "is_correct": false, "explanation": "语义：渠道是水利设施，不能行走，与“旧渠”的语境不符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：渠道不能唱歌，“不能唱歌了”与水利设施的语境无关。"}, {"text": "通电", "is_correct": false, "explanation": "搭配：“通电”指接通电流，一般不用于渠道，不说“渠道不能通电了”。"}], "explanations": {"输水": "正确：“不能输水了”指旧渠道已无法送水，与渠道的语境相符。", "行走": "语义：渠道是水利设施，不能行走，与“旧渠”的语境不符。", "唱歌": "语义：渠道不能唱歌，“不能唱歌了”与水利设施的语境无关。", "通电": "搭配：“通电”指接通电流，一般不用于渠道，不说“渠道不能通电了”。"}, "sentence_index": 6, "correct_answer": "输水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医院里，护士一天二十四小时给病人输水。", "explanation": "这里应该用〈输液〉。给病人静脉注入药液要说输液，输水指用管道、渠道运送水。"}, {"text": "他一天二十四小时用杯子输水。", "explanation": "这里应该用〈喝水〉。用杯子是喝水，输水指管道、渠道把水送到别处。"}, {"text": "这条电线一天二十四小时输水。", "explanation": "这里应该用〈输电〉。电线送的是电，要说输电，输水只用于管道、渠道送水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11f4889c-b619-43f4-885a-c7a5a833fda1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25280, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜里水泵一开，管子就输水着。", "corrected_sentence": "夜里水泵一开，管子就输水了。", "error_description": "错误：“一……就”表示动作紧接着完成，完成义要用“了”，“着”表示动作持续，不宜用在这里。正确：“输水了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11f4889c-b619-43f4-885a-c7a5a833fda1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25280, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条老管道以前输水过。", "corrected_sentence": "这条老管道以前输过水。", "error_description": "错误：经历体“过”位置错误，应紧跟动词。正确：“输过水”，“过”要放在动词“输”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11f4889c-b619-43f4-885a-c7a5a833fda1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
