INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25282, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "用很少的电就能工作。", "primary_collocate": null, "pronunciation": "dī néng hào", "ipa": "ti˥ nɤŋ˧˥ xaʊ˥˩", "syllable_count": 3, "sentences": [{"text": "这盏小灯很省电，是低能耗的。", "target_word": "低能耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台低能耗风扇一晚上只用一度电。", "target_word": "低能耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈买了一个低能耗的电饭锅。", "target_word": "低能耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "低能耗电视一个月电费很少。", "target_word": "低能耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种低能耗灯泡可以用很久。", "target_word": "低能耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想换一台低能耗的洗衣机。", "target_word": "低能耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "低能耗的小冰箱适合放在宿舍里。", "target_word": "低能耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器是低能耗的，电费很便宜。", "target_word": "低能耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校给教室装了低能耗灯。", "target_word": "低能耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "低能耗的电脑不会让电费变高。", "target_word": "低能耗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "电器工作时只用很少的电", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae977bd1-2422-4850-971e-89db1614974a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25282, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "低能耗", "is_correct": true, "explanation": "低能耗：说小灯耗电少，与“很省电”一致。"}, {"text": "高耗能", "is_correct": false, "explanation": "语义：“高耗能”指耗能多，与“很省电”矛盾。"}, {"text": "高功率", "is_correct": false, "explanation": "语义：“高功率”指用电功率大，与前面的“很省电”矛盾。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：灯不发出声音，“吵闹”与“小灯”的特点不合。"}], "explanations": {"低能耗": "低能耗：说小灯耗电少，与“很省电”一致。", "高耗能": "语义：“高耗能”指耗能多，与“很省电”矛盾。", "高功率": "语义：“高功率”指用电功率大，与前面的“很省电”矛盾。", "吵闹": "语义：灯不发出声音，“吵闹”与“小灯”的特点不合。"}, "sentence_index": 0, "correct_answer": "低能耗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的月薪很低能耗，只能勉强生活。", "explanation": "这里应该用〈少〉。低能耗只说设备耗电少，不能用来形容收入；收入少要说“月薪很少”。"}, {"text": "这双鞋很低能耗，穿了三年还很好。", "explanation": "这里应该用〈耐穿〉。低能耗只说设备耗电少，不能用来形容鞋的耐用程度。"}, {"text": "这位工人很低能耗，一小时能做两百个零件。", "explanation": "这里应该用〈高效〉。低能耗说设备耗电少，不能用来形容人的工作效率；说工人干活快要用“效率很高”或“高效”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25282, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "低能耗", "is_correct": true, "explanation": "低能耗：修饰“小冰箱”，说耗电少，符合宿舍用电条件。"}, {"text": "大型", "is_correct": false, "explanation": "语义：“大型”与“小冰箱”矛盾，也不适合放在宿舍。"}, {"text": "耗电", "is_correct": false, "explanation": "语义：耗电多，与“适合放在宿舍里”的省电要求相反。"}, {"text": "嘈杂", "is_correct": false, "explanation": "语义：“嘈杂”形容声音吵，与“适合放在宿舍”的安静环境相反。"}], "explanations": {"低能耗": "低能耗：修饰“小冰箱”，说耗电少，符合宿舍用电条件。", "大型": "语义：“大型”与“小冰箱”矛盾，也不适合放在宿舍。", "耗电": "语义：耗电多，与“适合放在宿舍里”的省电要求相反。", "嘈杂": "语义：“嘈杂”形容声音吵，与“适合放在宿舍”的安静环境相反。"}, "sentence_index": 6, "correct_answer": "低能耗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影很低能耗，看完很感动。", "explanation": "这里应该用〈精彩〉。低能耗只说设备耗电少，不能用来评价电影的好坏。"}, {"text": "他的作文写得很低能耗，老师看了很满意。", "explanation": "这里应该用〈生动〉。低能耗只说设备耗电少，不能用来评价作文的文采；作文好要说“写得很生动”。"}, {"text": "这条河的水很低能耗，流得很慢。", "explanation": "这里应该用〈缓慢〉。低能耗只说设备耗电少，不能用来形容水流的快慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25282, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想给家里换一台低能耗地洗衣机。", "corrected_sentence": "我想给家里换一台低能耗的洗衣机。", "error_description": "“低能耗”修饰名词“洗衣机”时应用定语标记“的”，此处误用状语标记“地”。应说“一台低能耗的洗衣机”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25282, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器是低能耗地，所以电费很便宜。", "corrected_sentence": "这台机器是低能耗的，所以电费很便宜。", "error_description": "错误：用了“地”。“低能耗”在“是……的”结构里作谓语，句末要用“的”，不能用状语标记“地”。应说“是低能耗的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
