INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25284, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "一直到某个时候或某件事发生。", "primary_collocate": null, "pronunciation": "zhí zhì", "ipa": "ʈʂɻ³⁵ ʈʂɻ⁵¹", "syllable_count": 2, "sentences": [{"text": "他一直工作，直至深夜。", "target_word": "直至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "直至今天，我还记得那件事。", "target_word": "直至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨下了很久，直至天黑才停。", "target_word": "直至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在这里等，直至老师来。", "target_word": "直至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "直至去年，他都住在北京。", "target_word": "直至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛一直进行，直至晚上九点。", "target_word": "直至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她哭了很久，直至睡着。", "target_word": "直至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "直至现在，我们还没有他的消息。", "target_word": "直至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子玩到很晚，直至妈妈叫他回家。", "target_word": "直至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "直至考试结束，没有人说话。", "target_word": "直至", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "表示动作持续到某个时间点或事件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fe847b-453c-49ae-ad59-f1b51c9b852b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25284, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "直至", "is_correct": true, "explanation": "正确：「直至」表示动作持续到某个时间点，与“深夜”搭配，符合句意。"}, {"text": "向", "is_correct": false, "explanation": "语义：「向」引出方向，“工作到深夜”表示持续到时间点，不是方向。"}, {"text": "对", "is_correct": false, "explanation": "搭配：「对」引出对象，“对深夜”不能作为动作的对象。"}, {"text": "替", "is_correct": false, "explanation": "配价：「替」需要受益的人作宾语，“深夜”不能作受益对象。"}], "explanations": {"直至": "正确：「直至」表示动作持续到某个时间点，与“深夜”搭配，符合句意。", "向": "语义：「向」引出方向，“工作到深夜”表示持续到时间点，不是方向。", "对": "搭配：「对」引出对象，“对深夜”不能作为动作的对象。", "替": "配价：「替」需要受益的人作宾语，“深夜”不能作受益对象。"}, "sentence_index": 0, "correct_answer": "直至"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一敲门，直至门就开了。", "explanation": "语义：这里把“直至”当成了“马上、立即”的意思。“直至”表示一直持续到某个终点，不能表示动作紧接着发生。"}, {"text": "直至他的成绩，我不清楚。", "explanation": "这里应该用〈至于〉。〈至于〉用来引出另一个话题，“直至”表示持续到某个终点，不能引出话题。"}, {"text": "直至天还没黑，我们赶路。", "explanation": "这里应该用〈趁着〉。“趁着”表示利用某个时机，“直至”表示持续到某个终点，不能表示趁机做事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25284, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "直至", "is_correct": true, "explanation": "正确：「直至」表示动作持续到某个结果，与“睡着”搭配，符合句意。"}, {"text": "从", "is_correct": false, "explanation": "语义：「从」表示起点，“从睡着”没有明确的起点，不符合句意。"}, {"text": "把", "is_correct": false, "explanation": "配价：「把」需要被处置的宾语，“把睡着”不成立。"}, {"text": "朝", "is_correct": false, "explanation": "语义：「朝」引出方向，“睡着”不是方向。"}], "explanations": {"直至": "正确：「直至」表示动作持续到某个结果，与“睡着”搭配，符合句意。", "从": "语义：「从」表示起点，“从睡着”没有明确的起点，不符合句意。", "把": "配价：「把」需要被处置的宾语，“把睡着”不成立。", "朝": "语义：「朝」引出方向，“睡着”不是方向。"}, "sentence_index": 6, "correct_answer": "直至"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直住在北京，直至上海。", "explanation": "语义：前句说“一直住在北京”，后句“直至上海”前后矛盾；若要表示搬去上海，应直接说“搬到上海”。"}, {"text": "直至三天的努力，他成功了。", "explanation": "这里应该用〈经过〉。“经过”用来引出一段过程，“直至”表示持续到某个终点，不能用来引出过程。"}, {"text": "直至旅行期间，他一直很开心。", "explanation": "这里应该用〈在……期间〉。“在……期间”表示一段时间之内，“直至”表示持续到某个终点，不能用来指一段时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25284, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨下了一夜，直至在天亮。", "corrected_sentence": "雨下了一夜，直至天亮。", "error_description": "介词误用：“直至”是介词，后面直接接时间词“天亮”，不能再加介词“在”，应说“直至天亮”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25284, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们吵了很久，直至到深夜。", "corrected_sentence": "他们吵了很久，直至深夜。", "error_description": "成分多余：“直至”本身就是“一直到”的意思，后面不能再加“到”，应说“直至深夜”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
