INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25286, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西藏在里面，还没有被发现。", "primary_collocate": null, "pronunciation": "yùn cáng", "ipa": "ɥn˥˩ tsʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这座山里蕴藏着很多宝石。", "target_word": "蕴藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海底蕴藏着许多还没发现的东西。", "target_word": "蕴藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块岩层深处蕴藏着很多水。", "target_word": "蕴藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心里蕴藏着一个小秘密。", "target_word": "蕴藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片土地蕴藏着很多煤，还没人挖。", "target_word": "蕴藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老房子里可能蕴藏着不少旧东西。", "target_word": "蕴藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "深山里蕴藏着一种少见的药草。", "target_word": "蕴藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小岛蕴藏了很多石油。", "target_word": "蕴藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子身上蕴藏着很大的力量。", "target_word": "蕴藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大海深处蕴藏着许多秘密。", "target_word": "蕴藏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "蕴藏着", "label": "体标"}, {"form": "蕴藏了", "label": "体标"}, {"form": "蘊藏", "label": "繁体"}], "register": "通用", "sense_fingerprint": "东西藏在里面还没被发现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae977bd1-2422-4850-971e-89db1614974a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25286, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蕴藏", "is_correct": true, "explanation": "蕴藏指东西藏在里面，与“这座山里”的存在义相合。"}, {"text": "播种", "is_correct": false, "explanation": "语义：播种指撒种子，与山里藏着宝石的含义无关。"}, {"text": "行走", "is_correct": false, "explanation": "搭配：“行走”的主语是人或动物，不能与宝石搭配。"}, {"text": "洗刷", "is_correct": false, "explanation": "语义：洗刷指冲洗擦拭，与山里藏着宝石的含义不符。"}], "explanations": {"蕴藏": "蕴藏指东西藏在里面，与“这座山里”的存在义相合。", "播种": "语义：播种指撒种子，与山里藏着宝石的含义无关。", "行走": "搭配：“行走”的主语是人或动物，不能与宝石搭配。", "洗刷": "语义：洗刷指冲洗擦拭，与山里藏着宝石的含义不符。"}, "sentence_index": 0, "correct_answer": "蕴藏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子把糖果蕴藏在枕头下面。", "explanation": "这里应该用〈隐藏〉。蕴藏指东西本身藏在里面，不指人有意把东西藏起来。"}, {"text": "她喜欢蕴藏老照片。", "explanation": "这里应该用〈收藏〉。蕴藏指东西本身藏在里面，不能表示主动搜集保存。"}, {"text": "这个箱子里蕴藏满了棉花。", "explanation": "这里应该用〈填满〉。蕴藏强调东西藏在内部、尚未被发现，不能表示用东西把空间占满。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25286, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蕴藏", "is_correct": true, "explanation": "蕴藏指东西藏在里面，与“深山里”搭配，表示深山中存在某物。"}, {"text": "缴纳", "is_correct": false, "explanation": "搭配：“缴纳”的对象是税费等，不能与药草搭配。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：拆除是拆掉建筑或设施，与深山里的药草不相容。"}, {"text": "打磨", "is_correct": false, "explanation": "语义：打磨是使物体表面光滑，与药草的存在义不符。"}], "explanations": {"蕴藏": "蕴藏指东西藏在里面，与“深山里”搭配，表示深山中存在某物。", "缴纳": "搭配：“缴纳”的对象是税费等，不能与药草搭配。", "拆除": "语义：拆除是拆掉建筑或设施，与深山里的药草不相容。", "打磨": "语义：打磨是使物体表面光滑，与药草的存在义不符。"}, "sentence_index": 6, "correct_answer": "蕴藏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把花生蕴藏进袋子里。", "explanation": "这里应该用〈装〉。蕴藏指东西藏在里面，把东西盛入袋子要用装。"}, {"text": "这个方案蕴藏三个步骤。", "explanation": "这里应该用〈包括〉。蕴藏指藏在内部、尚未显露的东西，方案的组成部分要用包括。"}, {"text": "墙上蕴藏着一幅画。", "explanation": "这里应该用〈挂〉。蕴藏指东西藏在里面，挂在墙上的物品要用挂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25286, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座山的深处蕴藏着了很多宝石。", "corrected_sentence": "这座山的深处蕴藏着很多宝石。", "error_description": "错误：“蕴藏着了”。“着”和“了”不能同时用在同一个动词后。正确形式：“蕴藏着很多宝石”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25286, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老城区的地下蕴藏得很多古钱。", "corrected_sentence": "老城区的地下蕴藏着很多古钱。", "error_description": "错误：“蕴藏得很多古钱”。“蕴藏”表示东西藏在地下的状态，状态持续要用“着”，应改为“蕴藏着很多古钱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
