INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25288, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很懂某件事的人。", "primary_collocate": null, "pronunciation": "zhuān jiā", "ipa": "tʂwan˥ tɕja˥", "syllable_count": 2, "sentences": [{"text": "他是研究水稻的专家。", "target_word": "专家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院请了一位专家来看病。", "target_word": "专家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题要问专家。", "target_word": "专家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说，每天走路对身体好。", "target_word": "专家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是教汉语的专家，学生都很喜欢她。", "target_word": "专家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视里有一位专家在讲怎么种菜。", "target_word": "专家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几位专家一起看了这张画。", "target_word": "专家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸是电脑方面的专家。", "target_word": "专家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请专家帮我们看一下这座桥。", "target_word": "专家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学了二十年，现在成了专家。", "target_word": "专家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "专家组", "label": "复合"}], "register": "中性", "sense_fingerprint": "在某一方面有专门知识或经验的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61123057-4989-4a95-82bf-725897152c51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25288, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "老板", "is_correct": false, "explanation": "语义：老板不以研究水稻为身份，与「研究」不搭，句子不通。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：小偷与研究水稻无关，句子说不通。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：「研究」的主体是人，「歌曲」不能作研究者，「研究水稻的歌曲」不成立。"}, {"text": "专家", "is_correct": true, "explanation": "「专家」指在某一领域有专门知识的人，与「研究水稻」相符。"}], "explanations": {"老板": "语义：老板不以研究水稻为身份，与「研究」不搭，句子不通。", "小偷": "语义：小偷与研究水稻无关，句子说不通。", "歌曲": "搭配：「研究」的主体是人，「歌曲」不能作研究者，「研究水稻的歌曲」不成立。", "专家": "「专家」指在某一领域有专门知识的人，与「研究水稻」相符。"}, "sentence_index": 0, "correct_answer": "专家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的专家是医学。", "explanation": "这里应该用〈专业〉。「专家」指有专门知识的人，不能用来说学科，应说「专业是医学」。"}, {"text": "这次会议来了一只专家。", "explanation": "这里应该用〈位〉或〈个〉。「只」用于动物或成对的东西，指人要用「位」。"}, {"text": "这本书写得很专家。", "explanation": "这里应该用〈专业〉。「专家」是名词，指人，不能作形容词说书写得好，应说「写得很专业」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25288, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：桌子是东西，不能看画，句子说不通。"}, {"text": "死者", "is_correct": false, "explanation": "语义：死者无法观看画作，句子不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有眼睛，不能看画，句子说不通。"}, {"text": "专家", "is_correct": true, "explanation": "「几位专家」指几位有专门知识的人，一起鉴赏画作，符合句意。"}], "explanations": {"桌子": "语义：桌子是东西，不能看画，句子说不通。", "死者": "语义：死者无法观看画作，句子不通。", "石头": "语义：石头没有眼睛，不能看画，句子说不通。", "专家": "「几位专家」指几位有专门知识的人，一起鉴赏画作，符合句意。"}, "sentence_index": 6, "correct_answer": "专家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑是一位专家。", "explanation": "这里应该用〈设备〉。「专家」指有专门知识的人，不能用来指称电脑这类物品。"}, {"text": "这次考试考了很多专家。", "explanation": "这里应该用〈知识〉。「考」考的是知识或内容，专家指人，不能作为考试内容。"}, {"text": "他的专家很高。", "explanation": "这里应该用〈水平〉。「专家」指人，不用来说技能的高低，应说「水平很高」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25288, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们请了一只专家来检查机器。", "corrected_sentence": "我们请了一位专家来检查机器。", "error_description": "「专家」指人，量词应用「位」或「个」，「只」用于动物或成对的东西，此处误用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25288, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几位专家们正在讨论这个方案。", "corrected_sentence": "几位专家正在讨论这个方案。", "error_description": "「几位」已表示人数，「们」不能与之同用，应说「几位专家」；单独说「专家们」是正常的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
