INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25294, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb97f0ec-c305-43bc-babc-013c0ba28949') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25294, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不同的东西可以分成不同的组，每组就是一个类型。", "primary_collocate": null, "pronunciation": "lèi xíng", "ipa": "lei˥˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "动物可以分成好几个类型。", "target_word": "类型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这三个类型各有各的特点。", "target_word": "类型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的衣服是哪个类型的？", "target_word": "类型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把练习分成两种类型。", "target_word": "类型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店里的书按类型放在不同的架子上。", "target_word": "类型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些颜色可以分成四个类型。", "target_word": "类型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的汽车属于同一个类型。", "target_word": "类型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先看看这个类型有什么特点。", "target_word": "类型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影的类型太多，我不知道选哪个。", "target_word": "类型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些问题可以归为三个类型。", "target_word": "类型", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "种", "label": "量词"}, {"form": "类型学", "label": "复合"}], "register": "中性", "sense_fingerprint": "把事物分组后，其中的每一组", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f5bb7cc-792b-4587-ac47-b7d173ac9402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25294, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "类型", "is_correct": true, "explanation": "类型：分组后的每一组，与“分成好几个”相合，句意通顺。"}, {"text": "房间", "is_correct": false, "explanation": "语义：动物不能被分成“房间”，句意不通。"}, {"text": "年份", "is_correct": false, "explanation": "语义：“年份”不是分组的单位，句意荒谬。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”应用量词“种”，不能说“几个天气”。"}], "explanations": {"类型": "类型：分组后的每一组，与“分成好几个”相合，句意通顺。", "房间": "语义：动物不能被分成“房间”，句意不通。", "年份": "语义：“年份”不是分组的单位，句意荒谬。", "天气": "搭配：“天气”应用量词“种”，不能说“几个天气”。"}, "sentence_index": 0, "correct_answer": "类型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个班的类型是四十人。", "explanation": "这里应该用〈人数〉。类型指分组后的一组，不能用来表示人的数量。"}, {"text": "这块地的类型很大。", "explanation": "这里应该用〈面积〉。类型不能说大小，表示大小要用面积。"}, {"text": "这根绳子的类型是五米。", "explanation": "这里应该用〈长度〉。类型不能表示长短，应说长度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb97f0ec-c305-43bc-babc-013c0ba28949') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25294, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "类型", "is_correct": true, "explanation": "类型：汽车所属的一组，句意通顺。"}, {"text": "房子", "is_correct": false, "explanation": "语义：汽车不属于“房子”这一类，句意荒谬。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”不是可以归属的分组，汽车不能属于“时间”，句意荒谬。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“同一个年龄”不能用来指车辆所属的分组。"}], "explanations": {"类型": "类型：汽车所属的一组，句意通顺。", "房子": "语义：汽车不属于“房子”这一类，句意荒谬。", "时间": "语义：“时间”不是可以归属的分组，汽车不能属于“时间”，句意荒谬。", "年龄": "搭配：“同一个年龄”不能用来指车辆所属的分组。"}, "sentence_index": 6, "correct_answer": "类型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这箱苹果的类型是十公斤。", "explanation": "这里应该用〈重量〉。类型指种类，表示轻重要用重量。"}, {"text": "这辆车的类型是每小时一百公里。", "explanation": "这里应该用〈速度〉。类型指种类，表示快慢要用速度。"}, {"text": "这台电视的类型是五十寸。", "explanation": "这里应该用〈尺寸〉。类型指种类，表示屏幕大小要用尺寸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb97f0ec-c305-43bc-babc-013c0ba28949') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25294, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这批零件可以分成三只类型。", "corrected_sentence": "这批零件可以分成三种类型。", "error_description": "错误形式：“类型”前用了量词“只”。正确形式：“三种类型”。原因：“只”用于动物等，修饰“类型”应用量词“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb97f0ec-c305-43bc-babc-013c0ba28949') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25294, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些报告可以分成两类型。", "corrected_sentence": "这些报告可以分成两种类型。", "error_description": "错误形式：“类型”前漏掉了量词。正确形式：“两种类型”。原因：数词与“类型”之间需要量词“种”，漏掉后句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb97f0ec-c305-43bc-babc-013c0ba28949') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25296, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25296, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25296, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "利用水来为人们做事，比如浇地、发电。", "primary_collocate": null, "pronunciation": "shuǐ lì", "ipa": "ʂweɪ̯˨˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "这个地方的水利很好，田里不缺水。", "target_word": "水利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里重视水利，今年不怕干旱。", "target_word": "水利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水利可以浇地，也可以发电。", "target_word": "水利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片地靠水利灌溉，年年都有好收成。", "target_word": "水利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边搞好了水利，帮农民解决了大问题。", "target_word": "水利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河有很好的水利条件。", "target_word": "水利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山区要发展水利，农民才有水浇地。", "target_word": "水利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年水利搞得好，秋天收了很多粮食。", "target_word": "水利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水利让这片干地变成了好田。", "target_word": "水利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里修好水利以后，粮食产量提高了。", "target_word": "水利", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "水利工程", "label": "复合"}, {"form": "水利设施", "label": "复合"}], "register": "通用", "sense_fingerprint": "用水浇地发电为人做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae977bd1-2422-4850-971e-89db1614974a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25296, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "水利", "is_correct": true, "explanation": "水利：利用水来为人做事，如浇地、发电，是正确答案。"}, {"text": "水里", "is_correct": false, "explanation": "shuǐ lǐ（第三声）与 shuǐ lì（第四声）声调不同，意思是“在水中”。"}, {"text": "税吏", "is_correct": false, "explanation": "shuì lì（第四声）与 shuǐ lì 的第一个音节声调不同，意思是“收税的官吏”。"}, {"text": "水梨", "is_correct": false, "explanation": "shuǐ lí（第二声）与 shuǐ lì 声调不同，意思是一种梨。"}], "explanations": {"水利": "水利：利用水来为人做事，如浇地、发电，是正确答案。", "水里": "shuǐ lǐ（第三声）与 shuǐ lì（第四声）声调不同，意思是“在水中”。", "税吏": "shuì lì（第四声）与 shuǐ lì 的第一个音节声调不同，意思是“收税的官吏”。", "水梨": "shuǐ lí（第二声）与 shuǐ lì 声调不同，意思是一种梨。"}, "sentence_index": null, "correct_answer": "水利"}, "level_3": {"options": [{"text": "水利", "is_correct": true, "explanation": "水利：作主语，指利用水做事的条件，与“田里不缺水”一致。"}, {"text": "干旱", "is_correct": false, "explanation": "语义：“干旱”与“田里不缺水”矛盾，不能说“干旱很好”。"}, {"text": "噪音", "is_correct": false, "explanation": "搭配：“噪音”只能说大小，不能用“很好”来评价。"}, {"text": "洪水", "is_correct": false, "explanation": "语义：“洪水”会淹没农田，与“田里不缺水”的语境相反。"}], "explanations": {"水利": "水利：作主语，指利用水做事的条件，与“田里不缺水”一致。", "干旱": "语义：“干旱”与“田里不缺水”矛盾，不能说“干旱很好”。", "噪音": "搭配：“噪音”只能说大小，不能用“很好”来评价。", "洪水": "语义：“洪水”会淹没农田，与“田里不缺水”的语境相反。"}, "sentence_index": 0, "correct_answer": "水利"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把伞很水利，下雨天带着很好。", "explanation": "这里应该用〈方便〉。水利指利用水浇地、发电等，不能用来形容伞好不好用。"}, {"text": "这辆汽车靠水利跑得很快。", "explanation": "这里应该用〈发动机〉。水利指利用水浇地、发电等，不能作汽车的动力来源。"}, {"text": "孩子们在水利里游泳，玩得很开心。", "explanation": "这里应该用〈水域〉。水利指利用水做事，不指水的区域，不能说“在水利里游泳”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25296, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水利", "is_correct": true, "explanation": "水利：作“发展”的宾语，指可以发展的水利事业，与“农民才有水浇地”的目的一致。"}, {"text": "荒漠", "is_correct": false, "explanation": "语义：“荒漠”不能作“发展”的对象，与“农民才有水浇地”的目标矛盾。"}, {"text": "灾害", "is_correct": false, "explanation": "搭配：“发展灾害”搭配不当，与“农民才有水浇地”的因果不符。"}, {"text": "洪涝", "is_correct": false, "explanation": "语义：“洪涝”造成水患，与“农民才有水浇地”的目的相反。"}], "explanations": {"水利": "水利：作“发展”的宾语，指可以发展的水利事业，与“农民才有水浇地”的目的一致。", "荒漠": "语义：“荒漠”不能作“发展”的对象，与“农民才有水浇地”的目标矛盾。", "灾害": "搭配：“发展灾害”搭配不当，与“农民才有水浇地”的因果不符。", "洪涝": "语义：“洪涝”造成水患，与“农民才有水浇地”的目的相反。"}, "sentence_index": 6, "correct_answer": "水利"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这段音乐的水利很好，听了很舒服。", "explanation": "这里应该用〈旋律〉。水利指利用水做事，不能用来评价音乐的好坏。"}, {"text": "他的水利很好，每天能跑十公里。", "explanation": "这里应该用〈体力〉。水利指利用水来做事，不能用来形容人的体能。"}, {"text": "这本书的水利很好，我一口气读完了。", "explanation": "这里应该用〈好看〉。水利指利用水做事，不能用来评价书的内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25296, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个村的一把水利很好，田里不缺水。", "corrected_sentence": "这个村的水利很好，田里不缺水。", "error_description": "“水利”前不能加量词“把”，“把”多用于有柄的器具；应去掉“一把”，说“这个村的水利很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25296, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "去年村里的水利搞的好，地里收了很多玉米。", "corrected_sentence": "去年村里的水利搞得好，地里收了很多玉米。", "error_description": "错误：“搞的好”。动词后引出程度补语要用“得”，应为“水利搞得好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21996082-966b-4a1d-9c7d-4ab3fd8ed023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
