INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25302, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个有很多房子和人的小地方。", "primary_collocate": null, "pronunciation": "cūn luò", "ipa": "tsʰwən˥ lwo˥˩", "syllable_count": 2, "sentences": [{"text": "河边的这个村落里房子很多，住着几百位村民。", "target_word": "村落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出生在山里的一个村落。", "target_word": "村落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个村落离城市很远，坐车要三个小时。", "target_word": "村落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在村落里住了两天。", "target_word": "村落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村落中间有一棵很大的树。", "target_word": "村落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天，整个村落开满了花。", "target_word": "村落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人们坐在村落的入口聊天。", "target_word": "村落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村落里有一所小学。", "target_word": "村落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客来到村落，看到了传统的房子。", "target_word": "村落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村落里的路很窄，汽车进不去。", "target_word": "村落", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "书面", "sense_fingerprint": "有房子有人居住的小地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e653b9f-1786-4a98-96fa-5c2fd7ba68c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25302, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公园", "is_correct": false, "explanation": "语义：“公园”是供人游玩的场所，不是居民居住的地方，与“住着几百位村民”冲突。"}, {"text": "村落", "is_correct": true, "explanation": "“村落”是人们居住的小地方，有房子也有村民，与句意相符。"}, {"text": "工地", "is_correct": false, "explanation": "语义：工地是施工的场所，不住村民，与“住着几百位村民”冲突。"}, {"text": "学校", "is_correct": false, "explanation": "搭配：“住着……村民”说的是居民点，学校不是供村民居住的地方，二者搭配不通。"}], "explanations": {"公园": "语义：“公园”是供人游玩的场所，不是居民居住的地方，与“住着几百位村民”冲突。", "村落": "“村落”是人们居住的小地方，有房子也有村民，与句意相符。", "工地": "语义：工地是施工的场所，不住村民，与“住着几百位村民”冲突。", "学校": "搭配：“住着……村民”说的是居民点，学校不是供村民居住的地方，二者搭配不通。"}, "sentence_index": 0, "correct_answer": "村落"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把村落装进了书包里带走了。", "explanation": "这里应该用〈地图〉。村落是有很多房子和人的地方，装不进书包；地图才能折起来放进包里。"}, {"text": "我每天早上喝一杯村落。", "explanation": "这里应该用〈牛奶〉。村落是有房子和人的地方，不能喝。"}, {"text": "我用这个村落在电脑上打字。", "explanation": "这里应该用〈键盘〉。村落是地方，不能用来打字，打字要用键盘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25302, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手机", "is_correct": false, "explanation": "语义：“手机”是通讯工具，不是有入口、可以让老人坐在旁边的地方，句意冲突。"}, {"text": "村落", "is_correct": true, "explanation": "“村落”是有入口的聚居地，老人坐在入口聊天，与句意相符。"}, {"text": "电影", "is_correct": false, "explanation": "语义：“电影”是影片，不是有入口的场所，与“坐在……的入口聊天”冲突。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“入口”指空间上的出入处，“歌曲”不是地点，不能说“歌曲的入口”。"}], "explanations": {"手机": "语义：“手机”是通讯工具，不是有入口、可以让老人坐在旁边的地方，句意冲突。", "村落": "“村落”是有入口的聚居地，老人坐在入口聊天，与句意相符。", "电影": "语义：“电影”是影片，不是有入口的场所，与“坐在……的入口聊天”冲突。", "歌曲": "搭配：“入口”指空间上的出入处，“歌曲”不是地点，不能说“歌曲的入口”。"}, "sentence_index": 6, "correct_answer": "村落"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只村落我去过三次。", "explanation": "这里应该用〈个〉。“只”多用于动物或成对的东西，村落应用量词“个”。"}, {"text": "这张村落很安静。", "explanation": "这里应该用〈个〉。“张”用于纸、桌子等平面的东西，村落应用量词“个”。"}, {"text": "这把村落很大，我走了半天。", "explanation": "这里应该用〈个〉。“把”用于有柄或可以握住的东西，村落应用量词“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25302, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在山里找到了一个村落们。", "corrected_sentence": "我们在山里找到了一个村落。", "error_description": "“们”只用于指人的名词，“村落”指地方，不能加“们”，应说“一个村落”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25302, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在一棵偏远的村落里待了一周。", "corrected_sentence": "我在一个偏远的村落里待了一周。", "error_description": "量词错误：“棵”用于树木等植物，“村落”应该用量词“个”，应说“一个偏远的村落”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
