INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25304, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "意思是“叫做”或“说是”。", "primary_collocate": null, "pronunciation": "chēng wéi", "ipa": "ʈʂʰɤŋ˥ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "这样的好人，可以称为“英雄”。", "target_word": "称为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个人走三天山路，可以称为“勇士”。", "target_word": "称为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书很有名，大家把它称为“经典”。", "target_word": "称为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水变成冰，这个过程称为“结冰”。", "target_word": "称为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "能听懂三种语言的人，可称为“语言高手”。", "target_word": "称为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样的朋友，称为“知己”也不过分。", "target_word": "称为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑里存的东西，我们称为“文件”。", "target_word": "称为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳升起的时候，这种景象可以称为“日出”。", "target_word": "称为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有一百年历史的老房子，可称为“古宅”。", "target_word": "称为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样的好天气，可以称为“秋高气爽”。", "target_word": "称为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "被称为", "label": "被动结构"}], "register": "中性", "sense_fingerprint": "称为：叫做、可以说是，用于下定义或作评价", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0381dfef-69c6-44e2-9d5e-c57aefd613e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25304, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "称为", "is_correct": true, "explanation": "正确答案，读作 chēng wéi，指叫做或可以说是某种名称。"}, {"text": "成为", "is_correct": false, "explanation": "chéng（第二声）与 chēng（第一声）声调不同，意思是变成。"}, {"text": "升为", "is_correct": false, "explanation": "shēng 与 chēng 声母不同（sh 与 ch），意思是提升为某个职位。"}, {"text": "称谓", "is_correct": false, "explanation": "wèi（第四声）与 wéi（第二声）声调不同，意思是称呼。"}], "explanations": {"称为": "正确答案，读作 chēng wéi，指叫做或可以说是某种名称。", "成为": "chéng（第二声）与 chēng（第一声）声调不同，意思是变成。", "升为": "shēng 与 chēng 声母不同（sh 与 ch），意思是提升为某个职位。", "称谓": "wèi（第四声）与 wéi（第二声）声调不同，意思是称呼。"}, "sentence_index": null, "correct_answer": "称为"}, "level_3": {"options": [{"text": "称为", "is_correct": true, "explanation": "正确答案。“这样的好人，可以称为“英雄””表示可以说是英雄。"}, {"text": "嫌弃", "is_correct": false, "explanation": "语义：“嫌弃”是厌烦、不喜欢，与对好人的赞美语境矛盾。"}, {"text": "起诉", "is_correct": false, "explanation": "搭配：“起诉”用于告发犯罪的人，不能用于称赞英雄。"}, {"text": "判决", "is_correct": false, "explanation": "搭配：“判决”用于法院的裁决，不用于评价人的品格。"}], "explanations": {"称为": "正确答案。“这样的好人，可以称为“英雄””表示可以说是英雄。", "嫌弃": "语义：“嫌弃”是厌烦、不喜欢，与对好人的赞美语境矛盾。", "起诉": "搭配：“起诉”用于告发犯罪的人，不能用于称赞英雄。", "判决": "搭配：“判决”用于法院的裁决，不用于评价人的品格。"}, "sentence_index": 0, "correct_answer": "称为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试他被称为九十分。", "explanation": "这里应该用〈得〉。“称为”表示起名，考试成绩要说“得”，不能用“被称为”。"}, {"text": "这份工资被称为一百元。", "explanation": "这里应该用〈定为〉。金额、数额要说定为，称为只表示给事物起名。"}, {"text": "他的身高被称为一米八。", "explanation": "这里应该用〈达到〉。身高这类数值要说达到，称为不能用来表示数量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25304, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "称为", "is_correct": true, "explanation": "正确答案。“我们称为“文件””指给电脑里存的东西起名，与句意一致。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：“烹饪”指做菜，电脑里的东西不能烹饪。"}, {"text": "种植", "is_correct": false, "explanation": "语义：“种植”指栽培植物，与电脑里存的东西毫不相干。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：“饲养”用于动物，不能用于文件。"}], "explanations": {"称为": "正确答案。“我们称为“文件””指给电脑里存的东西起名，与句意一致。", "烹饪": "语义：“烹饪”指做菜，电脑里的东西不能烹饪。", "种植": "语义：“种植”指栽培植物，与电脑里存的东西毫不相干。", "饲养": "搭配：“饲养”用于动物，不能用于文件。"}, "sentence_index": 6, "correct_answer": "称为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这袋面粉被称为五斤。", "explanation": "这里应该用〈重〉。说重量要说“重五斤”，称为只表示叫做某个名称，不能表示重量。"}, {"text": "这桶水被称为五十升。", "explanation": "这里应该用〈有〉。说容量要说“有五十升”，称为只表示叫做某个名称，不能表示容量。"}, {"text": "这张桌子被称为三米长。", "explanation": "这里应该用〈有〉。长度要说有，称为表示叫做某个名称，不能表示数量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25304, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种现象可以称为了“回声”。", "corrected_sentence": "这种现象可以称为“回声”。", "error_description": "“了”不能插在动词“称为”与宾语之间，“称为”后应直接接宾语。这里误加“了”，正确形式为“可以称为“回声””。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25304, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种景象被称为为“海市蜃楼”。", "corrected_sentence": "这种景象被称为“海市蜃楼”。", "error_description": "“被称为”中已经包含“为”，多加一个“为”是错误的，应删去，正确形式为“被称为”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
