INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25308, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水官是古代管水、管河的大官。", "primary_collocate": null, "pronunciation": "shuǐ guān", "ipa": "ʂweɪ˨˩˦ kwan˥", "syllable_count": 2, "sentences": [{"text": "古代的水官是管河的大官。", "target_word": "水官", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位水官的官很大，管着许多河。", "target_word": "水官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说爷爷的爷爷当过水官。", "target_word": "水官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水官的家里有很多关于河的书。", "target_word": "水官", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有一年大水来了，水官一夜没睡。", "target_word": "水官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝很相信这位水官。", "target_word": "水官", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那个水官带人在河边挖了一条水渠。", "target_word": "水官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在书里读到过一位水官的故事。", "target_word": "水官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水官为了管好河，常常住在河边。", "target_word": "水官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家叫他水官，因为他管着全城的水。", "target_word": "水官", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}], "register": "书面", "sense_fingerprint": "水官：古代管水、管河的大官", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0381dfef-69c6-44e2-9d5e-c57aefd613e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25308, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "水官", "is_correct": true, "explanation": "正确答案。shuǐ guān 指古代管水、管河的大官。"}, {"text": "税官", "is_correct": false, "explanation": "shuì（第四声）与 shuǐ（第三声）声调不同，意思是收税的官员。"}, {"text": "水管", "is_correct": false, "explanation": "guǎn（第三声）与 guān（第一声）声调不同，意思是输水的管道。"}, {"text": "水光", "is_correct": false, "explanation": "guāng 与 guān 韵母不同（ang 与 an），意思是水面反射的光。"}], "explanations": {"水官": "正确答案。shuǐ guān 指古代管水、管河的大官。", "税官": "shuì（第四声）与 shuǐ（第三声）声调不同，意思是收税的官员。", "水管": "guǎn（第三声）与 guān（第一声）声调不同，意思是输水的管道。", "水光": "guāng 与 guān 韵母不同（ang 与 an），意思是水面反射的光。"}, "sentence_index": null, "correct_answer": "水官"}, "level_3": {"options": [{"text": "水官", "is_correct": true, "explanation": "正确。句中指管河的大官。"}, {"text": "水手", "is_correct": false, "explanation": "语义：水手是船上干活的人，不是管河的大官。"}, {"text": "水利局", "is_correct": false, "explanation": "语域：水利局是现代机关的名称，与“古代”的语境不符。"}, {"text": "水工", "is_correct": false, "explanation": "语义：水工是普通的劳力，不是大官。"}], "explanations": {"水官": "正确。句中指管河的大官。", "水手": "语义：水手是船上干活的人，不是管河的大官。", "水利局": "语域：水利局是现代机关的名称，与“古代”的语境不符。", "水工": "语义：水工是普通的劳力，不是大官。"}, "sentence_index": 0, "correct_answer": "水官"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我姐姐在医院当水官，每天给病人打针。", "explanation": "这里应该用〈护士〉。“水官”是古代管水的大官，不能用来指现代医院里的护士。"}, {"text": "水官负责治理一县的治安和税收。", "explanation": "这里应该用〈县令〉。水官只管水利和河道，不管治安和税收。"}, {"text": "我在河边遇见一辆水官。", "explanation": "这里应该用量词〈位〉。水官指人，“辆”只用于车辆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25308, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水官", "is_correct": true, "explanation": "正确。“带人在河边挖渠”需要由人来带领，水官符合。"}, {"text": "水车", "is_correct": false, "explanation": "语义：水车是器械，不能带人挖渠。"}, {"text": "水渠", "is_correct": false, "explanation": "配价：“带人”需要有施事者，水渠不能带人挖渠。"}, {"text": "河道", "is_correct": false, "explanation": "搭配：河道是地理事物，“带人”的主语应是人。"}], "explanations": {"水官": "正确。“带人在河边挖渠”需要由人来带领，水官符合。", "水车": "语义：水车是器械，不能带人挖渠。", "水渠": "配价：“带人”需要有施事者，水渠不能带人挖渠。", "河道": "搭配：河道是地理事物，“带人”的主语应是人。"}, "sentence_index": 6, "correct_answer": "水官"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他年轻时在远洋货轮上当水官，常年在海上漂泊。", "explanation": "这里应该用〈水手〉。“水官”是古代管水利的大官，不能用来指船上的水手。"}, {"text": "厨房的水官坏了，地上都是水。", "explanation": "这里应该用〈水管〉。“水官”是古代管水的官员，输水的管子要说水管。"}, {"text": "水官每年都要检查各地的赋税。", "explanation": "这里应该用〈巡抚〉。水官只管河道和水利，不管各地赋税。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25308, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一只很有经验的水官。", "corrected_sentence": "他是一位很有经验的水官。", "error_description": "量词错误：“水官”指人，应用量词“位”，不能用“只”。错误只在量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25308, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他当了过十年水官，管着全县的河。", "corrected_sentence": "他当过十年水官，管着全县的河。", "error_description": "体貌错误：“当过”表示曾经担任过某职务，“了”与“过”不能同时使用，应去掉“了”，即“当过”，不能说“当了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
