INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25312, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25312, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让事情可以买卖，变成商品。", "primary_collocate": null, "pronunciation": "shì chǎng huà", "ipa": "ʂɻ̩˥˩ tʂʰɑŋ˨˩˦ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "有些人想把水资源市场化，让水也能卖钱。", "target_word": "市场化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市把公共停车位市场化了，现在要收费。", "target_word": "市场化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，不是所有东西都能市场化。", "target_word": "市场化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想把音乐课程市场化，让学生自己付钱。", "target_word": "市场化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把自己的故事市场化，写成书卖钱。", "target_word": "市场化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把古村的文化市场化，当地人很不满意。", "target_word": "市场化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校食堂市场化以后，饭菜价格变了。", "target_word": "市场化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家把电力市场化了，电可以自由买卖。", "target_word": "市场化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他反对把爱情市场化，爱不能买卖。", "target_word": "市场化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府不想把土地完全市场化，怕价格太高。", "target_word": "市场化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "市場化", "label": "繁体"}, {"form": "市场化了", "label": "体标"}], "register": "中性", "sense_fingerprint": "市场化|动词|让事物可以买卖、变成商品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0381dfef-69c6-44e2-9d5e-c57aefd613e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25312, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "市场化", "is_correct": true, "explanation": "正确。“想把水资源市场化，让水也能卖钱”中，动词应表示使事物变成商品。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“保护”与“让水也能卖钱”的意图不符，句意说不通。"}, {"text": "污染", "is_correct": false, "explanation": "语义：“污染”会降低水的价值，与“让水也能卖钱”的意图相反。"}, {"text": "节约", "is_correct": false, "explanation": "搭配：“节约”不能带出“让水也能卖钱”这样的结果，搭配不当。"}], "explanations": {"市场化": "正确。“想把水资源市场化，让水也能卖钱”中，动词应表示使事物变成商品。", "保护": "语义：“保护”与“让水也能卖钱”的意图不符，句意说不通。", "污染": "语义：“污染”会降低水的价值，与“让水也能卖钱”的意图相反。", "节约": "搭配：“节约”不能带出“让水也能卖钱”这样的结果，搭配不当。"}, "sentence_index": 0, "correct_answer": "市场化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把日记市场化了，贴在学校的墙上让大家看。", "explanation": "这里应该用〈公开〉。“市场化”指使事物可以买卖，把日记贴出来给大家看是公开，不是买卖。"}, {"text": "他把旧书市场化给了图书馆，一分钱也没要。", "explanation": "这里应该用〈捐〉。“市场化”指使事物可以买卖，把书免费给图书馆是捐，不是买卖。"}, {"text": "两家公司在这里市场化股票，每天都很热闹。", "explanation": "这里应该用〈交易〉。股票本来就可以买卖，不需要“市场化”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25312, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "市场化", "is_correct": true, "explanation": "正确。“学校食堂市场化以后，饭菜价格变了”说的是食堂改为市场运作后的变化。"}, {"text": "关闭", "is_correct": false, "explanation": "语义：食堂关闭后就没有饭菜，“饭菜价格变了”说不通。"}, {"text": "倒闭", "is_correct": false, "explanation": "语义：食堂倒闭后同样没有饭菜，句中“饭菜价格变了”不成立。"}, {"text": "禁止", "is_correct": false, "explanation": "配价：“禁止”需要带出被禁止的对象，“学校食堂禁止以后”的结构不完整。"}], "explanations": {"市场化": "正确。“学校食堂市场化以后，饭菜价格变了”说的是食堂改为市场运作后的变化。", "关闭": "语义：食堂关闭后就没有饭菜，“饭菜价格变了”说不通。", "倒闭": "语义：食堂倒闭后同样没有饭菜，句中“饭菜价格变了”不成立。", "禁止": "配价：“禁止”需要带出被禁止的对象，“学校食堂禁止以后”的结构不完整。"}, "sentence_index": 6, "correct_answer": "市场化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府把煤矿市场化了，工人变成了国家员工。", "explanation": "这里应该用〈国有化〉。市场化是让事物进入买卖，不是收归国家所有。"}, {"text": "政府把公园市场化给所有人，不收门票。", "explanation": "这里应该用〈开放〉。“市场化”指使事物可以买卖，与不收门票、免费向所有人开放的意思相反。"}, {"text": "妈妈把家里的老照片市场化了，给每个孩子留一张。", "explanation": "这里应该用〈赠送〉。“市场化”指使事物可以买卖，与留给孩子、不卖的意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25312, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校去年把体育课市场化着，现在上课要交钱。", "corrected_sentence": "学校去年把体育课市场化了，现在上课要交钱。", "error_description": "体标误用：“市场化”表示已完成的变化，应用“了”，不能用表示持续的“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25312, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个城市曾经把水厂市场化了过。", "corrected_sentence": "这个城市曾经把水厂市场化过。", "error_description": "“了”与“过”不能同时使用：表示曾经经历过时用“市场化过”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
