INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25322, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大家心里想的都一样。", "primary_collocate": null, "pronunciation": "gòng shí", "ipa": "kʊŋ˥˩ ʂʅ˧˥", "syllable_count": 2, "sentences": [{"text": "大家终于达成了共识。", "target_word": "共识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国领导人在会上取得了共识。", "target_word": "共识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护环境已经是社会的共识。", "target_word": "共识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们对这件事还没有共识。", "target_word": "共识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会的目的是让大家有共识。", "target_word": "共识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在孩子的教育问题上，夫妻要有共识。", "target_word": "共识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过三天的讨论，双方形成了共识。", "target_word": "共识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小组成员很快就有了共识。", "target_word": "共识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个共识来之不易。", "target_word": "共识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有共识，计划就没法做下去。", "target_word": "共识", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "共識", "label": "繁体"}], "register": "书面", "sense_fingerprint": "多方经过讨论后形成的共同看法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ab50cd-4340-49f3-b7d1-188a43322068') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25322, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "共识", "is_correct": true, "explanation": "正确：共识 gòng shí，大家的看法一致。"}, {"text": "共事", "is_correct": false, "explanation": "共事 gòng shì：第二个字 shì（第四声）与 shí 声调不同，意思是一起工作。"}, {"text": "工时", "is_correct": false, "explanation": "工时 gōng shí：第一个字 gōng（第一声）与 gòng 声调不同，意思是工作所用的时间。"}, {"text": "公式", "is_correct": false, "explanation": "公式 gōng shì：两个字的声调都与「共识」不同，意思是表示数量关系的式子。"}], "explanations": {"共识": "正确：共识 gòng shí，大家的看法一致。", "共事": "共事 gòng shì：第二个字 shì（第四声）与 shí 声调不同，意思是一起工作。", "工时": "工时 gōng shí：第一个字 gōng（第一声）与 gòng 声调不同，意思是工作所用的时间。", "公式": "公式 gōng shì：两个字的声调都与「共识」不同，意思是表示数量关系的式子。"}, "sentence_index": null, "correct_answer": "共识"}, "level_3": {"options": [{"text": "共识", "is_correct": true, "explanation": "正确：「共识」与「达成」搭配，表示大家达成的共同看法。"}, {"text": "争议", "is_correct": false, "explanation": "搭配：「达成」接协议、共识，不接「争议」作宾语。"}, {"text": "分歧", "is_correct": false, "explanation": "语义：「分歧」指意见不合，与「达成」的一致义相反。"}, {"text": "眼泪", "is_correct": false, "explanation": "搭配：「达成」不接「眼泪」作宾语。"}], "explanations": {"共识": "正确：「共识」与「达成」搭配，表示大家达成的共同看法。", "争议": "搭配：「达成」接协议、共识，不接「争议」作宾语。", "分歧": "语义：「分歧」指意见不合，与「达成」的一致义相反。", "眼泪": "搭配：「达成」不接「眼泪」作宾语。"}, "sentence_index": 0, "correct_answer": "共识"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两国终于喊出了共识。", "explanation": "这里应该用〈口号〉。喊出的是口号或声音，共识要靠讨论后形成，不能喊出。"}, {"text": "我对这件事有自己的共识。", "explanation": "这里应该用〈意见〉。共识是多方形成的共同看法，个人的看法用意见。"}, {"text": "他很快养成了一个共识。", "explanation": "这里应该用〈习惯〉。养成的是习惯、作风，共识是多人讨论后形成的看法，不能养成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25322, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共识", "is_correct": true, "explanation": "正确：「共识」与「形成」搭配，表示双方形成的共同看法。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：「冰箱」是家用电器，不能被「形成」。"}, {"text": "篮球", "is_correct": false, "explanation": "语义：「篮球」是体育用品，与讨论的结果无关。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：「形成」接结论、习惯等，不接「脚步」。"}], "explanations": {"共识": "正确：「共识」与「形成」搭配，表示双方形成的共同看法。", "冰箱": "语义：「冰箱」是家用电器，不能被「形成」。", "篮球": "语义：「篮球」是体育用品，与讨论的结果无关。", "脚步": "搭配：「形成」接结论、习惯等，不接「脚步」。"}, "sentence_index": 6, "correct_answer": "共识"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他过上了充实的共识。", "explanation": "这里应该用〈生活〉。过的是生活，共识是讨论后大家的共同看法，不能用过。"}, {"text": "他发明了一个共识。", "explanation": "这里应该用〈方法〉。发明的是物品或方法，共识要靠讨论后形成，不能发明。"}, {"text": "他对成功发出了共识。", "explanation": "这里应该用〈信号〉。发出的是信号或指令，共识要靠多人讨论形成，不能发出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25322, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家对这个问题很共识。", "corrected_sentence": "大家对这个问题很有共识。", "error_description": "错误：「很共识」。正确：「很有共识」。「共识」是名词，不能直接受程度副词「很」修饰，要说「很有共识」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25322, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天的会议要形成了共识。", "corrected_sentence": "明天的会议要形成共识。", "error_description": "错误：「要形成了共识」。正确：「要形成共识」。「要」表示将来，动词后面不能加「了」表示完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
