INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25326, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "能慢慢习惯新环境的能力。", "primary_collocate": null, "pronunciation": "shì yìng xìng", "ipa": "ʂɻ̩˥˩ iŋ˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "他的适应性很强，很快就习惯了新学校。", "target_word": "适应性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子的适应性比老人强。", "target_word": "适应性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国留学需要很强的适应性。", "target_word": "适应性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫的适应性不好，搬家后几天不吃东西。", "target_word": "适应性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她换了工作，适应性好，一周就熟悉了。", "target_word": "适应性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新员工的适应性，经理每个月都会看。", "target_word": "适应性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在高原要有适应性，身体要慢慢习惯。", "target_word": "适应性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条狗的适应性很好，换了新家也不怕。", "target_word": "适应性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长大以后，我的适应性变差了，不爱换环境。", "target_word": "适应性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先看看孩子对新班级的适应性怎么样。", "target_word": "适应性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "适应性训练", "label": "复合"}, {"form": "適應性", "label": "繁体"}], "register": "中性", "sense_fingerprint": "适应性|名词|慢慢习惯新环境的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0381dfef-69c6-44e2-9d5e-c57aefd613e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25326, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "适应性", "is_correct": true, "explanation": "正确：“适应性”指慢慢习惯新环境的能力，与“很快就习惯了新学校”相合。"}, {"text": "腐蚀性", "is_correct": false, "explanation": "搭配：“腐蚀性”多指物质侵蚀事物，不能用来形容人习惯新环境的能力。"}, {"text": "延展性", "is_correct": false, "explanation": "语义：“延展性”指材料能拉长，与人习惯新学校无关。"}, {"text": "挥发性", "is_correct": false, "explanation": "语义：“挥发性”指物质易散发，用于人的适应能力上语义不通。"}], "explanations": {"适应性": "正确：“适应性”指慢慢习惯新环境的能力，与“很快就习惯了新学校”相合。", "腐蚀性": "搭配：“腐蚀性”多指物质侵蚀事物，不能用来形容人习惯新环境的能力。", "延展性": "语义：“延展性”指材料能拉长，与人习惯新学校无关。", "挥发性": "语义：“挥发性”指物质易散发，用于人的适应能力上语义不通。"}, "sentence_index": 0, "correct_answer": "适应性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只猫的适应性很漂亮。", "explanation": "这里应该用〈外貌〉。适应性说习惯新环境的能力，猫的长相好看要说外貌。"}, {"text": "他的适应性很好，学过的东西都记得。", "explanation": "这里应该用〈记性〉。适应性说习惯新环境，记住东西要说记性。"}, {"text": "他的适应性很高，有一米八。", "explanation": "这里应该用〈身高〉。适应性说习惯新环境的能力，人有多高要说身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25326, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "适应性", "is_correct": true, "explanation": "正确：“住在高原要有适应性”指慢慢习惯新环境的能力，与“身体要慢慢习惯”相合。"}, {"text": "导电性", "is_correct": false, "explanation": "语义：“导电性”指导体传电的性质，与人在高原的习惯无关。"}, {"text": "熔点", "is_correct": false, "explanation": "语义：“熔点”指物质熔化的温度，用于人在高原上语义不通。"}, {"text": "放射性", "is_correct": false, "explanation": "搭配：“放射性”多指物质辐射，不能说“住在高原要有放射性”。"}], "explanations": {"适应性": "正确：“住在高原要有适应性”指慢慢习惯新环境的能力，与“身体要慢慢习惯”相合。", "导电性": "语义：“导电性”指导体传电的性质，与人在高原的习惯无关。", "熔点": "语义：“熔点”指物质熔化的温度，用于人在高原上语义不通。", "放射性": "搭配：“放射性”多指物质辐射，不能说“住在高原要有放射性”。"}, "sentence_index": 6, "correct_answer": "适应性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个箱子的适应性很重。", "explanation": "这里应该用〈重量〉。适应性说习惯新环境的能力，箱子的轻重要说重量。"}, {"text": "这张纸的适应性很厚。", "explanation": "这里应该用〈厚度〉。适应性说习惯新环境的能力，纸的薄厚要说厚度。"}, {"text": "这首歌的适应性很好听。", "explanation": "这里应该用〈旋律〉。适应性说习惯新环境的能力，歌好不好听要说旋律。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25326, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个孩子的一只适应性很强，很快就习惯了新学校。", "corrected_sentence": "这个孩子的适应性很强，很快就习惯了新学校。", "error_description": "多加了量词“一只”。“只”用于动物个体，“适应性”是抽象名词，不能说“一只适应性”。应为“这个孩子的适应性很强”，去掉多余的量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25326, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个孩子得适应性很强，转学后很快就习惯了。", "corrected_sentence": "这个孩子的适应性很强，转学后很快就习惯了。", "error_description": "“的”误用成“得”。应为“这个孩子的适应性”，“的”连接定语和中心语“适应性”，不能用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c3ee29-df87-4428-96fe-9d20a95a3ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
