INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25328, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "天上掉下来的水，比如雨或雪。", "primary_collocate": null, "pronunciation": "jiàng shuǐ", "ipa": "tɕjɑŋ⁵¹ ʂweɪ²¹⁴", "syllable_count": 2, "sentences": [{"text": "今天的降水是雨还是雪？", "target_word": "降水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里夏天降水很多。", "target_word": "降水", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天气预报说明天有降水。", "target_word": "降水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "降水多的时候，河水会变大。", "target_word": "降水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北方冬天的降水常常是雪。", "target_word": "降水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个地方一年四季都有降水。", "target_word": "降水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月降水太少了，树都干了。", "target_word": "降水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的降水持续了整个下午。", "target_word": "降水", "complexity_tier": "T3", "furigana": "zuótiān de jiàngshuǐ chíxù le zhěnggè xiàwǔ", "sentence_source": "generated"}, {"text": "山里的降水比城里多。", "target_word": "降水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为降水，比赛改到明天了。", "target_word": "降水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "降水量", "label": "复合"}], "register": "中性", "sense_fingerprint": "天上落下的雨或雪", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '666c4209-724f-4fd6-b02e-7caaa973cf90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25328, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "降水", "is_correct": true, "explanation": "正确：“降水”指天上落下的雨或雪，与“是雨还是雪”相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是雨或雪，与“是雨还是雪”的语义矛盾。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”与天气无关，“是雨还是雪”的问法不通。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”与“雨还是雪”不搭配，不能用来指天上落下的东西。"}], "explanations": {"降水": "正确：“降水”指天上落下的雨或雪，与“是雨还是雪”相符。", "颜色": "语义：“颜色”不是雨或雪，与“是雨还是雪”的语义矛盾。", "价格": "语义：“价格”与天气无关，“是雨还是雪”的问法不通。", "味道": "搭配：“味道”与“雨还是雪”不搭配，不能用来指天上落下的东西。"}, "sentence_index": 0, "correct_answer": "降水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屋顶上的降水很厚，我们得去扫。", "explanation": "这里应该用〈雪〉。“降水”是雨雪的总称，形容屋顶积雪的厚薄要说“雪”。"}, {"text": "路上积了很多降水。", "explanation": "这里应该用〈雨水〉。落在地面积起来的水要说“雨水”；“降水”指天上落下的雨或雪，不说“积了很多降水”。"}, {"text": "今天的降水很新鲜，我们去公园吧。", "explanation": "这里应该用〈空气〉。“降水”指雨雪，不能用来形容“新鲜”，要说“空气很新鲜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae487f50-7559-4720-aef5-53c5c49c45f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25328, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "降水", "is_correct": true, "explanation": "正确：“这个月降水太少了，树都干了”，“降水”作主语，与“树都干了”的因果相符。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度太少”不合常理，与“树都干了”的语义不相符。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资太少”与“树都干了”没有关联，句子不通。"}, {"text": "字数", "is_correct": false, "explanation": "搭配：“字数”不能用来描述“树都干了”的原因，搭配不当。"}], "explanations": {"降水": "正确：“这个月降水太少了，树都干了”，“降水”作主语，与“树都干了”的因果相符。", "温度": "语义：“温度太少”不合常理，与“树都干了”的语义不相符。", "工资": "语义：“工资太少”与“树都干了”没有关联，句子不通。", "字数": "搭配：“字数”不能用来描述“树都干了”的原因，搭配不当。"}, "sentence_index": 6, "correct_answer": "降水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我口渴了，想喝一杯降水。", "explanation": "这里应该用〈水〉。「降水」指天上落下的雨或雪，是天气现象，不是喝的水。"}, {"text": "这场降水在厨房里做了午饭。", "explanation": "这里的主语应是人，如〈妈妈〉；“降水”是天上落下的雨雪，不能在厨房做饭。"}, {"text": "降水出来了，天气晴朗。", "explanation": "这里应该用〈太阳〉。“降水”指落下的雨雪，不会“出来”，要说“太阳出来了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae487f50-7559-4720-aef5-53c5c49c45f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25328, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个降水是雨还是雪？", "corrected_sentence": "这场降水是雨还是雪？", "error_description": "错误形式：“这个降水”。“降水”作为一次降落的事件，量词应为“场”，不能用“个”。正确形式为“这场降水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae487f50-7559-4720-aef5-53c5c49c45f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25328, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个月几乎没有一个降水，树都干了。", "corrected_sentence": "这个月几乎没有降水，树都干了。", "error_description": "错误形式：“没有一个降水”。“降水”的量词应为“场”或“次”，不能用“个”；“几乎没有降水”不需要量词。正确形式为“几乎没有降水”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae487f50-7559-4720-aef5-53c5c49c45f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25330, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缓解", "is_correct": true, "explanation": "正确：“缓解”与“加剧”是反义词，都指不好的情况程度的变化，方向相反。"}, {"text": "购买", "is_correct": false, "explanation": "与“加剧”没有反义关系：“购买”是花钱获得东西。"}, {"text": "打开", "is_correct": false, "explanation": "与“加剧”没有反义关系：“打开”是使关闭的东西张开。"}, {"text": "散步", "is_correct": false, "explanation": "与“加剧”没有反义关系：“散步”是慢慢走动。"}], "correct_answer": "缓解", "explanations": {"缓解": "正确：“缓解”与“加剧”是反义词，都指不好的情况程度的变化，方向相反。", "购买": "与“加剧”没有反义关系：“购买”是花钱获得东西。", "打开": "与“加剧”没有反义关系：“打开”是使关闭的东西张开。", "散步": "与“加剧”没有反义关系：“散步”是慢慢走动。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25330, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缓解", "is_correct": true, "explanation": "正确：“缓解”与“加剧”是反义词，都指不好的情况程度的变化，方向相反。"}, {"text": "修理", "is_correct": false, "explanation": "与“加剧”没有反义关系：“修理”是把坏东西弄好。"}, {"text": "思考", "is_correct": false, "explanation": "与“加剧”没有反义关系：“思考”是动脑筋想问题。"}, {"text": "参加", "is_correct": false, "explanation": "与“加剧”没有反义关系：“参加”是加入某项活动。"}], "correct_answer": "缓解", "explanations": {"缓解": "正确：“缓解”与“加剧”是反义词，都指不好的情况程度的变化，方向相反。", "修理": "与“加剧”没有反义关系：“修理”是把坏东西弄好。", "思考": "与“加剧”没有反义关系：“思考”是动脑筋想问题。", "参加": "与“加剧”没有反义关系：“参加”是加入某项活动。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25330, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让不好的事情变得更厉害。", "primary_collocate": null, "pronunciation": "jiā jù", "ipa": "tɕja˥ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "下雨加剧了交通堵塞。", "target_word": "加剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气污染正在加剧。", "target_word": "加剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吵架只会加剧两人的矛盾。", "target_word": "加剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变冷，他的咳嗽加剧了。", "target_word": "加剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "食物不够，让这里的困难进一步加剧。", "target_word": "加剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不运动会加剧身体的疲劳。", "target_word": "加剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争使当地的饥饿问题日益加剧。", "target_word": "加剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "压力太大会加剧失眠。", "target_word": "加剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国之间的紧张关系不断加剧。", "target_word": "加剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大风加剧了山上的火灾。", "target_word": "加剧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "加剧了", "label": "体标"}, {"form": "加剧着", "label": "体标"}], "register": "书面", "sense_fingerprint": "使不好的情况、问题变得更严重", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a7a008-8700-472e-9416-a17e42e54d73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25330, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "加剧", "is_correct": true, "explanation": "正确：“加剧”表示不好的情况变得更厉害，与“下雨___了交通堵塞”相符。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是地方、房间等，不说打扫交通堵塞。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：下雨不能“欣赏”交通堵塞，句意不通。"}, {"text": "连接", "is_correct": false, "explanation": "配价：“连接”需要两个对象，句中只有“交通堵塞”一个，搭配不完整。"}], "explanations": {"加剧": "正确：“加剧”表示不好的情况变得更厉害，与“下雨___了交通堵塞”相符。", "打扫": "搭配：“打扫”的对象是地方、房间等，不说打扫交通堵塞。", "欣赏": "语义：下雨不能“欣赏”交通堵塞，句意不通。", "连接": "配价：“连接”需要两个对象，句中只有“交通堵塞”一个，搭配不完整。"}, "sentence_index": 0, "correct_answer": "加剧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月我的体重加剧了三公斤。", "explanation": "这里应该用〈增加〉。“加剧”指不好的情况更严重，体重增加是中性的数量变化，要说增加。"}, {"text": "今年的收入加剧了不少。", "explanation": "这里应该用〈提升〉。“加剧”只用于不好的情况，收入增长这样的好事要说提升。"}, {"text": "她的自信心加剧了许多。", "explanation": "这里应该用〈增强〉。“加剧”只用于不好的情况，积极的变化要说增强。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25330, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加剧", "is_correct": true, "explanation": "正确：“加剧”表示饥饿问题更严重，与“日益”的语境相符。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：饥饿问题不能被“忘记”，与“日益”的语境相矛盾。"}, {"text": "修建", "is_correct": false, "explanation": "搭配：“修建”的对象是房屋、道路等建筑，不用于问题。"}, {"text": "批评", "is_correct": false, "explanation": "搭配：“批评”的对象是人或言行，不用于饥饿问题。"}], "explanations": {"加剧": "正确：“加剧”表示饥饿问题更严重，与“日益”的语境相符。", "忘记": "语义：饥饿问题不能被“忘记”，与“日益”的语境相矛盾。", "修建": "搭配：“修建”的对象是房屋、道路等建筑，不用于问题。", "批评": "搭配：“批评”的对象是人或言行，不用于饥饿问题。"}, "sentence_index": 6, "correct_answer": "加剧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在咖啡里加剧了一勺糖。", "explanation": "这里应该用〈加〉。“加剧”表示不好的情况更严重，往饮品里放东西要说“加”。"}, {"text": "他在房间里加剧了一盏灯。", "explanation": "这里应该用〈加〉。“加剧”指不好的情况更严重，给房间添设备要说“加”。"}, {"text": "妈妈在汤里加剧了一点盐。", "explanation": "这里应该用〈加〉。“加剧”不表示往食物里放调料，那是“加”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25330, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几天的雾越来越大，空气污染正在加剧过。", "corrected_sentence": "这几天的雾越来越大，空气污染正在加剧。", "error_description": "体标误用：“正在”表示动作进行中，不能与表示经历的“过”同用；应去掉“过”，说“正在加剧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25330, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "前些年，村里的水土流失曾经加剧着。", "corrected_sentence": "前些年，村里的水土流失曾经加剧过。", "error_description": "动态助词误用：“曾经”表示经历，应与“过”搭配，“着”表示持续，两者不能搭配。正确应为“加剧过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
