INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25334, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "面积就是物体表面或一片土地、地区所占的平面大小。", "primary_collocate": null, "pronunciation": "miàn jī", "ipa": "mjɛn˥˩ tɕi˥", "syllable_count": 2, "sentences": [{"text": "这个房间的面积有二十平方米。", "target_word": "面积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家面积很小，只能住三个人。", "target_word": "面积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国的面积比日本大很多。", "target_word": "面积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地的面积是多少平方米？", "target_word": "面积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园的面积很大，走一圈要一个小时。", "target_word": "面积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想买面积大一点的房子。", "target_word": "面积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先量一下桌子的面积。", "target_word": "面积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个湖的面积越来越小了。", "target_word": "面积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的面积不大，但是很漂亮。", "target_word": "面积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个国家面积差不多。", "target_word": "面积", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "总面积", "label": "复合"}, {"form": "占地面积", "label": "复合"}], "register": "中性", "sense_fingerprint": "物体表面或土地范围的大小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b139088-ecac-459a-8b81-09a754a5d1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25334, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "面积", "is_correct": true, "explanation": "正确：面积指平面的大小，用平方米计量，与“房间”搭配。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“体积”用立方米计量，不能说“有二十平方米”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不是房间的大小，也不用平方米计量，句子不通。"}, {"text": "幅员", "is_correct": false, "explanation": "语域：“幅员”是正式用语，多指国家或地区的面积，不用于描述房间。"}], "explanations": {"面积": "正确：面积指平面的大小，用平方米计量，与“房间”搭配。", "体积": "搭配：“体积”用立方米计量，不能说“有二十平方米”。", "价格": "语义：价格不是房间的大小，也不用平方米计量，句子不通。", "幅员": "语域：“幅员”是正式用语，多指国家或地区的面积，不用于描述房间。"}, "sentence_index": 0, "correct_answer": "面积"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这瓶水的面积是五百毫升。", "explanation": "这里应该用〈体积〉。面积只说平面的大小，用毫升表示的是体积。"}, {"text": "这条河的面积很长。", "explanation": "这里应该用〈长度〉。面积指平面的大小，河流的长短要用长度。"}, {"text": "这个包裹的面积很轻，一个人就能拿起来。", "explanation": "这里应该用〈重量〉。面积只说平面大小，不能说轻重，物体的轻重要用重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25334, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "面积", "is_correct": true, "explanation": "正确：量桌子时要量的是它的面积，“量”可以搭配“面积”。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“量”用于可以测量的东西，颜色不能用“量”来测。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”是人或生物的岁数，用“量”来说桌子的年龄不通。"}, {"text": "名字", "is_correct": false, "explanation": "语义：桌子的名字不能用“量”来测，句子不通。"}], "explanations": {"面积": "正确：量桌子时要量的是它的面积，“量”可以搭配“面积”。", "颜色": "搭配：“量”用于可以测量的东西，颜色不能用“量”来测。", "年龄": "语义：“年龄”是人或生物的岁数，用“量”来说桌子的年龄不通。", "名字": "语义：桌子的名字不能用“量”来测，句子不通。"}, "sentence_index": 6, "correct_answer": "面积"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试的面积很大，很多同学都没做完。", "explanation": "这里应该用〈难度〉。面积只指平面的大小，考试的难易要用难度。"}, {"text": "电视的面积很大，吵得人睡不着。", "explanation": "这里应该用〈音量〉。面积只指平面的大小，声音的大小要用音量。"}, {"text": "他的面积写错了，信寄不到。", "explanation": "这里应该用〈地址〉。面积只指平面的大小，写在信封上的住址要说地址。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25334, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块地的面积是三百立方米。", "corrected_sentence": "这块地的面积是三百平方米。", "error_description": "错误：“面积”要用平方米计量，“立方米”是体积的单位。应改为“三百平方米”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25334, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个房间的面积加起来有八十米。", "corrected_sentence": "两个房间的面积加起来有八十平方米。", "error_description": "错误：面积的单位要用“平方米”，“米”是长度单位，应说“八十平方米”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
