INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25346, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "风从哪边吹来，就是风向。", "primary_collocate": null, "pronunciation": "fēng xiàng", "ipa": "fɤŋ˥ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "今天的风向是东北风。", "target_word": "风向", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "看这面旗，就知道风向。", "target_word": "风向", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "风向变了，天气也会变。", "target_word": "风向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机起飞前要先确认风向。", "target_word": "风向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "渔民出海前会看风向。", "target_word": "风向", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "山上的风向变得很快。", "target_word": "风向", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个小工具可以测出风向。", "target_word": "风向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天的风向和冬天的不一样。", "target_word": "风向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风向转了，帐篷要换个地方搭。", "target_word": "风向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们每天记录风向和温度。", "target_word": "风向", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "风向标", "label": "复合"}, {"form": "風向", "label": "繁体"}], "register": "中性", "sense_fingerprint": "风向|风吹来的方向（气象）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd07fe6f-230a-43d0-a4fb-bb51bcd47393') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25346, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "温度", "is_correct": false, "explanation": "语义：温度指冷热程度，不是风的来向，不能说“今天的温度是东北风”。"}, {"text": "风向", "is_correct": true, "explanation": "风向：风吹来的方向，此处指东北风的来向，符合句意。"}, {"text": "湿度", "is_correct": false, "explanation": "语义：湿度指空气的潮湿程度，不能用来表示风从哪边吹来。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：价格无法与“东北风”搭配，东北风只能用来说明风的来向。"}], "explanations": {"温度": "语义：温度指冷热程度，不是风的来向，不能说“今天的温度是东北风”。", "风向": "风向：风吹来的方向，此处指东北风的来向，符合句意。", "湿度": "语义：湿度指空气的潮湿程度，不能用来表示风从哪边吹来。", "价格": "搭配：价格无法与“东北风”搭配，东北风只能用来说明风的来向。"}, "sentence_index": 0, "correct_answer": "风向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "海上的风向很强，船只很难前进。", "explanation": "这里应该用〈风力〉。风向指风吹来的方向，没有强弱之分；形容风的力量要用风力。"}, {"text": "今天风向很低，大家都穿厚衣服。", "explanation": "这里应该用〈温度〉。风向指风的来向，不能说高低；形容冷热要用温度。"}, {"text": "明天风向晴朗，适合去郊游。", "explanation": "这里应该用〈天气〉。风向不能形容晴朗与否；描述晴雨要用天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25346, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "思想", "is_correct": false, "explanation": "语义：思想是人的想法，不是小工具能测出的对象。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是人的情绪，与风的方向无关，小工具测不出。"}, {"text": "风向", "is_correct": true, "explanation": "风向：风吹来的方向，是小工具可以测出的对象，符合句意。"}, {"text": "故事", "is_correct": false, "explanation": "搭配：“测出”的对象须是可测量的事物，故事不能用仪器测出。"}], "explanations": {"思想": "语义：思想是人的想法，不是小工具能测出的对象。", "心情": "语义：心情是人的情绪，与风的方向无关，小工具测不出。", "风向": "风向：风吹来的方向，是小工具可以测出的对象，符合句意。", "故事": "搭配：“测出”的对象须是可测量的事物，故事不能用仪器测出。"}, "sentence_index": 6, "correct_answer": "风向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我弟弟的风向是八岁，还很小。", "explanation": "这里应该用〈年龄〉。风向指风吹来的方向，不能表示人的岁数；说年纪要用年龄。"}, {"text": "这朵花的风向是红色的。", "explanation": "这里应该用〈颜色〉。风向不是颜色，不能说风向是红色的；说颜色要用颜色。"}, {"text": "他的风向有一米八。", "explanation": "这里应该用〈身高〉。风向不能表示人的高度；说人的高矮要用身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25346, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "海边的一股风向变得很快，游泳要小心。", "corrected_sentence": "海边的风向变得很快，游泳要小心。", "error_description": "量词错误：“股”用于成股流动的风、气流，风向是方向，不能用“一股”计量；应去掉“一股”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25346, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "傍晚风向了转，我们先回家吧。", "corrected_sentence": "傍晚风向转了，我们先回家吧。", "error_description": "错误：“了”放在“转”前，写成“风向了转”。正确应为“风向转了”。了表示变化已经发生，要放在动词之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
