INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25356, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "猜一猜还没有发生的事情会怎样。", "primary_collocate": null, "pronunciation": "yù pàn", "ipa": "y˥˩ pʰan˥˩", "syllable_count": 2, "sentences": [{"text": "你能预判一下比赛的结果吗？", "target_word": "预判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我预判明天会下雨。", "target_word": "预判", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很会预判股市的走势。", "target_word": "预判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师预判大家会问这个问题。", "target_word": "预判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈预判我会晚回家，早就做好了饭。", "target_word": "预判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意的人要会预判市场的变化。", "target_word": "预判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下棋时，我常常预判对手的走法。", "target_word": "预判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气预报员预判周末会降温。", "target_word": "预判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也没能预判这次考试这么难。", "target_word": "预判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他预判错了，今天没有下雪。", "target_word": "预判", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "预判了", "label": "完成体"}, {"form": "预判过", "label": "经历体"}], "register": "书面语", "sense_fingerprint": "提前猜测尚未发生的事情的结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c3d54eb-37c5-4193-8809-1266ef82ae7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25356, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "预判", "is_correct": true, "explanation": "预判（yù pàn）：提前猜测尚未发生的事情会怎样。"}, {"text": "玉盘", "is_correct": false, "explanation": "pán（第二声）与 pàn（第四声）声调不同，玉盘指玉做的盘子。"}, {"text": "预拌", "is_correct": false, "explanation": "bàn 与 pàn 声母不同（b 与 p），预拌指预先搅拌好的材料。"}, {"text": "预探", "is_correct": false, "explanation": "tàn 与 pàn 声母不同（t 与 p），预探指事先勘探。"}, {"text": "鱼盘", "is_correct": false, "explanation": "yú 与 yù 声调不同，pán 与 pàn 声调也不同，鱼盘指盛鱼的盘子。"}], "explanations": {"预判": "预判（yù pàn）：提前猜测尚未发生的事情会怎样。", "玉盘": "pán（第二声）与 pàn（第四声）声调不同，玉盘指玉做的盘子。", "预拌": "bàn 与 pàn 声母不同（b 与 p），预拌指预先搅拌好的材料。", "预探": "tàn 与 pàn 声母不同（t 与 p），预探指事先勘探。", "鱼盘": "yú 与 yù 声调不同，pán 与 pàn 声调也不同，鱼盘指盛鱼的盘子。"}, "sentence_index": null, "correct_answer": "预判"}, "level_3": {"options": [{"text": "预判", "is_correct": true, "explanation": "正确：“预判比赛的结果”指事前猜测结果，与“你能……吗”的询问相符。"}, {"text": "吞咽", "is_correct": false, "explanation": "语义：“吞咽”指把食物咽下去，不能用于比赛的结果。"}, {"text": "捐赠", "is_correct": false, "explanation": "搭配：“捐赠”的对象是钱物，不能说捐赠比赛的结果。"}, {"text": "拍摄", "is_correct": false, "explanation": "搭配：“拍摄”的对象是人、景等画面，不能说拍摄比赛的结果。"}], "explanations": {"预判": "正确：“预判比赛的结果”指事前猜测结果，与“你能……吗”的询问相符。", "吞咽": "语义：“吞咽”指把食物咽下去，不能用于比赛的结果。", "捐赠": "搭配：“捐赠”的对象是钱物，不能说捐赠比赛的结果。", "拍摄": "搭配：“拍摄”的对象是人、景等画面，不能说拍摄比赛的结果。"}, "sentence_index": 0, "correct_answer": "预判"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我预判了窗外正在下的雨。", "explanation": "这里应该用〈看到〉。预判针对尚未发生的事，窗外正在下的雨是眼前的事实，要说看到。"}, {"text": "他预判了那场已经结束的比赛。", "explanation": "这里应该用〈看过〉。预判针对尚未发生的事，那场比赛已经结束，只能说看过。"}, {"text": "他常常预判童年的往事。", "explanation": "这里应该用〈回忆〉。预判是对未来的推测，童年的往事已经发生，只能回忆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d501c33-c21b-43f8-9ac6-864766fdbc5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25356, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "预判", "is_correct": true, "explanation": "正确：“预判对手的走法”是事前推测对方下一步，与下棋的情境相合。"}, {"text": "拆卸", "is_correct": false, "explanation": "搭配：“拆卸”的对象是机器、零件等，不能说拆卸对手的走法。"}, {"text": "感激", "is_correct": false, "explanation": "搭配：“感激”的对象是人或帮助，不能用于对手的走法。"}, {"text": "证明", "is_correct": false, "explanation": "语义：“证明”针对论断或事实，走法是行动，不能被证明。"}], "explanations": {"预判": "正确：“预判对手的走法”是事前推测对方下一步，与下棋的情境相合。", "拆卸": "搭配：“拆卸”的对象是机器、零件等，不能说拆卸对手的走法。", "感激": "搭配：“感激”的对象是人或帮助，不能用于对手的走法。", "证明": "语义：“证明”针对论断或事实，走法是行动，不能被证明。"}, "sentence_index": 6, "correct_answer": "预判"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人预判了这块地的面积。", "explanation": "这里应该用〈测量〉。面积要用工具量出，预判只是事前推测，不能靠预判得出。"}, {"text": "他预判了自己的名字。", "explanation": "这里应该用〈记得〉。预判针对尚未发生的事，自己的名字早已知道，只能说记得。"}, {"text": "他预判了昨天晚饭吃的菜。", "explanation": "这里应该用〈想起〉。预判针对尚未发生的事，昨天的晚饭已经吃过，只能说想起。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d501c33-c21b-43f8-9ac6-864766fdbc5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25356, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我正在预判了明天的天气。", "corrected_sentence": "我正在预判明天的天气。", "error_description": "“正在”表示动作正在进行，不能与“了”同用，应说“正在预判”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d501c33-c21b-43f8-9ac6-864766fdbc5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25356, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我不预判到这次的结局。", "corrected_sentence": "我没预判到这次的结局。", "error_description": "否定尚未预判到的结果要用“没”，不能用“不”，应说“没预判到”，不说“不预判到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d501c33-c21b-43f8-9ac6-864766fdbc5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
