INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25360, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物发展的方向。", "primary_collocate": null, "pronunciation": "qū shì", "ipa": "tɕʰy˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "现在手机越来越便宜，这是一个好趋势。", "target_word": "趋势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市的人口有增加的趋势。", "target_word": "趋势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的天气有变暖的趋势。", "target_word": "趋势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说，价格的上升趋势还会继续。", "target_word": "趋势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人买东西越来越爱上网，这是大趋势。", "target_word": "趋势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从这张图能看出销售的趋势。", "target_word": "趋势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要跟上时代的趋势。", "target_word": "趋势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近学汉语的人有增多的趋势。", "target_word": "趋势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "越来越多的人用手机付钱，这种趋势很明显。", "target_word": "趋势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他分析了市场的发展趋势。", "target_word": "趋势", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种趋势", "label": "量词"}, {"form": "发展趋势", "label": "复合"}, {"form": "上升趋势", "label": "复合"}, {"form": "大趋势", "label": "复合"}], "register": "中性", "sense_fingerprint": "事物发展变化的总方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af672a29-e1eb-4780-8f57-35ac2a0384e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25360, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "趋势", "is_correct": true, "explanation": "趋势（qū shì）指事物发展的方向，是正确答案。"}, {"text": "驱使", "is_correct": false, "explanation": "驱使（qū shǐ）与趋势（qū shì）第二个音节声调不同，意思是支使、役使。"}, {"text": "去世", "is_correct": false, "explanation": "去世（qù shì）与趋势（qū shì）第一个音节声调不同，意思是人死亡，是委婉的说法。"}, {"text": "曲式", "is_correct": false, "explanation": "曲式（qǔ shì）与趋势（qū shì）第一个音节声调不同，意思是乐曲的结构形式。"}], "explanations": {"趋势": "趋势（qū shì）指事物发展的方向，是正确答案。", "驱使": "驱使（qū shǐ）与趋势（qū shì）第二个音节声调不同，意思是支使、役使。", "去世": "去世（qù shì）与趋势（qū shì）第一个音节声调不同，意思是人死亡，是委婉的说法。", "曲式": "曲式（qǔ shì）与趋势（qū shì）第一个音节声调不同，意思是乐曲的结构形式。"}, "sentence_index": null, "correct_answer": "趋势"}, "level_3": {"options": [{"text": "人口", "is_correct": false, "explanation": "搭配：“好”不能修饰“人口”，说“这是一个好人口”不通。"}, {"text": "趋势", "is_correct": true, "explanation": "“这是一个好趋势”说的是价格下降、手机变便宜这一方向，符合语境。"}, {"text": "体积", "is_correct": false, "explanation": "语义：体积只说大小，不能评价好坏，“好体积”说不通。"}, {"text": "宽度", "is_correct": false, "explanation": "语义：宽度只说宽窄，不能用“好”来评价手机变便宜这件事。"}], "explanations": {"人口": "搭配：“好”不能修饰“人口”，说“这是一个好人口”不通。", "趋势": "“这是一个好趋势”说的是价格下降、手机变便宜这一方向，符合语境。", "体积": "语义：体积只说大小，不能评价好坏，“好体积”说不通。", "宽度": "语义：宽度只说宽窄，不能用“好”来评价手机变便宜这件事。"}, "sentence_index": 0, "correct_answer": "趋势"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的书包的趋势很合适。", "explanation": "这里应该用〈大小〉。趋势指事物发展的总方向，说物品的尺寸要用〈大小〉。"}, {"text": "警察在调查嫌疑人的趋势。", "explanation": "这里应该用〈动向〉。趋势指事物整体的发展方向，个人的行动要用〈动向〉。"}, {"text": "他朝北边的趋势走去。", "explanation": "这里应该用〈方向〉。趋势指发展变化的总方向，说行走的路线要用〈方向〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25360, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体重", "is_correct": false, "explanation": "语义：体重指人或物的重量，“跟上时代的体重”说不通。"}, {"text": "趋势", "is_correct": true, "explanation": "“我们要跟上时代的趋势”指跟上事物发展的方向，符合语境。"}, {"text": "厚度", "is_correct": false, "explanation": "搭配：“厚度”只说厚薄，不能用来表示跟得上的对象。"}, {"text": "重量", "is_correct": false, "explanation": "语义：重量指物体的轻重，“跟上时代的重量”说不通。"}], "explanations": {"体重": "语义：体重指人或物的重量，“跟上时代的体重”说不通。", "趋势": "“我们要跟上时代的趋势”指跟上事物发展的方向，符合语境。", "厚度": "搭配：“厚度”只说厚薄，不能用来表示跟得上的对象。", "重量": "语义：重量指物体的轻重，“跟上时代的重量”说不通。"}, "sentence_index": 6, "correct_answer": "趋势"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他分析了这张桌子的趋势。", "explanation": "这里应该用〈形状〉。趋势指事物发展变化的总方向，物体的外形要用〈形状〉。"}, {"text": "他分析了这块石头的趋势。", "explanation": "这里应该用〈纹路〉。趋势是抽象的发展方向，石头表面的花纹要用〈纹路〉。"}, {"text": "他分析了那扇门的趋势。", "explanation": "这里应该用〈颜色〉。趋势指发展变化的方向，门的颜色要用〈颜色〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25360, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我觉得这根趋势很明显。", "corrected_sentence": "我觉得这种趋势很明显。", "error_description": "量词错误：“趋势”应用“种”计量，“根”用于细长的条状物，不能修饰抽象的趋势，应改为“这种趋势”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25360, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几年市场出现了一本新趋势。", "corrected_sentence": "这几年市场出现了一种新趋势。", "error_description": "量词错误：“本”用于书本等，不能修饰抽象的“趋势”，应说「一种新趋势」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
