INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25362, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "能帮助我们找到答案或解决问题的事情。", "primary_collocate": null, "pronunciation": "xiàn suǒ", "ipa": "ɕjɛn˥˩ swo˨˩˦", "syllable_count": 2, "sentences": [{"text": "地上的脚印是一条线索。", "target_word": "线索", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你有什么线索吗？", "target_word": "线索", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "警察在找新的线索。", "target_word": "线索", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这张纸条是重要的线索。", "target_word": "线索", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们没有别的线索了。", "target_word": "线索", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他给了我们一条线索。", "target_word": "线索", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看地图能找到寻宝的线索。", "target_word": "线索", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给同学们一些线索，让大家猜答案。", "target_word": "线索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个线索帮我们找到了丢的书包。", "target_word": "线索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直在找解决问题的线索。", "target_word": "线索", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "線索", "label": "繁体"}], "register": "中性", "sense_fingerprint": "线索|帮助找到答案的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd07fe6f-230a-43d0-a4fb-bb51bcd47393') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25362, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "线索", "is_correct": true, "explanation": "“线索”指能帮助找到答案的迹象，地上的脚印正可以起这种作用。"}, {"text": "河流", "is_correct": false, "explanation": "语义：脚印不可能是一条河流，二者不相干。"}, {"text": "围巾", "is_correct": false, "explanation": "语义：脚印不是可以披戴的物品，不能说是一条围巾。"}, {"text": "招数", "is_correct": false, "explanation": "语义：“招数”指做事的办法或手段，不能指地上的脚印。"}], "explanations": {"线索": "“线索”指能帮助找到答案的迹象，地上的脚印正可以起这种作用。", "河流": "语义：脚印不可能是一条河流，二者不相干。", "围巾": "语义：脚印不是可以披戴的物品，不能说是一条围巾。", "招数": "语义：“招数”指做事的办法或手段，不能指地上的脚印。"}, "sentence_index": 0, "correct_answer": "线索"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这幅画的线索很流畅。", "explanation": "这里应该用〈线条〉。线索是引导查找的提示信息，流畅只能用来形容线条。"}, {"text": "这位画家的线索很有名。", "explanation": "这里应该用〈作品〉。线索是提示信息，不能用来指画家的作品。"}, {"text": "这条公交线索经过三个区。", "explanation": "这里应该用〈线路〉。线索是提示信息，公交行驶的路径要说线路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25362, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "线索", "is_correct": true, "explanation": "“线索”指能帮助找到目标的提示，地图提供的正是寻宝所需的这类信息。"}, {"text": "地毯", "is_correct": false, "explanation": "语义：地毯是铺在地上的织物，不能帮助找到宝藏。"}, {"text": "围墙", "is_correct": false, "explanation": "语义：围墙是用来挡住的建筑，不是能让人找到东西的提示。"}, {"text": "面容", "is_correct": false, "explanation": "体貌：“面容”指人的脸，与看地图寻宝的语境不符。"}], "explanations": {"线索": "“线索”指能帮助找到目标的提示，地图提供的正是寻宝所需的这类信息。", "地毯": "语义：地毯是铺在地上的织物，不能帮助找到宝藏。", "围墙": "语义：围墙是用来挡住的建筑，不是能让人找到东西的提示。", "面容": "体貌：“面容”指人的脸，与看地图寻宝的语境不符。"}, "sentence_index": 6, "correct_answer": "线索"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用这条线索炒了一盘菜。", "explanation": "这里误把线索当作〈食材〉。线索是提示信息，不能用来炒菜。"}, {"text": "这条线索很甜。", "explanation": "这里误把线索当作〈味道〉可感的东西。线索是提示信息，没有甜味，不能用“甜”形容。"}, {"text": "他用这条线索缝好了裂开的袖子。", "explanation": "这里误把线索当作〈棉线〉来用。线索是提示信息，缝衣服要用线，不能说线索。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25362, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些线索们都很有用。", "corrected_sentence": "这些线索都很有用。", "error_description": "“们”只用于指人的名词，线索是无生命的事物。应说“这些线索”，不能说“这些线索们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25362, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们找到了两线索。", "corrected_sentence": "他们找到了两条线索。", "error_description": "数词后缺少量词：“两”后面要加量词“条”，应说“两条线索”，不能省略量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25364, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "运动", "is_correct": true, "explanation": "“运动”指物体在移动，“静止”指物体不动，二者互为反义。"}, {"text": "读书", "is_correct": false, "explanation": "“读书”与“静止”没有反义关系，二者不构成对立。"}, {"text": "洗澡", "is_correct": false, "explanation": "“洗澡”与“静止”没有反义关系，二者不构成对立。"}, {"text": "写信", "is_correct": false, "explanation": "“写信”与“静止”没有反义关系，二者不构成对立。"}], "correct_answer": "运动", "explanations": {"运动": "“运动”指物体在移动，“静止”指物体不动，二者互为反义。", "读书": "“读书”与“静止”没有反义关系，二者不构成对立。", "洗澡": "“洗澡”与“静止”没有反义关系，二者不构成对立。", "写信": "“写信”与“静止”没有反义关系，二者不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25364, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "运动", "is_correct": true, "explanation": "“运动”指物体在移动，“静止”指物体不动，二者互为反义。"}, {"text": "睡觉", "is_correct": false, "explanation": "“睡觉”与“静止”没有反义关系，二者不构成对立。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”与“静止”没有反义关系，二者不构成对立。"}, {"text": "写字", "is_correct": false, "explanation": "“写字”与“静止”没有反义关系，二者不构成对立。"}], "correct_answer": "运动", "explanations": {"运动": "“运动”指物体在移动，“静止”指物体不动，二者互为反义。", "睡觉": "“睡觉”与“静止”没有反义关系，二者不构成对立。", "唱歌": "“唱歌”与“静止”没有反义关系，二者不构成对立。", "写字": "“写字”与“静止”没有反义关系，二者不构成对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25364, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不动了，就像玩具车停在那里。", "primary_collocate": null, "pronunciation": "jìng zhǐ", "ipa": "tɕiŋ˥˩ ʈʂɻ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "玩具车撞到墙，一下子静止了。", "target_word": "静止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小船靠岸后，慢慢静止了。", "target_word": "静止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "皮球越跳越低，最后静止在墙角。", "target_word": "静止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他按了暂停键，屏幕上的人一下子静止了。", "target_word": "静止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摆钟坏了，摆锤静止，不再来回摆动。", "target_word": "静止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小车没电了，滑了一小段就静止了。", "target_word": "静止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "转盘越转越慢，最后完全静止了。", "target_word": "静止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "等秋千静止了，你再坐上去。", "target_word": "静止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把玩具车放在地上，车轮转了几圈就静止了。", "target_word": "静止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小球碰到盒子后，在原地静止了几秒。", "target_word": "静止", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "静止了", "label": "体标"}, {"form": "静止不动", "label": "复合"}, {"form": "靜止", "label": "繁体"}], "register": "中性", "sense_fingerprint": "运动的东西停下来、不再动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd07fe6f-230a-43d0-a4fb-bb51bcd47393') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25364, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "静止", "is_correct": true, "explanation": "“静止”指不动了，与撞墙后突然停下的情节一致。"}, {"text": "散步", "is_correct": false, "explanation": "语义：玩具车不能散步，“散步”的主体是人。"}, {"text": "睡觉", "is_correct": false, "explanation": "搭配：“睡觉”只用于人或动物，玩具车不能睡觉。"}, {"text": "生气", "is_correct": false, "explanation": "语义：玩具车没有情绪，不能生气。"}], "explanations": {"静止": "“静止”指不动了，与撞墙后突然停下的情节一致。", "散步": "语义：玩具车不能散步，“散步”的主体是人。", "睡觉": "搭配：“睡觉”只用于人或动物，玩具车不能睡觉。", "生气": "语义：玩具车没有情绪，不能生气。"}, "sentence_index": 0, "correct_answer": "静止"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对我的感情突然静止了。", "explanation": "这里应该用〈消失〉。静止指物体不动，感情是抽象的东西，不能说“静止”。"}, {"text": "他静止地跑过了操场。", "explanation": "这里误把静止当成〈迅速〉的意思。静止表示不动，不能用来形容跑得快。"}, {"text": "池塘的水在冬天静止成了冰。", "explanation": "这里应该用〈凝固〉。静止只表示不动，不表示液体变成固体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25364, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "静止", "is_correct": true, "explanation": "“静止”指不动了，与“最后完全”停下的转盘状态一致。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：转盘没有感情，不会哭泣。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：转盘不是人，不会吃饭。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：转盘没有表情，不会微笑。"}], "explanations": {"静止": "“静止”指不动了，与“最后完全”停下的转盘状态一致。", "哭泣": "语义：转盘没有感情，不会哭泣。", "吃饭": "语义：转盘不是人，不会吃饭。", "微笑": "语义：转盘没有表情，不会微笑。"}, "sentence_index": 6, "correct_answer": "静止"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会议因为停电静止了。", "explanation": "这里应该用〈中止〉。静止指物体不动，会议不是物体，不能用“静止”。"}, {"text": "工厂因为事故静止了。", "explanation": "这里应该用〈停工〉。静止说物体不动，工厂停工是生产停下，不能说“静止”。"}, {"text": "比赛因为下雨静止了。", "explanation": "这里应该用〈中断〉。静止只表示不动，比赛中断不是物体静止。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25364, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车子开到门口，慢慢静止来了。", "corrected_sentence": "车子开到门口，慢慢静止下来了。", "error_description": "补语用错：表示由动到静应说“静止下来”，“静止来了”方向错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25364, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "画面一直静止了着。", "corrected_sentence": "画面一直静止着。", "error_description": "体标用错：“着”表示持续，已经有“着”就不能再加“了”，应说“静止着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
