INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25366, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "海水是海里咸咸的水。", "primary_collocate": null, "pronunciation": "hǎi shuǐ", "ipa": "xaɪ˨˩˦ ʂueɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "海水是咸的。", "target_word": "海水", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我尝了一下海水，真咸！", "target_word": "海水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说，海水不能喝。", "target_word": "海水", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小朋友在海边用桶装海水。", "target_word": "海水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海水是蓝色的，很漂亮。", "target_word": "海水", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夏天，海水凉凉的，我们都想下水。", "target_word": "海水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从海里打了一桶海水回家。", "target_word": "海水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海水干了以后，会留下白白的盐。", "target_word": "海水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条鱼只能在海水里生活，不能在河里生活。", "target_word": "海水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海水涨上来了，我们快离开沙滩吧。", "target_word": "海水", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "杯", "label": "量词"}, {"form": "桶", "label": "量词"}, {"form": "海水鱼", "label": "复合"}], "register": "中性", "sense_fingerprint": "海里又咸又蓝的水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd07fe6f-230a-43d0-a4fb-bb51bcd47393') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25366, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "糖", "is_correct": false, "explanation": "语义：糖是甜的，与“咸”相反，句子说的是海水的味道。"}, {"text": "海水", "is_correct": true, "explanation": "海水：海里咸咸的水，与“咸的”相合，符合句意。"}, {"text": "蜂蜜", "is_correct": false, "explanation": "语义：蜂蜜同样是甜的，不能说是咸的。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“咸”形容味道，不能用来形容天空。"}], "explanations": {"糖": "语义：糖是甜的，与“咸”相反，句子说的是海水的味道。", "海水": "海水：海里咸咸的水，与“咸的”相合，符合句意。", "蜂蜜": "语义：蜂蜜同样是甜的，不能说是咸的。", "天空": "搭配：“咸”形容味道，不能用来形容天空。"}, "sentence_index": 0, "correct_answer": "海水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "河边的海水很清，村里的小孩常在那里玩。", "explanation": "这里应该用〈河水〉。河里的水是淡水，海水只存在于海洋中，不会出现在河边。"}, {"text": "下雨了，天上落下了好多海水。", "explanation": "这里应该用〈雨水〉。从天上落下的是雨水，海水是海里的水。"}, {"text": "下完雨，院子里积了一些海水。", "explanation": "这里应该用〈雨水〉。海水来自海里，院子里积的是雨水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25366, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "牛奶", "is_correct": false, "explanation": "语义：句中说从海里打水，牛奶不会取自海里。"}, {"text": "海水", "is_correct": true, "explanation": "海水：从海里打来的水，符合句意。"}, {"text": "果汁", "is_correct": false, "explanation": "语义：果汁不可能从海里打来，与句中的“海里”不合。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油并非从海里打来的东西，与句中的“海里”不合。"}], "explanations": {"牛奶": "语义：句中说从海里打水，牛奶不会取自海里。", "海水": "海水：从海里打来的水，符合句意。", "果汁": "语义：果汁不可能从海里打来，与句中的“海里”不合。", "汽油": "语义：汽油并非从海里打来的东西，与句中的“海里”不合。"}, "sentence_index": 6, "correct_answer": "海水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这口井的海水很清，村里人都来这里打水。", "explanation": "这里应该用〈井水〉。海水在海里，不会出现在井里。"}, {"text": "山上的泉眼里流出了清清的海水。", "explanation": "这里应该用〈泉水〉。泉眼里流出的是泉水，海水只在海里。"}, {"text": "这条河的海水很清，鱼在里面游来游去。", "explanation": "这里应该用〈河水〉。河里的是淡水，海水只存在于海洋中。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25366, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师让我们带一粒海水回教室。", "corrected_sentence": "老师让我们带一杯海水回教室。", "error_description": "量词错误：海水是液体，应说“一杯海水”；“粒”用于颗粒状的东西，不能用于海水。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25366, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "海水慢慢退了上去，露出了礁石。", "corrected_sentence": "海水慢慢退了下去，露出了礁石。", "error_description": "补语错误：海水向大海方向后退，应说“退下去”；“退上去”方向不对，不能表示海水后撤。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
