INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25370, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人类学是研究人类怎么生活、怎么变化的学问。", "primary_collocate": null, "pronunciation": "rén lèi xué", "ipa": "ʐən˧˥ lei˥˩ ɕɥe˧˥", "syllable_count": 3, "sentences": [{"text": "人类学是研究人类生活和变化的学问。", "target_word": "人类学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐姐在大学学人类学，常常去农村住。", "target_word": "人类学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学人类学的人，喜欢和不同的人聊天。", "target_word": "人类学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人类学让我明白，每个民族的生活都不一样。", "target_word": "人类学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用人类学的方法，看看这里的人怎么过节。", "target_word": "人类学", "complexity_tier": "T3", "furigana": "tā xiǎng yòng rén lèi xué de fāng fǎ, kàn kan zhè lǐ de rén zěn me guò jié.", "sentence_source": "generated"}, {"text": "这个周末我要去听一个人类学的讲座。", "target_word": "人类学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上大学以后，她第一次听说人类学。", "target_word": "人类学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人类学研究人怎么生活，历史学研究过去的事。", "target_word": "人类学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王学了三年人类学，去过很多地方。", "target_word": "人类学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想知道人怎么生活和变化，可以读人类学。", "target_word": "人类学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人类学家", "label": "复合"}, {"form": "文化人类学", "label": "复合"}, {"form": "人類學", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：研究人怎么生活、怎么变化的学问（学人类学）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f895ac-25cd-46d5-9ed8-238277971775') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25370, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人类学", "is_correct": true, "explanation": "人类学：研究人类生活与变化的学问，作主语，句意通顺。"}, {"text": "气候", "is_correct": false, "explanation": "语义：“气候”是天气的长期状况，不是研究人类生活的学问。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“厨房”是场所，不能作“学问”的主语。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指身体的温度，不能被说成研究人类生活的学问。"}], "explanations": {"人类学": "人类学：研究人类生活与变化的学问，作主语，句意通顺。", "气候": "语义：“气候”是天气的长期状况，不是研究人类生活的学问。", "厨房": "搭配：“厨房”是场所，不能作“学问”的主语。", "体温": "语义：“体温”指身体的温度，不能被说成研究人类生活的学问。"}, "sentence_index": 0, "correct_answer": "人类学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "人类学研究山川河流的分布。", "explanation": "这里应该用〈地理学〉。人类学研究人的生活与变化，山川河流的分布属于地理学。"}, {"text": "人类学研究数量和图形的规律。", "explanation": "这里应该用〈数学〉。人类学研究人类社会与文化，数量和图形的规律属于数学。"}, {"text": "人类学研究天气的变化规律。", "explanation": "这里应该用〈气象学〉。人类学研究人的生活与变化，天气的变化规律属于气象学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25370, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人类学", "is_correct": true, "explanation": "人类学：可以听说的一门学问，与“听说”搭配，句意通顺。"}, {"text": "非常", "is_correct": false, "explanation": "语法：“非常”是副词，不能作“听说”的宾语。"}, {"text": "漂亮", "is_correct": false, "explanation": "语法：“漂亮”是形容词，“听说漂亮”不成立。"}, {"text": "慢慢", "is_correct": false, "explanation": "语法：“慢慢”修饰动作，不能作“听说”的宾语。"}], "explanations": {"人类学": "人类学：可以听说的一门学问，与“听说”搭配，句意通顺。", "非常": "语法：“非常”是副词，不能作“听说”的宾语。", "漂亮": "语法：“漂亮”是形容词，“听说漂亮”不成立。", "慢慢": "语法：“慢慢”修饰动作，不能作“听说”的宾语。"}, "sentence_index": 6, "correct_answer": "人类学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "人类学研究物体的运动和力的关系。", "explanation": "这里应该用〈物理学〉。人类学研究人的生活与变化，物体的运动和力的关系属于物理学。"}, {"text": "人类学研究岩石是怎样形成的。", "explanation": "这里应该用〈地质学〉。人类学研究人的生活与变化，岩石的形成属于地质学。"}, {"text": "人类学研究庄稼怎么种。", "explanation": "这里应该用〈农学〉。人类学研究人类社会与文化，庄稼的种植属于农学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25370, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他毕业后在博物馆工作，学的是人类学的。", "corrected_sentence": "他毕业后在博物馆工作，学的是人类学。", "error_description": "“的”多余：“学的是……”结构中，宾语“人类学”后不能再加“的”，应说“学的是人类学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25370, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他以前学了过人类学。", "corrected_sentence": "他以前学过人类学。", "error_description": "体貌错误：表示经历用“过”，不能与“了”叠用，应说“学过人类学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
