INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25372, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "没有足够的水。", "primary_collocate": null, "pronunciation": "quē shuǐ", "ipa": "tɕʰɥe˥ ʂwei̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "山上很缺水，农民只能种玉米。", "target_word": "缺水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鱼缺水就活不了。", "target_word": "缺水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年天气干，田里缺水。", "target_word": "缺水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跑了一天，嘴唇很干，可能是缺水了。", "target_word": "缺水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子旁边没有河，家里常常缺水。", "target_word": "缺水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草地缺水，你该去浇一浇。", "target_word": "缺水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵树缺水，叶子都掉了。", "target_word": "缺水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去爬山的时候，别忘了带水，不然会缺水。", "target_word": "缺水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，那一年村里特别缺水。", "target_word": "缺水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子出汗多，容易缺水，要多喝水。", "target_word": "缺水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "缺水了", "label": "体标"}, {"form": "缺过水", "label": "体标"}, {"form": "缺水地区", "label": "复合"}], "register": "通用", "sense_fingerprint": "没有足够的水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b139446e-7524-4719-8232-ba3bfc86546e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25372, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "缺水", "is_correct": true, "explanation": "“缺水”与“只能种玉米”的理由相符，是句中原词。"}, {"text": "缺氧", "is_correct": false, "explanation": "语义：“缺氧”与“农民只能种玉米”之间没有合理的因果联系，句子不通。"}, {"text": "缺点", "is_correct": false, "explanation": "语义：“缺点”是名词，指不足之处，不能说“山上很缺点”，句子不通。"}, {"text": "缺德", "is_correct": false, "explanation": "搭配：“缺德”形容人品，不能用来形容地方。"}], "explanations": {"缺水": "“缺水”与“只能种玉米”的理由相符，是句中原词。", "缺氧": "语义：“缺氧”与“农民只能种玉米”之间没有合理的因果联系，句子不通。", "缺点": "语义：“缺点”是名词，指不足之处，不能说“山上很缺点”，句子不通。", "缺德": "搭配：“缺德”形容人品，不能用来形容地方。"}, "sentence_index": 0, "correct_answer": "缺水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子长得快，骨头却缺水。", "explanation": "这里应该用〈缺钙〉。“缺水”指水分不足，骨头不足应说“缺钙”。"}, {"text": "他的手机电量缺水，快要关机了。", "explanation": "这里应该用〈不足〉。“缺水”只指水分不足，电量不够应说“电量不足”，不能用“缺水”。"}, {"text": "这家公司最近缺水，正在招聘员工。", "explanation": "这里应该用〈缺人〉。“缺水”不能用来说人手短缺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25372, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缺水", "is_correct": true, "explanation": "“缺水”指缺乏水分，与“叶子都掉了”的结果相符，是句中原词。"}, {"text": "发烧", "is_correct": false, "explanation": "搭配：“发烧”是人的身体状态，不能用来形容树。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与树叶掉落没有因果关系，句子不通。"}, {"text": "失眠", "is_correct": false, "explanation": "搭配：“失眠”只用于人，不能用于树。"}], "explanations": {"缺水": "“缺水”指缺乏水分，与“叶子都掉了”的结果相符，是句中原词。", "发烧": "搭配：“发烧”是人的身体状态，不能用来形容树。", "唱歌": "语义：“唱歌”与树叶掉落没有因果关系，句子不通。", "失眠": "搭配：“失眠”只用于人，不能用于树。"}, "sentence_index": 6, "correct_answer": "缺水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他做事很认真，只是经验缺水。", "explanation": "这里应该用〈缺乏〉。“缺水”只指水分不足，说经验不够要用“缺乏”，不能用“缺水”。"}, {"text": "这家店的牛奶卖完了，现在缺水。", "explanation": "这里应该用〈缺货〉。“缺水”指水分不足，商品卖完要用“缺货”。"}, {"text": "他这个月缺水，要省着花。", "explanation": "这里应该用〈缺钱〉。“缺水”只指水分不足，不能用来说金钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25372, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "去年夏天我们村缺水过。", "corrected_sentence": "去年夏天我们村缺过水。", "error_description": "错误：“过”放在了“水”的后面。正确：“过”要紧跟动词，应为“缺过水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25372, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个村子去年没缺水了。", "corrected_sentence": "这个村子去年没缺水。", "error_description": "错误：“没缺水了”；正确：“没缺水”。用“没”否定“缺水”时，后面不能再加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
