INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25384, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大家最注意、最关心的人或事。", "primary_collocate": null, "pronunciation": "jiāo diǎn", "ipa": "tɕjɑʊ˥ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "他是今天晚会的焦点。", "target_word": "焦点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事成了大家谈话的焦点。", "target_word": "焦点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个新玩具成了孩子们的焦点。", "target_word": "焦点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条新闻是今天报纸的焦点。", "target_word": "焦点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的新帽子成了朋友们的焦点。", "target_word": "焦点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的焦点是谁能得第一名。", "target_word": "焦点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的讨论焦点是旅行的时间。", "target_word": "焦点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一唱歌，就成为大家的焦点。", "target_word": "焦点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位新同学一来，就成了全班的焦点。", "target_word": "焦点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喜欢成为人群的焦点。", "target_word": "焦点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个焦点", "label": "量词"}, {"form": "焦點", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大家最注意、最关心的人或事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f3bbb28-ef77-4126-94bd-0d4dcabd7445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25384, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "焦点", "is_correct": true, "explanation": "焦点：晚会上大家最注意的人，与句意相符。"}, {"text": "账单", "is_correct": false, "explanation": "语义：“账单”是付款凭证，不是人，“他是晚会的账单”说不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人，不能说“他是晚会的天气”。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是电子设备，不是人，“他是晚会的手机”说不通。"}], "explanations": {"焦点": "焦点：晚会上大家最注意的人，与句意相符。", "账单": "语义：“账单”是付款凭证，不是人，“他是晚会的账单”说不通。", "天气": "语义：天气不是人，不能说“他是晚会的天气”。", "手机": "语义：手机是电子设备，不是人，“他是晚会的手机”说不通。"}, "sentence_index": 0, "correct_answer": "焦点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "外面下着焦点，地上白茫茫的一片。", "explanation": "这里应该用〈雪〉。雪会从天上下来，让地上白茫茫；「焦点」指大家最注意的地方，不会下。"}, {"text": "院子里有一个焦点，夏天很凉快。", "explanation": "这里应该用〈大树〉。大树能遮阴，所以夏天凉快；「焦点」不能遮阴。"}, {"text": "桌上有三个焦点，孩子们抢着吃。", "explanation": "这里应该用〈糖〉。糖可以吃，孩子们会抢；「焦点」是大家最注意的地方，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25384, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "焦点", "is_correct": true, "explanation": "焦点：大家最关注的部分，讨论的重点是旅行的时间。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不能作为讨论的对象，与“旅行的时间”无关。"}, {"text": "老师", "is_correct": false, "explanation": "语义：“老师”是人，不是讨论的内容，句子说的是讨论的话题。"}, {"text": "座位", "is_correct": false, "explanation": "搭配：“讨论”通常接话题、问题，不说“讨论座位”。"}], "explanations": {"焦点": "焦点：大家最关注的部分，讨论的重点是旅行的时间。", "冰箱": "语义：冰箱是家电，不能作为讨论的对象，与“旅行的时间”无关。", "老师": "语义：“老师”是人，不是讨论的内容，句子说的是讨论的话题。", "座位": "搭配：“讨论”通常接话题、问题，不说“讨论座位”。"}, "sentence_index": 6, "correct_answer": "焦点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的焦点很好，适合出去玩。", "explanation": "这里应该用〈天气〉。天气有好坏，适合出门；「焦点」指大家最注意的地方，没有好坏之分，不能说适合出去玩。"}, {"text": "这个焦点很大，住着一家人。", "explanation": "这里应该用〈房子〉。房子可以住人；「焦点」不能住人。"}, {"text": "屋里跑进来一个焦点，很可爱。", "explanation": "这里应该用〈小猫〉。小猫会跑进屋，还很可爱；「焦点」不会跑，也不能说可爱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25384, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位歌手的新专辑成了大家议论的一股焦点。", "corrected_sentence": "这位歌手的新专辑成了大家议论的一个焦点。", "error_description": "量词错：“焦点”应说“个”；“股”用于气体、液体等成股的东西，不能用来数“焦点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25384, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这幅画是今天展览会的一名焦点。", "corrected_sentence": "这幅画是今天展览会的一个焦点。", "error_description": "量词错：“焦点”应说“个”；“名”用于人，不能用来数“焦点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25388, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出现", "is_correct": true, "explanation": "出现与消失是一对反义词：出现指显露、有了，消失指不见了、没有了。"}, {"text": "读书", "is_correct": false, "explanation": "读书指阅读书籍的动作，与消失没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌指发出歌声，与消失没有反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步指快速移动身体，与消失没有反义关系。"}], "correct_answer": "出现", "explanations": {"出现": "出现与消失是一对反义词：出现指显露、有了，消失指不见了、没有了。", "读书": "读书指阅读书籍的动作，与消失没有反义关系。", "唱歌": "唱歌指发出歌声，与消失没有反义关系。", "跑步": "跑步指快速移动身体，与消失没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25388, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出现", "is_correct": true, "explanation": "出现与消失是一对反义词：出现指显露、有了，消失指不见了、没有了。"}, {"text": "写字", "is_correct": false, "explanation": "写字指用笔写出文字，与消失没有反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳指在水中运动，与消失没有反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "睡觉指闭眼休息，与消失没有反义关系。"}], "correct_answer": "出现", "explanations": {"出现": "出现与消失是一对反义词：出现指显露、有了，消失指不见了、没有了。", "写字": "写字指用笔写出文字，与消失没有反义关系。", "游泳": "游泳指在水中运动，与消失没有反义关系。", "睡觉": "睡觉指闭眼休息，与消失没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25388, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看不见了，没有了。", "primary_collocate": null, "pronunciation": "xiāo shī", "ipa": "ɕjɑʊ˥ ʂɨ˥", "syllable_count": 2, "sentences": [{"text": "太阳出来后，雾慢慢消失了。", "target_word": "消失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走进人群，一下子消失了。", "target_word": "消失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的头疼已经消失了。", "target_word": "消失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种小鸟在这里消失很多年了。", "target_word": "消失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到妈妈，孩子的害怕马上消失了。", "target_word": "消失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机里的照片突然消失了。", "target_word": "消失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑以后，山慢慢消失在夜色里。", "target_word": "消失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只猫从家里消失过一次。", "target_word": "消失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪一到春天就会消失。", "target_word": "消失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的笑容突然消失了，大家都很吃惊。", "target_word": "消失", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "消失了", "label": "体标"}, {"form": "消失过", "label": "体标"}], "register": "中性", "sense_fingerprint": "人或事物逐渐或突然不见、不存在", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b139088-ecac-459a-8b81-09a754a5d1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25388, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "消失", "is_correct": true, "explanation": "消失（xiāo shī）是本词，意思是看不见了、没有了。"}, {"text": "小时", "is_correct": false, "explanation": "xiǎo（第三声）与 xiāo（第一声）声调不同，shí（第二声）与 shī（第一声）声调不同，意思是小时（时间单位）。"}, {"text": "小事", "is_correct": false, "explanation": "xiǎo 与 xiāo 声调不同，shì（第四声）与 shī（第一声）声调不同，意思是小事（不重要的事）。"}, {"text": "小诗", "is_correct": false, "explanation": "xiǎo 与 xiāo 声调不同，意思是小诗（篇幅短的诗）。"}, {"text": "消食", "is_correct": false, "explanation": "shí（第二声）与 shī（第一声）声调不同，意思是消化食物，如饭后散步消食。"}], "explanations": {"消失": "消失（xiāo shī）是本词，意思是看不见了、没有了。", "小时": "xiǎo（第三声）与 xiāo（第一声）声调不同，shí（第二声）与 shī（第一声）声调不同，意思是小时（时间单位）。", "小事": "xiǎo 与 xiāo 声调不同，shì（第四声）与 shī（第一声）声调不同，意思是小事（不重要的事）。", "小诗": "xiǎo 与 xiāo 声调不同，意思是小诗（篇幅短的诗）。", "消食": "shí（第二声）与 shī（第一声）声调不同，意思是消化食物，如饭后散步消食。"}, "sentence_index": null, "correct_answer": "消失"}, "level_3": {"options": [{"text": "消失", "is_correct": true, "explanation": "消失：看不见了、没有了，与“太阳出来后，雾慢慢……”的变化相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：雾不会唱歌，“唱”与自然现象的变化没有关系，句子说不通。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”的宾语应是可以食用的东西，雾不能被吃掉。"}, {"text": "喝", "is_correct": false, "explanation": "配价：“喝”的宾语应是饮品，雾不能被喝掉。"}], "explanations": {"消失": "消失：看不见了、没有了，与“太阳出来后，雾慢慢……”的变化相符。", "唱": "语义：雾不会唱歌，“唱”与自然现象的变化没有关系，句子说不通。", "吃": "配价：“吃”的宾语应是可以食用的东西，雾不能被吃掉。", "喝": "配价：“喝”的宾语应是饮品，雾不能被喝掉。"}, "sentence_index": 0, "correct_answer": "消失"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的气温消失了。", "explanation": "这里应该用〈降低〉。消失是整体不存在，气温下降要用降低。"}, {"text": "他这个月的体重消失了三公斤。", "explanation": "这里应该用〈减轻〉。消失表示不再存在，体重变轻要用减轻，不能用消失。"}, {"text": "班里的人数消失了。", "explanation": "这里应该用〈减少〉。消失指全部不见了，人数只是变少，要用减少。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25388, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "消失", "is_correct": true, "explanation": "消失（xiāo shī）是本词，意思是看不见了、没有了。"}, {"text": "晓事", "is_correct": false, "explanation": "xiǎo（第三声）与 xiāo（第一声）声调不同，shì（第四声）与 shī（第一声）声调不同，意思是懂事、明白事理。"}, {"text": "小试", "is_correct": false, "explanation": "xiǎo 与 xiāo 声调不同，shì 与 shī 声调不同，意思是稍微试一下（小试身手）。"}, {"text": "小石", "is_correct": false, "explanation": "xiǎo 与 xiāo 声调不同，shí（第二声）与 shī（第一声）声调不同，意思是小石头。"}, {"text": "小视", "is_correct": false, "explanation": "xiǎo 与 xiāo 声调不同，shì 与 shī 声调不同，意思是轻视、看不起。"}], "explanations": {"消失": "消失（xiāo shī）是本词，意思是看不见了、没有了。", "晓事": "xiǎo（第三声）与 xiāo（第一声）声调不同，shì（第四声）与 shī（第一声）声调不同，意思是懂事、明白事理。", "小试": "xiǎo 与 xiāo 声调不同，shì 与 shī 声调不同，意思是稍微试一下（小试身手）。", "小石": "xiǎo 与 xiāo 声调不同，shí（第二声）与 shī（第一声）声调不同，意思是小石头。", "小视": "xiǎo 与 xiāo 声调不同，shì 与 shī 声调不同，意思是轻视、看不起。"}, "sentence_index": null, "correct_answer": "消失"}, "level_3": {"options": [{"text": "消失", "is_correct": true, "explanation": "消失：不见了，与“天黑以后，山慢慢……在夜色里”的意思相符。"}, {"text": "飞", "is_correct": false, "explanation": "语义：山不会飞，“飞”与“山慢慢……在夜色里”的画面不合。"}, {"text": "游", "is_correct": false, "explanation": "语义：山不能游动，“游”不能用来描述山。"}, {"text": "住", "is_correct": false, "explanation": "搭配：“住”要求人或动物作主语，不能用来说“山住在夜色里”。"}], "explanations": {"消失": "消失：不见了，与“天黑以后，山慢慢……在夜色里”的意思相符。", "飞": "语义：山不会飞，“飞”与“山慢慢……在夜色里”的画面不合。", "游": "语义：山不能游动，“游”不能用来描述山。", "住": "搭配：“住”要求人或动物作主语，不能用来说“山住在夜色里”。"}, "sentence_index": 6, "correct_answer": "消失"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次活动让我们学校的名声消失得更大了。", "explanation": "这里应该用〈扩大〉。消失表示不存在，名声变大要用扩大，不能用消失。"}, {"text": "这些照片我全部消失了。", "explanation": "这里应该用〈删除〉。消失表示不见了，不是人主动去做的动作；删掉照片要用删除。"}, {"text": "小树苗一年就消失了一米。", "explanation": "这里应该用〈长高〉。消失表示不存在，树苗变高要用长高，不能用消失。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25388, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只狗突然消失了尾巴。", "corrected_sentence": "那只狗突然消失了。", "error_description": "错误：“消失”是不及物动词，后面不能带宾语“尾巴”。应说“那只狗突然消失了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25388, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "星星慢慢消失晨光里。", "corrected_sentence": "星星慢慢消失在晨光里。", "error_description": "错误：“消失”后面表示处所时要用介词“在”，应说“消失在晨光里”，不能省略“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
