INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25390, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "土里有多少水。", "primary_collocate": null, "pronunciation": "tǔ rǎng shī dù", "ipa": "tʰu˨˩˦ ɻɑŋ˨˩˦ ʂɨ˥ tu˥˩", "syllable_count": 4, "sentences": [{"text": "花盆里的土壤湿度太低了。", "target_word": "土壤湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我用小机器测土壤湿度。", "target_word": "土壤湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨后土壤湿度很高，地是软的。", "target_word": "土壤湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "土壤湿度不够，苗就长不好。", "target_word": "土壤湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸用手摸土，知道土壤湿度。", "target_word": "土壤湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天土壤湿度下降得很快，要多浇水。", "target_word": "土壤湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校的菜园里有一台测土壤湿度的机器。", "target_word": "土壤湿度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土壤湿度高的地方，草长得更好。", "target_word": "土壤湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请告诉我今天的土壤湿度是多少。", "target_word": "土壤湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "种花以前，先看看土壤湿度。", "target_word": "土壤湿度", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "土壤濕度", "label": "繁体"}], "register": "中性", "sense_fingerprint": "土里水分的多少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f895ac-25cd-46d5-9ed8-238277971775') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25390, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "土壤湿度", "is_correct": true, "explanation": "“太低了”说明湿度不够，符合句意。"}, {"text": "土壤颜色", "is_correct": false, "explanation": "搭配：颜色不能用“太低了”来形容。"}, {"text": "土壤形状", "is_correct": false, "explanation": "搭配：形状不能用“太低了”来形容。"}, {"text": "土壤气味", "is_correct": false, "explanation": "搭配：气味不说“太低了”，此处搭配不成立。"}], "explanations": {"土壤湿度": "“太低了”说明湿度不够，符合句意。", "土壤颜色": "搭配：颜色不能用“太低了”来形容。", "土壤形状": "搭配：形状不能用“太低了”来形容。", "土壤气味": "搭配：气味不说“太低了”，此处搭配不成立。"}, "sentence_index": 0, "correct_answer": "土壤湿度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块地的土壤湿度很深，说明有很多腐殖质。", "explanation": "这里应该用〈土壤颜色〉。“深”描述颜色，湿度是百分比数值，不说深浅。"}, {"text": "山坡上的土壤湿度有一米，够种树了。", "explanation": "这里应该用〈土壤厚度〉。“一米”说的是厚度，湿度不用米计量。"}, {"text": "这个花园的土壤湿度很松，好种花。", "explanation": "这里应该用〈土壤质地〉。“松”形容土的质地，湿度不说松软。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25390, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "土壤湿度", "is_correct": true, "explanation": "“测土壤湿度的机器”说的是测量含水量的仪器，符合句意。"}, {"text": "土壤感情", "is_correct": false, "explanation": "语义：土壤没有感情，无法用机器测量，句意不成立。"}, {"text": "土壤价格", "is_correct": false, "explanation": "搭配：“测”不能与“价格”搭配，应说“查”价格。"}, {"text": "土壤故事", "is_correct": false, "explanation": "语义：土壤不能讲故事，“测土壤故事”不成立。"}], "explanations": {"土壤湿度": "“测土壤湿度的机器”说的是测量含水量的仪器，符合句意。", "土壤感情": "语义：土壤没有感情，无法用机器测量，句意不成立。", "土壤价格": "搭配：“测”不能与“价格”搭配，应说“查”价格。", "土壤故事": "语义：土壤不能讲故事，“测土壤故事”不成立。"}, "sentence_index": 6, "correct_answer": "土壤湿度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冬天的土壤湿度是零下三度，不能种花。", "explanation": "这里应该用〈土壤温度〉。零下几度说的是温度，湿度用百分比表示，不会是负数。"}, {"text": "这一桶土的土壤湿度是六点五，偏酸。", "explanation": "这里应该用〈酸碱度〉。“偏酸”说的是酸碱度，土壤湿度表示土里水分的多少，不能用来说酸性。"}, {"text": "这块地的土壤湿度有五亩。", "explanation": "这里应该用〈土壤面积〉。“亩”是面积单位，湿度不用亩计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25390, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们需要一台测土壤湿度机器。", "corrected_sentence": "我们需要一台测土壤湿度的机器。", "error_description": "“测土壤湿度”修饰名词“机器”时中间要加“的”，应说“测土壤湿度的机器”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25390, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个花园的土壤湿度得很高，草长得很好。", "corrected_sentence": "这个花园的土壤湿度很高，草长得很好。", "error_description": "“得”不能直接接在“土壤湿度”后作补语标记，应说“土壤湿度很高”，去掉“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
