INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25392, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "比别的多或高，比如跑得更快。", "primary_collocate": null, "pronunciation": "chāo", "ipa": "ʈʂʰɑʊ˥", "syllable_count": 1, "sentences": [{"text": "他跑得很快，一下就超了我。", "target_word": "超", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面的车太慢，我超了它。", "target_word": "超", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小马最后一圈超了小王，拿到第一。", "target_word": "超", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想超他，可是怎么也超不了。", "target_word": "超", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟的个子已经超了哥哥。", "target_word": "超", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车开得快，超了好几辆车。", "target_word": "超", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学习很努力，慢慢超了其他同学。", "target_word": "超", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步时你别急，不要总想着超别人。", "target_word": "超", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛，我超了他一圈。", "target_word": "超", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那辆白车从左边超了我们。", "target_word": "超", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "超了", "label": "体标"}, {"form": "超车", "label": "复合"}], "register": "口语", "sense_fingerprint": "从后面赶到前面，或在数量、程度上高过别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b139088-ecac-459a-8b81-09a754a5d1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25392, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "超", "is_correct": true, "explanation": "超（chāo）是本词，意思是超过、胜过别人。"}, {"text": "潮", "is_correct": false, "explanation": "cháo（第二声）与 chāo（第一声）声调不同，意思是潮水。"}, {"text": "炒", "is_correct": false, "explanation": "chǎo（第三声）与 chāo（第一声）声调不同，意思是炒菜。"}, {"text": "招", "is_correct": false, "explanation": "zh 与 ch 声母不同，声调相同，意思是招手、招收。"}, {"text": "操", "is_correct": false, "explanation": "c 与 ch 声母不同（cāo 与 chāo），意思是操作、体操。"}], "explanations": {"超": "超（chāo）是本词，意思是超过、胜过别人。", "潮": "cháo（第二声）与 chāo（第一声）声调不同，意思是潮水。", "炒": "chǎo（第三声）与 chāo（第一声）声调不同，意思是炒菜。", "招": "zh 与 ch 声母不同，声调相同，意思是招手、招收。", "操": "c 与 ch 声母不同（cāo 与 chāo），意思是操作、体操。"}, "sentence_index": null, "correct_answer": "超"}, "level_3": {"options": [{"text": "超", "is_correct": true, "explanation": "超：越过别人、超过别人，与“他跑得很快，一下就……了我”的语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”的宾语应是食物，“吃了我”说不通。"}, {"text": "喝", "is_correct": false, "explanation": "配价：“喝”的宾语应是饮品，“喝了我”说不通。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是烹饪的动作，与“跑得很快，一下就”的情况不合。"}], "explanations": {"超": "超：越过别人、超过别人，与“他跑得很快，一下就……了我”的语境相符。", "吃": "配价：“吃”的宾语应是食物，“吃了我”说不通。", "喝": "配价：“喝”的宾语应是饮品，“喝了我”说不通。", "煮": "语义：“煮”是烹饪的动作，与“跑得很快，一下就”的情况不合。"}, "sentence_index": 0, "correct_answer": "超"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司这个月超了三名新员工。", "explanation": "这里应该用〈招〉。超表示越过、超过，不表示招收员工；招收员工要用招。"}, {"text": "我在门口超了一个包裹。", "explanation": "这里应该用〈拿〉。“超”表示越过、超过别人，不能用来说拿包裹。"}, {"text": "汽车超了那座桥。", "explanation": "这里应该用〈越过〉。“超”的对象是人或车辆，不能说超过一座桥。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25392, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "超", "is_correct": true, "explanation": "超（chāo）是本词，意思是超过、胜过别人。"}, {"text": "吵", "is_correct": false, "explanation": "chǎo（第三声）与 chāo（第一声）声调不同，意思是吵架。"}, {"text": "巢", "is_correct": false, "explanation": "cháo（第二声）与 chāo（第一声）声调不同，意思是鸟巢。"}, {"text": "糙", "is_correct": false, "explanation": "c 与 ch 声母不同，意思是粗糙，如糙米。"}], "explanations": {"超": "超（chāo）是本词，意思是超过、胜过别人。", "吵": "chǎo（第三声）与 chāo（第一声）声调不同，意思是吵架。", "巢": "cháo（第二声）与 chāo（第一声）声调不同，意思是鸟巢。", "糙": "c 与 ch 声母不同，意思是粗糙，如糙米。"}, "sentence_index": null, "correct_answer": "超"}, "level_3": {"options": [{"text": "超", "is_correct": true, "explanation": "超：越过别人、超过别人，与“他学习很努力，慢慢……了其他同学”的语境相符。"}, {"text": "写", "is_correct": false, "explanation": "配价：“写”的宾语应是字或文章，不能写“其他同学”。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”是伤害性的动作，与“学习很努力”的语境不符。"}, {"text": "捐", "is_correct": false, "explanation": "配价：“捐”的宾语应是钱物，不能捐“同学”。"}], "explanations": {"超": "超：越过别人、超过别人，与“他学习很努力，慢慢……了其他同学”的语境相符。", "写": "配价：“写”的宾语应是字或文章，不能写“其他同学”。", "咬": "语义：“咬”是伤害性的动作，与“学习很努力”的语境不符。", "捐": "配价：“捐”的宾语应是钱物，不能捐“同学”。"}, "sentence_index": 6, "correct_answer": "超"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们终于超到了车站。", "explanation": "这里应该用〈赶到〉。“超”表示越过别人、超过别人，不表示到达某地。"}, {"text": "他终于超了这个谜题。", "explanation": "这里应该用〈解开〉。“超”表示越过、超过别人或事物，不能用于解开谜题。"}, {"text": "我们今天超了一张照片。", "explanation": "这里应该用〈拍〉。超表示越过、超过，不表示拍摄；拍照片要用拍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25392, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "前面那个人跑得太快，我怎么也超得不了。", "corrected_sentence": "前面那个人跑得太快，我怎么也超不了。", "error_description": "错误：可能补语的否定式是“超不了”，不能说“超得不了”。应说“怎么也超不了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25392, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我一直没超了他。", "corrected_sentence": "我一直没超过他。", "error_description": "错误：否定已经完成的超越要用“没超过”，“没超了”不成立，应说“没超过他”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
