INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25394, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "用不同科目的知识。", "primary_collocate": null, "pronunciation": "kuà xué kē", "ipa": "kʰua˥˩ ɕɥɛ˧˥ kʰɤ˥", "syllable_count": 3, "sentences": [{"text": "这门课是跨学科的。", "target_word": "跨学科", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们学校有跨学科的课程。", "target_word": "跨学科", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她喜欢跨学科的研究。", "target_word": "跨学科", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们一个跨学科的题目。", "target_word": "跨学科", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个跨学科项目很有意思。", "target_word": "跨学科", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跨学科学习能让我们想得更多。", "target_word": "跨学科", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做的是跨学科研究，不只是数学。", "target_word": "跨学科", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个跨学科小组有医生和工程师。", "target_word": "跨学科", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跨学科的课让我学到很多东西。", "target_word": "跨学科", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想选一门跨学科的课。", "target_word": "跨学科", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "同时用到几个不同学科的知识", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ac6ae9e-65f2-4cd8-afbe-fbecadfb9dc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25394, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跨学科", "is_correct": true, "explanation": "正确：跨学科指用不同科目的知识，与“这门课是跨学科的”相符。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：课程没有性格，不能说“温柔”。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：课程是抽象的，没有高矮大小，不能说“高大”。"}, {"text": "圆形", "is_correct": false, "explanation": "体貌：课程没有形状，不能说“圆形”。"}], "explanations": {"跨学科": "正确：跨学科指用不同科目的知识，与“这门课是跨学科的”相符。", "温柔": "语义：课程没有性格，不能说“温柔”。", "高大": "体貌：课程是抽象的，没有高矮大小，不能说“高大”。", "圆形": "体貌：课程没有形状，不能说“圆形”。"}, "sentence_index": 0, "correct_answer": "跨学科"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两家公司正在做跨学科贸易。", "explanation": "这里应该用〈跨国〉。跨学科指用不同科目的知识，不能用来形容贸易。"}, {"text": "这个城市的文化很跨学科。", "explanation": "这里应该用〈多元〉。跨学科只用于知识和学科，不用于形容文化。"}, {"text": "这是一条跨学科的公交线路。", "explanation": "这里应该用〈跨区域〉。跨学科指用不同科目的知识，不能用来形容公交线路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25394, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跨学科", "is_correct": true, "explanation": "正确：跨学科说明研究涉及多个学科，与“他做的是跨学科研究”相符。"}, {"text": "咸", "is_correct": false, "explanation": "语义：研究没有咸淡，不能说“咸”。"}, {"text": "脆", "is_correct": false, "explanation": "语义：“脆”只说食物的口感，不能形容研究。"}, {"text": "高耸", "is_correct": false, "explanation": "搭配：“高耸”形容建筑或山峰，不能和“研究”搭配。"}], "explanations": {"跨学科": "正确：跨学科说明研究涉及多个学科，与“他做的是跨学科研究”相符。", "咸": "语义：研究没有咸淡，不能说“咸”。", "脆": "语义：“脆”只说食物的口感，不能形容研究。", "高耸": "搭配：“高耸”形容建筑或山峰，不能和“研究”搭配。"}, "sentence_index": 6, "correct_answer": "跨学科"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河是跨学科的。", "explanation": "这里应该用〈跨省〉。跨学科指知识涉及不同学科，河流不是知识，不能用它形容。"}, {"text": "这台冰箱功能很跨学科。", "explanation": "这里应该用〈多功能〉。跨学科只说知识涉及多个学科，不能形容机器的功能。"}, {"text": "他的船跨学科航行了一个月。", "explanation": "这里应该用〈跨洋〉。跨学科指知识涉及多门科目，不能用来形容航行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25394, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们这次做的是一项跨学科了的活动。", "corrected_sentence": "我们这次做的是一项跨学科的活动。", "error_description": "助词错误：“跨学科”后面不能加“了”，“跨学科了的”应改为“跨学科的”。正确说法是“一项跨学科的活动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25394, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个项目是跨学科地。", "corrected_sentence": "这个项目是跨学科的。", "error_description": "结构助词错误：“跨学科”作表语时后面应用“的”，不能用“地”（“地”用于修饰动词）。正确说法是“这个项目是跨学科的。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
