INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25396, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大自然就是外面的山、水、树、花和小动物们。", "primary_collocate": null, "pronunciation": "dà zì rán", "ipa": "ta˥˩ tsɻ̩˥˩ ɻan˧˥", "syllable_count": 3, "sentences": [{"text": "周末我们去大自然里走一走。", "target_word": "大自然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大自然里有山，有水，还有花和树。", "target_word": "大自然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们喜欢在大自然里玩。", "target_word": "大自然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大自然的声音让人觉得很放松。", "target_word": "大自然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要爱护大自然，不要乱扔东西。", "target_word": "大自然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他拍了很多大自然的照片。", "target_word": "大自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天的大自然特别漂亮。", "target_word": "大自然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸟和小鱼都是大自然的朋友。", "target_word": "大自然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "住在城市里的人很想去看看大自然。", "target_word": "大自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们到大自然里认识小动物。", "target_word": "大自然", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人类以外的山水草木动物等自然世界", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '474535a0-0dad-4240-b06c-55efe2468b5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25396, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大自然", "is_correct": true, "explanation": "正确。“大自然”指人类以外的山水草木，是可以“去……里走一走”的地方。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，人走不进去，不能去冰箱里走一走。"}, {"text": "抽屉", "is_correct": false, "explanation": "搭配：“走一走”要去的是能步行的场所，不能说在抽屉里走一走。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包太小，人无法在里面散步。"}], "explanations": {"大自然": "正确。“大自然”指人类以外的山水草木，是可以“去……里走一走”的地方。", "冰箱": "语义：冰箱是家用电器，人走不进去，不能去冰箱里走一走。", "抽屉": "搭配：“走一走”要去的是能步行的场所，不能说在抽屉里走一走。", "书包": "语义：书包太小，人无法在里面散步。"}, "sentence_index": 0, "correct_answer": "大自然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间教室的大自然很安静，适合学习。", "explanation": "这里应该用〈环境〉。大自然指人类以外的自然世界，教室是人造的场所，要说“环境”。"}, {"text": "这张桌子是用大自然做的。", "explanation": "这里误用了〈大自然〉。大自然指山、水、树等自然界的景物，不是能做成桌子的材料；做桌子要用〈木头〉。"}, {"text": "这首歌的大自然很好听。", "explanation": "这里误用了〈大自然〉。大自然指山水树花等自然景物，不指音乐；说歌好听要说它的〈旋律〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25396, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大自然", "is_correct": true, "explanation": "正确。“大自然”指自然界，与“春天的……特别漂亮”搭配自然。"}, {"text": "会议", "is_correct": false, "explanation": "语义：会议是活动，不能用“漂亮”来形容。"}, {"text": "电费", "is_correct": false, "explanation": "搭配：电费是钱的数目，不能用“漂亮”来形容。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是一种测验，不是可以被称作漂亮的事物。"}], "explanations": {"大自然": "正确。“大自然”指自然界，与“春天的……特别漂亮”搭配自然。", "会议": "语义：会议是活动，不能用“漂亮”来形容。", "电费": "搭配：电费是钱的数目，不能用“漂亮”来形容。", "考试": "语义：考试是一种测验，不是可以被称作漂亮的事物。"}, "sentence_index": 6, "correct_answer": "大自然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "动物园里有很多大自然。", "explanation": "这里应该用〈动物〉。大自然指自然界，不是能被关进动物园的东西，动物园里有的是动物。"}, {"text": "这个大自然有很多高楼。", "explanation": "这里应该用〈城市〉。大自然是人类以外的自然世界，高楼只属于城市。"}, {"text": "他每天早上都喝一杯大自然。", "explanation": "这里误用了〈大自然〉。大自然指山水树花等自然界的景物，不是能喝的东西；喝的应该是〈牛奶〉之类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25396, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小朋友们周末喜欢在大自然上跑一跑。", "corrected_sentence": "小朋友们周末喜欢在大自然里跑一跑。", "error_description": "方位词错误：“大自然”是一个范围很大的空间，要说“在大自然里”，不能说“在大自然上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25396, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们放假时喜欢大自然里玩。", "corrected_sentence": "孩子们放假时喜欢在大自然里玩。", "error_description": "介词缺失：“喜欢大自然里玩”少了“在”。“大自然”是活动的地点，要用“在……里”引出，应说“孩子们放假时喜欢在大自然里玩”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
