INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25398, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "非常小的生物，要用显微镜才能看到，有的会让我们生病。", "primary_collocate": null, "pronunciation": "xì jūn", "ipa": "ɕi˥˩ tɕyn˥", "syllable_count": 2, "sentences": [{"text": "细菌很小，要用显微镜才能看到。", "target_word": "细菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的细菌会让我们生病。", "target_word": "细菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "脏衣服上有很多细菌。", "target_word": "细菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾桶里有很多细菌，别用手碰。", "target_word": "细菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生病的时候，医生会给我药，杀死身体里的细菌。", "target_word": "细菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水不干净，里面可能有细菌。", "target_word": "细菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道吗？空气里也有细菌。", "target_word": "细菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机屏幕上也有很多细菌。", "target_word": "细菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "煮开的水里没有细菌，可以放心喝。", "target_word": "细菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，吃东西以前先洗手，不然会带进细菌。", "target_word": "细菌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "细菌·很小的生物·让人生病", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f3bbb28-ef77-4126-94bd-0d4dcabd7445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25398, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "细菌", "is_correct": true, "explanation": "细菌很小，要用显微镜才能看到，符合句意。"}, {"text": "大象", "is_correct": false, "explanation": "语义：大象体形庞大，与「很小」矛盾。"}, {"text": "大楼", "is_correct": false, "explanation": "语义：大楼体积庞大，与「很小」「要用显微镜才能看到」矛盾。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳肉眼就能看到，不需要用显微镜。"}], "explanations": {"细菌": "细菌很小，要用显微镜才能看到，符合句意。", "大象": "语义：大象体形庞大，与「很小」矛盾。", "大楼": "语义：大楼体积庞大，与「很小」「要用显微镜才能看到」矛盾。", "太阳": "语义：太阳肉眼就能看到，不需要用显微镜。"}, "sentence_index": 0, "correct_answer": "细菌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个细菌太重了，我一个人搬不动。", "explanation": "这里应该用〈箱子〉。细菌非常小，要用显微镜才能看到，不会重得搬不动。"}, {"text": "手机中了木马，是因为里面有细菌。", "explanation": "这里应该用〈病毒〉。手机中毒是病毒造成的，细菌不用来说电子设备的故障。"}, {"text": "公园的树上有几个细菌在唱歌。", "explanation": "这里应该用〈小鸟〉。小鸟会在树上唱歌；细菌很小，看不见，也不会唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25398, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "细菌", "is_correct": true, "explanation": "细菌在空气中也存在，符合句意。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼生活在水中，空气里不会有鱼。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不会存在于空气中。"}, {"text": "皮鞋", "is_correct": false, "explanation": "搭配：「空气里也有」指看不见的微粒，皮鞋不能这样说。"}], "explanations": {"细菌": "细菌在空气中也存在，符合句意。", "鱼": "语义：鱼生活在水中，空气里不会有鱼。", "桌子": "语义：桌子是家具，不会存在于空气中。", "皮鞋": "搭配：「空气里也有」指看不见的微粒，皮鞋不能这样说。"}, "sentence_index": 6, "correct_answer": "细菌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑的细菌坏了，要送去修。", "explanation": "这里应该用〈硬盘〉。硬盘是电脑的部件，会坏、要修；细菌不是电脑的部件。"}, {"text": "人的身体是由很多细菌组成的。", "explanation": "这里应该用〈细胞〉。人体由细胞组成，细菌不是构成人体的单位。"}, {"text": "蛔虫是一种细菌。", "explanation": "这里应该用〈寄生虫〉。蛔虫属于动物，是寄生虫，不是细菌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25398, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块布上有一只细菌，它很小。", "corrected_sentence": "这块布上有一种细菌，它很小。", "error_description": "「细菌」的量词应用「种」或「个」，「只」多用于动物。「一只细菌」错误，应为「一种细菌」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25398, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "洗手可以把细菌洗。", "corrected_sentence": "洗手可以把细菌洗掉。", "error_description": "「把」字句中，动词后要有结果补语等成分，「把细菌洗」意思不完整，应为「把细菌洗掉」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
