INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25400, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种塑料，可以在大自然里自己分解消失，不会一直留在垃圾里。", "primary_collocate": null, "pronunciation": "jiàng jiě sù liào", "ipa": "tɕjɑŋ˥˩ tɕjɛ˨˩˦ su˥˩ ljaʊ˥˩", "syllable_count": 4, "sentences": [{"text": "这个杯子是降解塑料做的。", "target_word": "降解塑料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "降解塑料不会一直留在地里。", "target_word": "降解塑料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "超市开始用降解塑料袋了。", "target_word": "降解塑料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "降解塑料可以自己分解。", "target_word": "降解塑料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他买了一个降解塑料饭盒。", "target_word": "降解塑料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用降解塑料能少一些垃圾。", "target_word": "降解塑料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的吸管是降解塑料的。", "target_word": "降解塑料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "降解塑料比普通塑料贵一点。", "target_word": "降解塑料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司想用降解塑料做新瓶子。", "target_word": "降解塑料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "降解塑料在土里会慢慢消失。", "target_word": "降解塑料", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "能在自然中分解消失的塑料材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ac6ae9e-65f2-4cd8-afbe-fbecadfb9dc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25400, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "降解塑料", "is_correct": true, "explanation": "正确：这个杯子是用降解塑料做的，与句子相符。"}, {"text": "故事", "is_correct": false, "explanation": "语义：“故事”不是材料，不能用来做杯子。"}, {"text": "掌声", "is_correct": false, "explanation": "搭配：“掌声”是声音，不能说“是……做的”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是气体，不能用来做成杯子。"}], "explanations": {"降解塑料": "正确：这个杯子是用降解塑料做的，与句子相符。", "故事": "语义：“故事”不是材料，不能用来做杯子。", "掌声": "搭配：“掌声”是声音，不能说“是……做的”。", "空气": "语义：空气是气体，不能用来做成杯子。"}, "sentence_index": 0, "correct_answer": "降解塑料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只降解塑料。", "explanation": "这里应该用〈种〉。塑料是材料，量词用“种”，不用“只”。"}, {"text": "这些衣服降解塑料了。", "explanation": "这里应该用〈降价〉。降解塑料指材料能分解，不能用来说衣服的价格变化。"}, {"text": "天气降解塑料了。", "explanation": "这里应该用〈降温〉。降解塑料指材料能被分解，不能用来形容天气变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25400, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "降解塑料", "is_correct": true, "explanation": "正确：吸管是用降解塑料做的，与句子相符。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”不是材料，不能用来做吸管。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“温度”说高低冷热，不说“是……的”材料。"}, {"text": "歌声", "is_correct": false, "explanation": "语义：歌声是声音，不是材料，不能做吸管。"}], "explanations": {"降解塑料": "正确：吸管是用降解塑料做的，与句子相符。", "心情": "语义：“心情”不是材料，不能用来做吸管。", "温度": "搭配：“温度”说高低冷热，不说“是……的”材料。", "歌声": "语义：歌声是声音，不是材料，不能做吸管。"}, "sentence_index": 6, "correct_answer": "降解塑料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我口渴了，喝了一杯降解塑料。", "explanation": "这里应该用〈果汁〉。降解塑料是用来做杯子、袋子的材料，不能喝。"}, {"text": "老师在降解塑料题目。", "explanation": "这里应该用〈解释〉。降解塑料指材料能分解，不能用来形容讲解题目。"}, {"text": "物价降解塑料了很多。", "explanation": "这里应该用〈下降〉。降解塑料指材料能分解，不能用来形容物价变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25400, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂买了一个降解塑料。", "corrected_sentence": "工厂买了一种降解塑料。", "error_description": "量词错误：降解塑料是材料，应用“种”，“个”不能修饰材料。正确说法是“工厂买了一种降解塑料”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25400, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家超市改用降解塑料地袋了。", "corrected_sentence": "这家超市改用降解塑料袋了。", "error_description": "结构助词错误：“降解塑料”修饰“袋”时直接接名词，中间不能加“地”（“地”用于修饰动词）。正确说法是“这家超市改用降解塑料袋了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25402, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合并", "is_correct": true, "explanation": "合并：把分开的部分合在一起，与「分成」的分开方向相反。"}, {"text": "建造", "is_correct": false, "explanation": "无关：「建造」指修建房屋等，与「分成」没有反义关系。"}, {"text": "阅读", "is_correct": false, "explanation": "无关：「阅读」指看书报，与「分成」没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "无关：「唱歌」指发出歌声，与「分成」没有反义关系。"}], "correct_answer": "合并", "explanations": {"合并": "合并：把分开的部分合在一起，与「分成」的分开方向相反。", "建造": "无关：「建造」指修建房屋等，与「分成」没有反义关系。", "阅读": "无关：「阅读」指看书报，与「分成」没有反义关系。", "唱歌": "无关：「唱歌」指发出歌声，与「分成」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25402, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合并", "is_correct": true, "explanation": "合并：把分开的部分合在一起，与「分成」的分开方向相反。"}, {"text": "种植", "is_correct": false, "explanation": "无关：「种植」指把植物种在土里，与「分成」没有反义关系。"}, {"text": "检查", "is_correct": false, "explanation": "无关：「检查」指仔细查看，与「分成」没有反义关系。"}, {"text": "打扫", "is_correct": false, "explanation": "无关：「打扫」指清除脏物，与「分成」没有反义关系。"}], "correct_answer": "合并", "explanations": {"合并": "合并：把分开的部分合在一起，与「分成」的分开方向相反。", "种植": "无关：「种植」指把植物种在土里，与「分成」没有反义关系。", "检查": "无关：「检查」指仔细查看，与「分成」没有反义关系。", "打扫": "无关：「打扫」指清除脏物，与「分成」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25402, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把整体切开或分开成几部分，让人看到里面不一样的部分。", "primary_collocate": null, "pronunciation": "fēn chéng", "ipa": "fən˥ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "把西瓜分成两半，就能看到红红的瓜肉。", "target_word": "分成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把蛋糕分成两半，里面有三层不同的颜色。", "target_word": "分成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把洋葱分成两半，让我们看里面的样子。", "target_word": "分成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把梨分成两半，我们看到里面很白。", "target_word": "分成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把苹果分成两半，你会看到里面的小星星。", "target_word": "分成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把煮熟的鸡蛋分成两半，能看到白的和黄的。", "target_word": "分成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这个面包分成两半，里面有不一样的馅。", "target_word": "分成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟把橘子分成两半，给我看里面的小块。", "target_word": "分成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把花分成几部分，让我们看清花瓣和花心。", "target_word": "分成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这块巧克力分成两半，里面有红色的果酱。", "target_word": "分成", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分成了", "label": "体标"}, {"form": "分成过", "label": "体标"}], "register": "中性", "sense_fingerprint": "分成·分开后露出里面不同的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f3bbb28-ef77-4126-94bd-0d4dcabd7445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25402, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分成", "is_correct": true, "explanation": "分成：把西瓜打开成两半，让瓜肉露出来，符合句意。"}, {"text": "包", "is_correct": false, "explanation": "语义：包是裹住，不会让瓜肉露出来，与句意矛盾。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：「擦」不能带「两半」这样的结果宾语。"}, {"text": "保存", "is_correct": false, "explanation": "语义：保存是留住完整，不会把西瓜切开让瓜肉露出来。"}], "explanations": {"分成": "分成：把西瓜打开成两半，让瓜肉露出来，符合句意。", "包": "语义：包是裹住，不会让瓜肉露出来，与句意矛盾。", "擦": "搭配：「擦」不能带「两半」这样的结果宾语。", "保存": "语义：保存是留住完整，不会把西瓜切开让瓜肉露出来。"}, "sentence_index": 0, "correct_answer": "分成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "把这封信分成了三只小猫，大家都很高兴。", "explanation": "这里不能用〈分成〉。〈分成〉的结果必须是原物的部分，“三只小猫”不是信的部分，搭配不通。"}, {"text": "我把弟弟分成两半，给妈妈看。", "explanation": "这里不能用〈分成〉。〈分成〉的对象只能是可以切开的物品，「弟弟」是人，人不能被切成两半给别人看，这是搭配错误。"}, {"text": "妈妈把蛋糕分成了我们。", "explanation": "这里应该用〈分给〉。「分成」的结果是部分，不能指向人，把东西给人要用〈分给〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25402, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分成", "is_correct": true, "explanation": "分成：把面包切成两半，露出里面的馅，符合句意。"}, {"text": "装", "is_correct": false, "explanation": "搭配：「装」的宾语是放进容器里的东西，不能说把面包装成两半。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：「挂」指悬挂，面包不能这样被分成两半。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：吃掉会把面包吃光，就看不到里面的馅了，与句意矛盾。"}], "explanations": {"分成": "分成：把面包切成两半，露出里面的馅，符合句意。", "装": "搭配：「装」的宾语是放进容器里的东西，不能说把面包装成两半。", "挂": "搭配：「挂」指悬挂，面包不能这样被分成两半。", "吃掉": "语义：吃掉会把面包吃光，就看不到里面的馅了，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "分成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两条小路分成了一条路。", "explanation": "这里应该用〈汇成〉。两条路合到一起是“汇成一条路”；「分成」是把整体分开，意思正好相反。"}, {"text": "这些颜料分成了一种新颜色。", "explanation": "这里应该用〈合成〉。颜料混合后才得到新颜色，「分成」是把整体分开。"}, {"text": "他分成了我们的小组。", "explanation": "这里应该用〈加入〉。人是加入小组，而不是被分成小组。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25402, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "把橘子分成在两半，就能看到一瓣一瓣的果肉。", "corrected_sentence": "把橘子分成两半，就能看到一瓣一瓣的果肉。", "error_description": "搭配错：「分成」后直接接结果宾语「两半」，中间不能插入「在」，应为「把橘子分成两半」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25402, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个面包可以分成了两半，里面有馅。", "corrected_sentence": "这个面包可以分成两半，里面有馅。", "error_description": "「可以」表示可能，后面的动词不能再加「了」。「可以分成了两半」错误，应为「可以分成两半」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
