INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25406, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "对做某件事有帮助或作用。", "primary_collocate": null, "pronunciation": "yǒu zhù yú", "ipa": "joʊ˨˩˦ ʈʂu˥˩ y˧˥", "syllable_count": 3, "sentences": [{"text": "多喝水有助于身体健康。", "target_word": "有助于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "早睡早起有助于学习。", "target_word": "有助于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "看书有助于提高中文水平。", "target_word": "有助于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多听多说有助于学好汉语。", "target_word": "有助于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每天运动有助于睡个好觉。", "target_word": "有助于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，做笔记有助于记住新词。", "target_word": "有助于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃早饭有助于让人一上午都有精神。", "target_word": "有助于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次谈话有助于我们互相了解。", "target_word": "有助于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "安静的环境有助于孩子专心写作业。", "target_word": "有助于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "和当地人聊天，有助于你更快地学会说中文。", "target_word": "有助于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "对某件事有帮助、有益处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e373b1f0-8529-4f99-bdb4-29789ab94d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25406, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有助于", "is_correct": true, "explanation": "正确。“多喝水有助于身体健康”，表示对身体有好处。"}, {"text": "有害于", "is_correct": false, "explanation": "语义：“多喝水”对身体有好处，“有害于”说的是坏处，与句意矛盾。"}, {"text": "不利于", "is_correct": false, "explanation": "语义：“不利于身体健康”与“多喝水”的好处相反，不符合常识。"}, {"text": "等于", "is_correct": false, "explanation": "搭配：“等于”表示数量或概念相同，不能说“多喝水等于身体健康”。"}], "explanations": {"有助于": "正确。“多喝水有助于身体健康”，表示对身体有好处。", "有害于": "语义：“多喝水”对身体有好处，“有害于”说的是坏处，与句意矛盾。", "不利于": "语义：“不利于身体健康”与“多喝水”的好处相反，不符合常识。", "等于": "搭配：“等于”表示数量或概念相同，不能说“多喝水等于身体健康”。"}, "sentence_index": 0, "correct_answer": "有助于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师一直有助于我，我很感激她。", "explanation": "这里应该用〈帮助〉。“有助于”的主语应是事情或做法，不能是人；说老师给我帮助，要用“帮助”。"}, {"text": "他讲的笑话有助于大家的笑声。", "explanation": "这里应该用〈引起〉。“有助于”表示对做某事有帮助，“笑声”是笑话直接带来的反应，应说“引起大家的笑声”。"}, {"text": "他这样做有助于大家的危险。", "explanation": "这里应该用〈威胁〉。“有助于”表示带来好处，说对大家带来危险，应该用“威胁”，不能用“有助于”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25406, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有助于", "is_correct": true, "explanation": "正确。“吃早饭有助于让人一上午都有精神”，表示早饭对精神有好处。"}, {"text": "妨碍", "is_correct": false, "explanation": "语义：“妨碍”表示阻碍，与“让人一上午都有精神”的积极作用相反。"}, {"text": "包括", "is_correct": false, "explanation": "语义：“包括”表示包含关系，句子说的是因果效果，不是包含。"}, {"text": "表示", "is_correct": false, "explanation": "搭配：“表示”后接意义或态度，不能接“让人有精神”这样的结果。"}], "explanations": {"有助于": "正确。“吃早饭有助于让人一上午都有精神”，表示早饭对精神有好处。", "妨碍": "语义：“妨碍”表示阻碍，与“让人一上午都有精神”的积极作用相反。", "包括": "语义：“包括”表示包含关系，句子说的是因果效果，不是包含。", "表示": "搭配：“表示”后接意义或态度，不能接“让人有精神”这样的结果。"}, "sentence_index": 6, "correct_answer": "有助于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场大雨有助于很大的损失。", "explanation": "这里应该用〈造成〉。“有助于”表示带来帮助或好处，说带来坏的结果要用“造成很大的损失”。"}, {"text": "这个消息很有助于大家的哭声。", "explanation": "这里应该用〈引起〉。“有助于”表示带来帮助，“哭声”是情绪反应，不能说“有助于”，应说“引起”大家的哭声。"}, {"text": "护士每天有助于病人，病人都很感激。", "explanation": "这里应该用〈照顾〉。“有助于”的主语应是事情或做法，不能是人；护士照顾病人要用“照顾”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25406, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个方法有助于了我提高成绩。", "corrected_sentence": "这个方法有助于我提高成绩。", "error_description": "多余的“了”。“有助于”后应直接接宾语“我”，“了”不能插在“于”和“我”之间，应说“这个方法有助于我提高成绩”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25406, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "规律作息有助于于身体健康。", "corrected_sentence": "规律作息有助于身体健康。", "error_description": "多余的“于”。“有助于”是一个整体动词，“于”已经包含在其中，不能再加一个“于”，应说“规律作息有助于身体健康”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
