INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25408, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很多小分子连在一起变成的大分子。", "primary_collocate": null, "pronunciation": "jù hé wù", "ipa": "tɕy˥˩ xɤ˧˥ u˥˩", "syllable_count": 3, "sentences": [{"text": "塑料是一种常见的聚合物。", "target_word": "聚合物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "聚合物是由很多小分子连成的大分子。", "target_word": "聚合物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室里正在研究新的聚合物。", "target_word": "聚合物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种聚合物很轻，也很结实。", "target_word": "聚合物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "橡胶是天然的聚合物。", "target_word": "聚合物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用聚合物做了一根水管。", "target_word": "聚合物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋白质也是一种聚合物。", "target_word": "聚合物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加热以后，这种聚合物会变软。", "target_word": "聚合物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "化学老师给我们看了一块聚合物。", "target_word": "聚合物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多衣服的纤维是人造聚合物。", "target_word": "聚合物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种聚合物", "label": "量词"}], "register": "书面", "sense_fingerprint": "由许多小分子连成的大分子化合物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '071f4daf-d2f5-4352-a46c-90263f231feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25408, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "聚合物", "is_correct": true, "explanation": "“聚合物”指由许多小分子连成的大分子，塑料正是这类材料，符合句意。"}, {"text": "金属", "is_correct": false, "explanation": "语义：塑料不是金属，“塑料是一种常见的金属”与事实不符。"}, {"text": "元素", "is_correct": false, "explanation": "搭配：“塑料是一种……”后面的类别要与塑料同类，塑料是化合物，不是元素。"}, {"text": "合金", "is_correct": false, "explanation": "语义：合金是金属混合物，塑料不属于合金。"}], "explanations": {"聚合物": "“聚合物”指由许多小分子连成的大分子，塑料正是这类材料，符合句意。", "金属": "语义：塑料不是金属，“塑料是一种常见的金属”与事实不符。", "元素": "搭配：“塑料是一种……”后面的类别要与塑料同类，塑料是化合物，不是元素。", "合金": "语义：合金是金属混合物，塑料不属于合金。"}, "sentence_index": 0, "correct_answer": "聚合物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "乙烯是一种常见的聚合物。", "explanation": "这里应该用〈单体〉。乙烯是能连成聚合物的小分子，“聚合物”指很多单体连成后的大分子，乙烯本身不是聚合物。"}, {"text": "水是一种常见的聚合物。", "explanation": "这里应该用〈化合物〉。水是由氢和氧组成的小分子化合物，不是许多小分子连成的大分子。"}, {"text": "氧是一种常见的聚合物。", "explanation": "这里应该用〈元素〉。氧是单一的化学元素，不是由许多小分子连成的大分子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25408, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "聚合物", "is_correct": true, "explanation": "“聚合物”是大分子化合物，蛋白质也属于这一类，句中“也是一种”符合句意。"}, {"text": "矿物", "is_correct": false, "explanation": "语义：蛋白质不是矿物，“蛋白质也是一种矿物”说不通。"}, {"text": "脂肪", "is_correct": false, "explanation": "搭配：蛋白质和脂肪是并列的营养素，“也是一种”要求同类，此处说不通。"}, {"text": "维生素", "is_correct": false, "explanation": "语义：蛋白质不是维生素，两者性质不同。"}], "explanations": {"聚合物": "“聚合物”是大分子化合物，蛋白质也属于这一类，句中“也是一种”符合句意。", "矿物": "语义：蛋白质不是矿物，“蛋白质也是一种矿物”说不通。", "脂肪": "搭配：蛋白质和脂肪是并列的营养素，“也是一种”要求同类，此处说不通。", "维生素": "语义：蛋白质不是维生素，两者性质不同。"}, "sentence_index": 6, "correct_answer": "聚合物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个工厂一天能做出一座聚合物。", "explanation": "这里应该用〈一批〉。座用于山、房屋这类大型固定物，聚合物是物质，不能用“座”来量。"}, {"text": "衣服的纤维里有一只聚合物。", "explanation": "这里应该用〈一种〉。只用于动物或成对物品中的一个，聚合物是一类物质，应说“一种聚合物”。"}, {"text": "厂里运来了一间聚合物。", "explanation": "这里应该用〈一批〉。间用于房屋、房间，不能用来量聚合物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25408, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂研发了一种新地聚合物。", "corrected_sentence": "工厂研发了一种新的聚合物。", "error_description": "结构助词错误：修饰名词“聚合物”的定语要用“的”，“地”用于修饰动词，应说“一种新的聚合物”，不能说“新地聚合物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25408, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家工厂今天生产一只新的聚合物。", "corrected_sentence": "这家工厂今天生产一种新的聚合物。", "error_description": "量词错误：“聚合物”是一类物质，量词应用“种”，“只”用于动物等，不能说“一只聚合物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
