INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25412, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "土豆是一种可以吃的长在土里的圆圆的东西。", "primary_collocate": null, "pronunciation": "tǔ dòu", "ipa": "tʰu˨˩˦ toʊ˥˩", "syllable_count": 2, "sentences": [{"text": "土豆长在土里面。", "target_word": "土豆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个土豆圆圆的，很可爱。", "target_word": "土豆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们中午吃了土豆。", "target_word": "土豆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶在家煮土豆。", "target_word": "土豆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明爱吃热热的土豆。", "target_word": "土豆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地里有很多土豆。", "target_word": "土豆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土豆要煮熟了才能吃。", "target_word": "土豆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有两个土豆。", "target_word": "土豆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在菜市场买土豆。", "target_word": "土豆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟不喜欢吃土豆，只喜欢吃肉。", "target_word": "土豆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个土豆", "label": "量词"}, {"form": "土豆泥", "label": "复合"}], "register": "中性", "sense_fingerprint": "长在土里、圆圆的、可以吃的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f52a17a-78f7-4fb3-bb7f-3ca4d49b212e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25412, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "土豆", "is_correct": true, "explanation": "正确：土豆是长在土里的东西，符合句意。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳在天上，不会长在土里。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“长”用于植物或生物，不说汽车长。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮在天上，不会长在土里。"}], "explanations": {"土豆": "正确：土豆是长在土里的东西，符合句意。", "太阳": "语义：太阳在天上，不会长在土里。", "汽车": "搭配：“长”用于植物或生物，不说汽车长。", "月亮": "语义：月亮在天上，不会长在土里。"}, "sentence_index": 0, "correct_answer": "土豆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶在家煮一只土豆。", "explanation": "这里应该用〈个〉。“只”用于动物或成对物品中的一个，土豆用“个”。"}, {"text": "奶奶在家煮一条土豆。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，土豆用“个”。"}, {"text": "奶奶在家煮一张土豆。", "explanation": "这里应该用〈个〉。“张”用于平面的东西，如纸、桌子，土豆用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0defd26-0587-41c1-b427-02bf228d33be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25412, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "土豆", "is_correct": true, "explanation": "正确：土豆煮熟了才能吃，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：石头不是食物，不说煮熟了才能吃。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板不是食物，不能煮熟了吃。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：钢笔不是食物，不能煮熟了吃。"}], "explanations": {"土豆": "正确：土豆煮熟了才能吃，符合句意。", "石头": "搭配：石头不是食物，不说煮熟了才能吃。", "黑板": "语义：黑板不是食物，不能煮熟了吃。", "钢笔": "语义：钢笔不是食物，不能煮熟了吃。"}, "sentence_index": 6, "correct_answer": "土豆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "土豆长在树上，结了很多果子。", "explanation": "这里应该用〈苹果树〉。苹果树长在地上，会结很多果子；土豆长在土里，不会长在树上结果子。"}, {"text": "这个土豆很酸，适合做饮料。", "explanation": "这里应该用〈柠檬〉。柠檬味道酸，土豆没有酸味，“很酸”要用柠檬。"}, {"text": "妈妈用土豆磨了豆浆，很香。", "explanation": "这里应该用〈黄豆〉。豆浆要用黄豆磨成，土豆不能用来做豆浆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0defd26-0587-41c1-b427-02bf228d33be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25412, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "篮子里有三只土豆。", "corrected_sentence": "篮子里有三个土豆。", "error_description": "量词用错：土豆应用“个”，不说“只”。“只”多用于动物或成对物品中的一个。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0defd26-0587-41c1-b427-02bf228d33be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25412, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶年轻时种过一条土豆。", "corrected_sentence": "奶奶年轻时种过一片土豆。", "error_description": "量词用错：“条”用于细长的东西，土豆成片种植应说“一片土豆”，不说“一条土豆”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0defd26-0587-41c1-b427-02bf228d33be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
