INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25418, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "这个词表示在平常的日子中。", "primary_collocate": null, "pronunciation": "zài shēng huó zhōng", "ipa": "tsaɪ˥˩ ʂɤŋ˥ xuo˧˥ ʈʂʊŋ˥", "syllable_count": 4, "sentences": [{"text": "在生活中，我们每天都要吃饭、睡觉。", "target_word": "在生活中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在生活中是一个安静的人。", "target_word": "在生活中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在生活中，爸爸比工作时轻松多了。", "target_word": "在生活中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在生活中，他不太爱说话。", "target_word": "在生活中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些小问题在生活中常常遇到。", "target_word": "在生活中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在生活中，朋友的一句话也很重要。", "target_word": "在生活中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在生活中很节约，从不浪费水。", "target_word": "在生活中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在生活中，我喜欢听音乐放松自己。", "target_word": "在生活中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在生活中，他是个很有耐心的人。", "target_word": "在生活中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在生活中，每个人都会遇到不开心的事。", "target_word": "在生活中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "在生活中-在平常的日子里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c937a50d-2199-49ee-9ea8-5faf8f53680f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25418, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "在生活中", "is_correct": true, "explanation": "正确：“在生活中”指平常的日子，与“每天都要”的一般性描述相符。"}, {"text": "偶尔", "is_correct": false, "explanation": "搭配：“偶尔”表示很少发生，与“每天都要”矛盾，不能搭配。"}, {"text": "一年一次", "is_correct": false, "explanation": "频率：“一年一次”与“每天都要吃饭、睡觉”的说法矛盾，不能搭配。"}, {"text": "每周一次", "is_correct": false, "explanation": "频率：“每周一次”与“每天都要吃饭、睡觉”的说法矛盾，不能搭配。"}], "explanations": {"在生活中": "正确：“在生活中”指平常的日子，与“每天都要”的一般性描述相符。", "偶尔": "搭配：“偶尔”表示很少发生，与“每天都要”矛盾，不能搭配。", "一年一次": "频率：“一年一次”与“每天都要吃饭、睡觉”的说法矛盾，不能搭配。", "每周一次": "频率：“每周一次”与“每天都要吃饭、睡觉”的说法矛盾，不能搭配。"}, "sentence_index": 0, "correct_answer": "在生活中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨天在生活中，他考了第一名。", "explanation": "这里应该用〈在考试中〉。“在生活中”指平常的日子，不能用来说明某次考试的结果。"}, {"text": "桌子在生活中放在厨房里。", "explanation": "此句错在把“在生活中”当作位置使用。它表示平常的日子，不能说明物体的位置。"}, {"text": "这次比赛，他在生活中拿到了冠军。", "explanation": "这里应该用〈在比赛中〉。“在生活中”指平常的日子，不能用来说明具体比赛的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25418, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "在生活中", "is_correct": true, "explanation": "正确：“在生活中”说明日常中的表现，句意通顺。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”指一时发生的变化，与“很节约”“从不浪费水”的长期习惯不合。"}, {"text": "在梦里", "is_correct": false, "explanation": "语义：梦里的情境不是现实中的日常表现，与“妈妈很节约”的描述不合。"}, {"text": "一下子", "is_correct": false, "explanation": "搭配：“一下子”表示短时间内完成的动作，不能修饰“很节约、从不浪费水”这类长期状态。"}], "explanations": {"在生活中": "正确：“在生活中”说明日常中的表现，句意通顺。", "突然": "语义：“突然”指一时发生的变化，与“很节约”“从不浪费水”的长期习惯不合。", "在梦里": "语义：梦里的情境不是现实中的日常表现，与“妈妈很节约”的描述不合。", "一下子": "搭配：“一下子”表示短时间内完成的动作，不能修饰“很节约、从不浪费水”这类长期状态。"}, "sentence_index": 6, "correct_answer": "在生活中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨天在生活中，我参加了一场婚礼。", "explanation": "此句中“在生活中”表示平常的日子，不能用来说明昨天某次具体的活动，这里不这样用。"}, {"text": "请把杯子放在生活中。", "explanation": "此句把“在生活中”当作具体位置。它表示平常的日子，不能指放东西的地方。"}, {"text": "这次出差，他在生活中见到了老朋友。", "explanation": "此句中“在生活中”表示平常的日子，不能用来说明某次出差中的具体经历，这里不这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25418, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在生活中里，人们常常会遇到小麻烦。", "corrected_sentence": "在生活中，人们常常会遇到小麻烦。", "error_description": "多余成分：“在生活中”已含方位词“中”，后面不能再加“里”。把“在生活中里”改为“在生活中”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25418, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在生活中的，人们需要学会等待。", "corrected_sentence": "在生活中，人们需要学会等待。", "error_description": "结构错误：句首状语“在生活中”后多加了“的”，接逗号后成为无中心语的悬空结构；删去“的”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25420, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "看得见", "is_correct": true, "explanation": "反义：「看得见」与「看不见」相对，表示能用眼睛看到。"}, {"text": "摸到", "is_correct": false, "explanation": "非反义：「摸到」指用手碰到，与视觉无关，不是相对义。"}, {"text": "尝到", "is_correct": false, "explanation": "非反义：「尝到」指用舌头感受味道，不是视觉上的相对义。"}, {"text": "想到", "is_correct": false, "explanation": "非反义：「想到」指在脑中想起，与「看不见」不构成反义。"}], "correct_answer": "看得见", "explanations": {"看得见": "反义：「看得见」与「看不见」相对，表示能用眼睛看到。", "摸到": "非反义：「摸到」指用手碰到，与视觉无关，不是相对义。", "尝到": "非反义：「尝到」指用舌头感受味道，不是视觉上的相对义。", "想到": "非反义：「想到」指在脑中想起，与「看不见」不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aa7f61f-2729-4d5d-99e7-c6c8d654eeee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25420, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "看得见", "is_correct": true, "explanation": "反义：「看得见」与「看不见」相对，表示能用眼睛看到。"}, {"text": "闻到", "is_correct": false, "explanation": "非反义：「闻到」指用鼻子感知气味，与视觉无关，不是相对义。"}, {"text": "吃掉", "is_correct": false, "explanation": "非反义：「吃掉」指吞下食物，与「看不见」没有相对关系。"}, {"text": "听到", "is_correct": false, "explanation": "非反义：「听到」指用耳朵感知声音，不是视觉上的相对义。"}], "correct_answer": "看得见", "explanations": {"看得见": "反义：「看得见」与「看不见」相对，表示能用眼睛看到。", "闻到": "非反义：「闻到」指用鼻子感知气味，与视觉无关，不是相对义。", "吃掉": "非反义：「吃掉」指吞下食物，与「看不见」没有相对关系。", "听到": "非反义：「听到」指用耳朵感知声音，不是视觉上的相对义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aa7f61f-2729-4d5d-99e7-c6c8d654eeee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25420, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "眼睛看不到东西。", "primary_collocate": null, "pronunciation": "kàn bu jiàn", "ipa": "kʰan˥˩ pu tɕjɛn˥˩", "syllable_count": 3, "sentences": [{"text": "停电了，屋里黑黑的，我什么都看不见。", "target_word": "看不见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的眼睛生病了，现在什么也看不见。", "target_word": "看不见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没戴眼镜，我连黑板都看不见。", "target_word": "看不见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雾太大，司机看不见前面的路。", "target_word": "看不见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "灯关了，孩子在黑暗里看不见东西。", "target_word": "看不见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "阳光太亮，我一下子看不见了。", "target_word": "看不见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是盲人，什么都看不见，但是听得很清楚。", "target_word": "看不见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蒙上眼睛，你就看不见周围的东西了。", "target_word": "看不见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外面下大雨，窗户上都是水，我看不见外面。", "target_word": "看不见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年纪大了，眼睛不好，连大门口的牌子都看不见。", "target_word": "看不见", "complexity_tier": "T3", "furigana": "yéye niánjì dà le, yǎnjing bù hǎo, lián dàmén kǒu de páizi dōu kàn bú jiàn.", "sentence_source": "generated"}], "morphological_forms": [{"form": "看得见", "label": "反义形式"}, {"form": "看不见了", "label": "体标"}], "register": "中性", "sense_fingerprint": "人因黑暗、视力差或遮挡等原因眼睛看不到东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '859509cb-ef91-48f7-818c-847e5d1c3de5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25420, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看不见", "is_correct": true, "explanation": "正确。停电后屋里黑，眼睛看不到东西，与前文一致。"}, {"text": "看得见", "is_correct": false, "explanation": "语义：「看得见」与「停电」「黑黑的」矛盾，句子会说眼睛能看到东西。"}, {"text": "看得清", "is_correct": false, "explanation": "语义：「看得清」说能看清楚，与「屋里黑黑的」矛盾。"}, {"text": "看不起", "is_correct": false, "explanation": "搭配：「看不起」用于瞧不起人，不能与「什么都」搭配指看不到东西。"}], "explanations": {"看不见": "正确。停电后屋里黑，眼睛看不到东西，与前文一致。", "看得见": "语义：「看得见」与「停电」「黑黑的」矛盾，句子会说眼睛能看到东西。", "看得清": "语义：「看得清」说能看清楚，与「屋里黑黑的」矛盾。", "看不起": "搭配：「看不起」用于瞧不起人，不能与「什么都」搭配指看不到东西。"}, "sentence_index": 0, "correct_answer": "看不见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说的话太快，我看不见。", "explanation": "这里应该用〈听不懂〉。看不见指眼睛看不到东西，不能用于听不懂说话的内容。"}, {"text": "这种新的说话方式，我还看不见。", "explanation": "这里应该用〈看不惯〉。看不见只说眼睛看不到，表示不习惯某种做法要用看不惯。"}, {"text": "他这样欺负小孩，我真看不见。", "explanation": "这里应该用〈看不过去〉。看不见只说眼睛看不到，表示不忍心看下去要用看不过去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aa7f61f-2729-4d5d-99e7-c6c8d654eeee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25420, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看不见", "is_correct": true, "explanation": "正确。盲人眼睛看不到东西，后半句说听得清楚，与前文一致。"}, {"text": "看见", "is_correct": false, "explanation": "语义：「看见」与「他是盲人」矛盾，盲人不能什么都看见。"}, {"text": "听不见", "is_correct": false, "explanation": "语义：「听不见」与后半句「听得很清楚」矛盾。"}, {"text": "吃不下", "is_correct": false, "explanation": "语义：「吃不下」指不能进食，与盲人的情况和后半句的转折不相符。"}], "explanations": {"看不见": "正确。盲人眼睛看不到东西，后半句说听得清楚，与前文一致。", "看见": "语义：「看见」与「他是盲人」矛盾，盲人不能什么都看见。", "听不见": "语义：「听不见」与后半句「听得很清楚」矛盾。", "吃不下": "语义：「吃不下」指不能进食，与盲人的情况和后半句的转折不相符。"}, "sentence_index": 6, "correct_answer": "看不见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "吵得很，我看不见你说话的声音。", "explanation": "这里应该用〈听不见〉。看不见说的是眼睛看不到，听别人说话要用听不见。"}, {"text": "厨房里没有煤气，我看不见味道。", "explanation": "这里应该用〈闻不到〉。看不见只说眼睛看不到，感受气味要用闻不到。"}, {"text": "这首歌很好听，他看不见旋律。", "explanation": "这里应该用〈听不出〉。看不见指眼睛看不到东西，旋律要靠耳朵辨认，应说听不出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aa7f61f-2729-4d5d-99e7-c6c8d654eeee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25420, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屋子里太暗，我看不见把桌子上的书。", "corrected_sentence": "屋子里太暗，我看不见桌子上的书。", "error_description": "错误形式：「看不见把桌子上的书」；正确形式：「看不见桌子上的书」。「看不见」后面不能再加「把」引出宾语，宾语应直接放在动词之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aa7f61f-2729-4d5d-99e7-c6c8d654eeee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25420, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他躲在门后，我一下子看不见了他。", "corrected_sentence": "他躲在门后，我一下子看不见他。", "error_description": "错误形式：「看不见了他」；「了」插在补语和宾语之间，不符合语序。正确形式：「看不见他」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aa7f61f-2729-4d5d-99e7-c6c8d654eeee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
