INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25424, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让不好的结果或局面出现。", "primary_collocate": null, "pronunciation": "zào chéng", "ipa": "tsɑʊ˥˩ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "大雨造成了很多地方的水灾。", "target_word": "造成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不好的习惯可能造成健康问题。", "target_word": "造成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场车祸造成了三个人受伤。", "target_word": "造成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的粗心造成了这次错误。", "target_word": "造成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太多的汽车造成了城市的空气污染。", "target_word": "造成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的大雪造成交通堵塞。", "target_word": "造成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长时间玩手机会造成眼睛疲劳。", "target_word": "造成", "complexity_tier": "T3", "furigana": "cháng shí jiān wán shǒu jī huì zào chéng yǎn jīng pí láo。", "sentence_source": "generated"}, {"text": "谁造成了这个问题？", "target_word": "造成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次失败是他不努力造成的。", "target_word": "造成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，他的错误没有造成大麻烦。", "target_word": "造成", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "造成了", "label": "体标"}, {"form": "造成过", "label": "体标"}], "register": "中性", "sense_fingerprint": "导致不好的结果或局面出现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f9422c-71d5-4159-b92d-1d18b93b36af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25424, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "造成", "is_correct": true, "explanation": "正确答案。造成（zào chéng）指让不好的结果或局面出现。"}, {"text": "凿成", "is_correct": false, "explanation": "凿成（záo chéng）第一音节 záo（第二声）与 zào（第四声）声调不同，意思是用工具凿出某种形状。"}, {"text": "做成", "is_correct": false, "explanation": "做成（zuò chéng）第一音节 zuò 与 zào 韵母不同（uo 与 ao），意思是做出某个东西。"}, {"text": "炒成", "is_correct": false, "explanation": "炒成（chǎo chéng）第一音节 chǎo 与 zào 声母和声调都不同（ch 与 z），意思是炒出某道菜。"}, {"text": "早成", "is_correct": false, "explanation": "早成（zǎo chéng）第一音节 zǎo（第三声）与 zào（第四声）声调不同，意思是较早形成或完成。"}], "explanations": {"造成": "正确答案。造成（zào chéng）指让不好的结果或局面出现。", "凿成": "凿成（záo chéng）第一音节 záo（第二声）与 zào（第四声）声调不同，意思是用工具凿出某种形状。", "做成": "做成（zuò chéng）第一音节 zuò 与 zào 韵母不同（uo 与 ao），意思是做出某个东西。", "炒成": "炒成（chǎo chéng）第一音节 chǎo 与 zào 声母和声调都不同（ch 与 z），意思是炒出某道菜。", "早成": "早成（zǎo chéng）第一音节 zǎo（第三声）与 zào（第四声）声调不同，意思是较早形成或完成。"}, "sentence_index": null, "correct_answer": "造成"}, "level_3": {"options": [{"text": "享受", "is_correct": false, "explanation": "语义：“享受”指愉快地接受好的事物，不能用于灾害。"}, {"text": "造成", "is_correct": true, "explanation": "正确。“造成”指引起某种结果，与“大雨……水灾”的因果关系相符。"}, {"text": "通过", "is_correct": false, "explanation": "配价：“通过”要求可以被经过或批准的对象，不能以“水灾”作宾语。"}, {"text": "挖掘", "is_correct": false, "explanation": "搭配：“挖掘”指从地下或深处取出东西，不与“水灾”搭配。"}], "explanations": {"享受": "语义：“享受”指愉快地接受好的事物，不能用于灾害。", "造成": "正确。“造成”指引起某种结果，与“大雨……水灾”的因果关系相符。", "通过": "配价：“通过”要求可以被经过或批准的对象，不能以“水灾”作宾语。", "挖掘": "搭配：“挖掘”指从地下或深处取出东西，不与“水灾”搭配。"}, "sentence_index": 0, "correct_answer": "造成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事造成了大家的注意。", "explanation": "这里应该用〈引起〉。“造成”指引出不好的结果，引起注意、兴趣要用“引起”。"}, {"text": "工厂每天造成很多汽车。", "explanation": "这里应该用〈制造〉。“造成”指引起结果，制作具体的东西要用“制造”。"}, {"text": "他的观点是在长期思考中造成的。", "explanation": "这里应该用〈形成〉。“造成”指由某种原因引起结果，观点、习惯逐渐形成要用“形成”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe4d3447-d802-4dcc-982d-cc53a9016261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25424, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保持", "is_correct": false, "explanation": "语义：“保持”指维持原样，不能指玩手机造成的身体状况。"}, {"text": "造成", "is_correct": true, "explanation": "正确。“造成”指引起不好的结果，与“长时间玩手机会……眼睛疲劳”的因果关系相符。"}, {"text": "赢得", "is_correct": false, "explanation": "搭配：“赢得”多与“胜利”“尊重”搭配，不能与“疲劳”搭配。"}, {"text": "通过", "is_correct": false, "explanation": "配价：“通过”要求可以被经过的对象，“眼睛疲劳”不能作它的宾语。"}], "explanations": {"保持": "语义：“保持”指维持原样，不能指玩手机造成的身体状况。", "造成": "正确。“造成”指引起不好的结果，与“长时间玩手机会……眼睛疲劳”的因果关系相符。", "赢得": "搭配：“赢得”多与“胜利”“尊重”搭配，不能与“疲劳”搭配。", "通过": "配价：“通过”要求可以被经过的对象，“眼睛疲劳”不能作它的宾语。"}, "sentence_index": 6, "correct_answer": "造成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次聚会造成了大家的开心。", "explanation": "这里应该用〈带来〉。“造成”指引出不好的结果，“开心”这类好的感受要用“带来”。"}, {"text": "他的努力造成了这次成功。", "explanation": "这里应该用〈带来〉。“造成”指引出不好的结果，“成功”是好的结果，要用“带来”。"}, {"text": "这部电影造成了很多人的感动。", "explanation": "这里应该用〈引起〉。“造成”指引出不好的结果，“感动”这类正面感受要用“引起”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe4d3447-d802-4dcc-982d-cc53a9016261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25424, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场大雨曾经造成着很多地方的水灾。", "corrected_sentence": "这场大雨曾经造成过很多地方的水灾。", "error_description": "体标错误：“造成”表示一次性产生结果，不能用“着”，应用“过”。写成“造成着”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe4d3447-d802-4dcc-982d-cc53a9016261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25424, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次堵车是暴雨造成了的。", "corrected_sentence": "这次堵车是暴雨造成的。", "error_description": "体标错误：“是……的”结构中只用“造成的”，不能再加“了”。写成“造成了的”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe4d3447-d802-4dcc-982d-cc53a9016261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
