INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25428, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可以自己烂掉，不会一直留在环境中。", "primary_collocate": null, "pronunciation": "kě jiàng jiě", "ipa": "kʰɤ˨˩˦ tɕjɑŋ˥˩ tɕjɛ˨˩˦", "syllable_count": 3, "sentences": [{"text": "这个袋子是可降解的，用完不会污染环境。", "target_word": "可降解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市开始卖可降解塑料袋。", "target_word": "可降解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "可降解的饭盒埋在土里会慢慢烂掉。", "target_word": "可降解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家咖啡店用可降解的杯子。", "target_word": "可降解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "可降解材料对环境更好。", "target_word": "可降解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了可降解垃圾袋。", "target_word": "可降解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种瓶子不是可降解的，会留在土里很多年。", "target_word": "可降解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司正在研究更便宜的可降解包装。", "target_word": "可降解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请选择可降解的餐具，保护环境。", "target_word": "可降解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "可降解的东西在自然中会慢慢消失。", "target_word": "可降解", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "能被自然分解、不长期留在环境中的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec4c1b08-8b6c-49e8-8306-b34cf5a1cd34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25428, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可降解", "is_correct": true, "explanation": "“可降解”指能自然分解，与“用完不会污染环境”一致，符合句意。"}, {"text": "防水", "is_correct": false, "explanation": "语义：防水和“用完不会污染环境”无关，句子意思不通。"}, {"text": "透明", "is_correct": false, "explanation": "搭配：“透明”说的是外观，不能说明袋子能否降解，与句中的说明不相配。"}, {"text": "塑料", "is_correct": false, "explanation": "语义：塑料袋是污染环境的主要来源，与“用完不会污染环境”矛盾。"}], "explanations": {"可降解": "“可降解”指能自然分解，与“用完不会污染环境”一致，符合句意。", "防水": "语义：防水和“用完不会污染环境”无关，句子意思不通。", "透明": "搭配：“透明”说的是外观，不能说明袋子能否降解，与句中的说明不相配。", "塑料": "语义：塑料袋是污染环境的主要来源，与“用完不会污染环境”矛盾。"}, "sentence_index": 0, "correct_answer": "可降解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个玻璃瓶是可降解的，扔进回收箱就行。", "explanation": "这里应该用〈可回收〉。扔进回收箱说明能再利用，玻璃瓶要说“可回收”；“可降解”指能被自然分解，玻璃并不能分解。"}, {"text": "太阳能是可降解的能源，可以一直用下去。", "explanation": "这里应该用〈可再生〉。太阳能能不断补充，要说“可再生”；“可降解”只用于能被自然分解的物品。"}, {"text": "这台冰箱是可降解的，坏了还能修好。", "explanation": "这里应该用〈可修复〉。坏了还能修好要说“可修复”，“可降解”不能说明冰箱能否修好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25428, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可降解", "is_correct": true, "explanation": "这里要用“可降解”，指瓶子能被自然分解，与“不是……的”形成对比，符合句意。"}, {"text": "轻便", "is_correct": false, "explanation": "搭配：“轻便”说的是重量，与瓶子能否分解无关，不这样搭配。"}, {"text": "圆形", "is_correct": false, "explanation": "语义：圆形是形状，和“会留在土里很多年”没有关系。"}, {"text": "可爱", "is_correct": false, "explanation": "语义：“可爱”是外观评价，不能说明瓶子能否分解。"}], "explanations": {"可降解": "这里要用“可降解”，指瓶子能被自然分解，与“不是……的”形成对比，符合句意。", "轻便": "搭配：“轻便”说的是重量，与瓶子能否分解无关，不这样搭配。", "圆形": "语义：圆形是形状，和“会留在土里很多年”没有关系。", "可爱": "语义：“可爱”是外观评价，不能说明瓶子能否分解。"}, "sentence_index": 6, "correct_answer": "可降解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把铁锤是可降解的，用了很多年也不坏。", "explanation": "这里应该用〈耐用〉。说东西经久不坏要用“耐用”；“可降解”指能被自然分解，铁锤不会分解。"}, {"text": "这种锅可降解，可以放进烤箱。", "explanation": "这里应该用〈耐高温〉。能放进烤箱说明耐高温，“可降解”只说明能被自然分解。"}, {"text": "鞋底可降解，走雨地不滑倒。", "explanation": "这里应该用〈防滑〉。走雨地不滑倒要说“防滑”，“可降解”不能说明防滑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25428, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种餐具很可降解，用完可以埋进土里。", "corrected_sentence": "这种餐具可降解，用完可以埋进土里。", "error_description": "副词错误：“可降解”表示能否被自然分解，前面不能加“很”，应直接说“这种餐具可降解”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25428, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种袋子是可降解地，埋在土里能慢慢烂掉。", "corrected_sentence": "这种袋子是可降解的，埋在土里能慢慢烂掉。", "error_description": "结构助词错误：“是……的”结构中，形容词后应用“的”，不用“地”；“地”修饰动词，不修饰这里的形容词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
