INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25432, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西不见了。", "primary_collocate": null, "pronunciation": "diū", "ipa": "tiou̯˥", "syllable_count": 1, "sentences": [{"text": "我的书包丢了，里面有作业。", "target_word": "丢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的钥匙丢了，进不了家。", "target_word": "丢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你找到我丢的那只手套了吗？", "target_word": "丢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，出门要小心，别丢东西。", "target_word": "丢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在地铁上丢了一把伞。", "target_word": "丢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她哭着说小狗丢了。", "target_word": "丢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是我丢的，谢谢你送回来。", "target_word": "丢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把票丢了，只好再买一张。", "target_word": "丢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我丢了钱包，很着急。", "target_word": "丢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只旧手表不知什么时候丢了。", "target_word": "丢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "丢了", "label": "体标"}, {"form": "丢过", "label": "体标"}, {"form": "丟", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西遗失、找不到了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c937a50d-2199-49ee-9ea8-5faf8f53680f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25432, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "丢", "is_correct": true, "explanation": "正确：丢（diū）表示东西不见了。"}, {"text": "秋", "is_correct": false, "explanation": "qiū（第一声）与 diū 声母不同（q／d），意思是秋天。"}, {"text": "溜", "is_correct": false, "explanation": "liū 与 diū 同为第一声，仅声母不同（l／d），意思是溜走，不是丢失。"}, {"text": "修", "is_correct": false, "explanation": "xiū 与 diū 同为第一声，仅声母不同（x／d），意思是修理，不是丢失。"}], "explanations": {"丢": "正确：丢（diū）表示东西不见了。", "秋": "qiū（第一声）与 diū 声母不同（q／d），意思是秋天。", "溜": "liū 与 diū 同为第一声，仅声母不同（l／d），意思是溜走，不是丢失。", "修": "xiū 与 diū 同为第一声，仅声母不同（x／d），意思是修理，不是丢失。"}, "sentence_index": null, "correct_answer": "丢"}, "level_3": {"options": [{"text": "丢", "is_correct": true, "explanation": "正确：“我的书包丢了”表示书包找不到了，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：书包不会“吃”，“我的书包吃了”句意不通。"}, {"text": "跳", "is_correct": false, "explanation": "语义：书包不会“跳”，“我的书包跳了”句意不通。"}, {"text": "病", "is_correct": false, "explanation": "搭配：“病”不与“书包”搭配，书包不能“病”。"}], "explanations": {"丢": "正确：“我的书包丢了”表示书包找不到了，符合句意。", "吃": "语义：书包不会“吃”，“我的书包吃了”句意不通。", "跳": "语义：书包不会“跳”，“我的书包跳了”句意不通。", "病": "搭配：“病”不与“书包”搭配，书包不能“病”。"}, "sentence_index": 0, "correct_answer": "丢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "午后，风慢慢丢了。", "explanation": "这里应该用〈停〉。“丢”表示东西不见了，风是慢慢停下来，不说“风丢了”。"}, {"text": "篝火渐渐丢了。", "explanation": "这里应该用〈熄灭〉。“丢”表示东西不见了，篝火是慢慢熄灭，不说“篝火丢了”。"}, {"text": "烟雾慢慢丢了。", "explanation": "这里应该用〈散〉。“丢”表示东西不见了，烟雾是慢慢散去，不说“烟雾丢了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25432, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "丢", "is_correct": true, "explanation": "正确：丢（diū）表示东西不见了。"}, {"text": "休", "is_correct": false, "explanation": "xiū 与 diū 同为第一声，仅声母不同（x／d），意思是休息，不是丢失。"}, {"text": "兜", "is_correct": false, "explanation": "dōu 与 diū 同为第一声，仅韵母少一个介音 i（ou／iou），意思是口袋，不是丢失。"}, {"text": "秋", "is_correct": false, "explanation": "qiū 与 diū 同为第一声，仅声母不同（q／d），意思是秋天。"}], "explanations": {"丢": "正确：丢（diū）表示东西不见了。", "休": "xiū 与 diū 同为第一声，仅声母不同（x／d），意思是休息，不是丢失。", "兜": "dōu 与 diū 同为第一声，仅韵母少一个介音 i（ou／iou），意思是口袋，不是丢失。", "秋": "qiū 与 diū 同为第一声，仅声母不同（q／d），意思是秋天。"}, "sentence_index": null, "correct_answer": "丢"}, "level_3": {"options": [{"text": "丢", "is_correct": true, "explanation": "正确：“这本书是我丢的”表示书是我遗失的，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”不能用来指书，“这本书是我唱的”句意不通。"}, {"text": "笑", "is_correct": false, "explanation": "语义：“笑”不能作用于书，“这本书是我笑的”句意不通。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“书”作宾语，“我睡的书”不成立。"}], "explanations": {"丢": "正确：“这本书是我丢的”表示书是我遗失的，符合句意。", "唱": "语义：“唱”不能用来指书，“这本书是我唱的”句意不通。", "笑": "语义：“笑”不能作用于书，“这本书是我笑的”句意不通。", "睡": "配价：“睡”是不及物动词，不能带“书”作宾语，“我睡的书”不成立。"}, "sentence_index": 6, "correct_answer": "丢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她哭了很久，一直在丢眼泪。", "explanation": "这里应该用〈掉〉。“掉眼泪”是固定说法，“丢”不与“眼泪”搭配。"}, {"text": "树叶一片片地丢下来。", "explanation": "这里应该用〈掉〉。“掉下来”指脱落，“丢下来”不表示树叶落下。"}, {"text": "这件毛衣洗了几次，颜色就丢了。", "explanation": "这里应该用〈掉〉。“掉色”指颜色脱落，“颜色丢了”不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25432, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的伞丢了了，很着急。", "corrected_sentence": "我的伞丢了，很着急。", "error_description": "了重复：“丢了”只用一个“了”，应说“我的伞丢了，很着急”，不说“丢了了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25432, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的票了丢，只好再买。", "corrected_sentence": "他的票丢了，只好再买。", "error_description": "了位置错误：“了”应放在动词后，“票了丢”顺序错误，应说“他的票丢了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25434, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
