INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25434, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "脸上用来看东西的器官。", "primary_collocate": null, "pronunciation": "yǎn jing", "ipa": "jɛn˨˩ tɕiŋ", "syllable_count": 2, "sentences": [{"text": "眼睛是用来看东西的。", "target_word": "眼睛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝睁大了眼睛，好奇地看着四周。", "target_word": "眼睛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用眼睛看，用耳朵听。", "target_word": "眼睛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹的眼睛圆圆的，真可爱。", "target_word": "眼睛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉的时候，我们要闭上眼睛。", "target_word": "眼睛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鱼的眼睛在头的两边。", "target_word": "眼睛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "眼睛看不清，就要去看医生。", "target_word": "眼睛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他眨了眨眼睛，笑了。", "target_word": "眼睛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有两只眼睛，一个鼻子。", "target_word": "眼睛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哭了以后，她的眼睛红红的。", "target_word": "眼睛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一双眼睛", "label": "量词"}, {"form": "一只眼睛", "label": "量词"}, {"form": "大眼睛", "label": "复合"}], "register": "中性", "sense_fingerprint": "脸上用来看东西的器官", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c937a50d-2199-49ee-9ea8-5faf8f53680f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25434, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "眼睛", "is_correct": true, "explanation": "正确：眼睛（yǎn jing）指脸上用来看东西的器官。"}, {"text": "眼镜", "is_correct": false, "explanation": "“镜”是 jìng（第四声），与“眼睛”的轻声 jing 声调不同，意思是眼镜。"}, {"text": "演讲", "is_correct": false, "explanation": "第二音节 jiǎng（第三声）与 jing 的韵母不同（iang／ing），意思是演讲。"}, {"text": "严禁", "is_correct": false, "explanation": "yán（第二声）与 yǎn（第三声）声调不同，jìn 与 jing 韵尾不同（n／ng），意思是严格禁止。"}], "explanations": {"眼睛": "正确：眼睛（yǎn jing）指脸上用来看东西的器官。", "眼镜": "“镜”是 jìng（第四声），与“眼睛”的轻声 jing 声调不同，意思是眼镜。", "演讲": "第二音节 jiǎng（第三声）与 jing 的韵母不同（iang／ing），意思是演讲。", "严禁": "yán（第二声）与 yǎn（第三声）声调不同，jìn 与 jing 韵尾不同（n／ng），意思是严格禁止。"}, "sentence_index": null, "correct_answer": "眼睛"}, "level_3": {"options": [{"text": "眼睛", "is_correct": true, "explanation": "正确：“眼睛是用来看东西的”说的是视觉器官，符合句意。"}, {"text": "耳朵", "is_correct": false, "explanation": "语义：耳朵是用来听的，不能用来看东西，与句意相反。"}, {"text": "鼻子", "is_correct": false, "explanation": "搭配：“用来看东西”不与“鼻子”搭配，鼻子是用来闻的。"}, {"text": "嘴巴", "is_correct": false, "explanation": "语义：嘴巴是用来吃饭、说话的，不用来看东西。"}], "explanations": {"眼睛": "正确：“眼睛是用来看东西的”说的是视觉器官，符合句意。", "耳朵": "语义：耳朵是用来听的，不能用来看东西，与句意相反。", "鼻子": "搭配：“用来看东西”不与“鼻子”搭配，鼻子是用来闻的。", "嘴巴": "语义：嘴巴是用来吃饭、说话的，不用来看东西。"}, "sentence_index": 0, "correct_answer": "眼睛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的一条眼睛很亮。", "explanation": "这里应该用〈只〉。“条”用于细长的东西，眼睛不用“条”。"}, {"text": "妹妹有一把眼睛。", "explanation": "这里应该用〈双〉或〈只〉。“把”用于有柄的东西，眼睛不用“把”。"}, {"text": "小鸟有一本明亮的眼睛。", "explanation": "这里应该用〈只〉或〈双〉。“本”用于书籍，眼睛不用“本”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25434, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "眼睛", "is_correct": true, "explanation": "正确：眼睛（yǎn jing）指脸上用来看东西的器官。"}, {"text": "演进", "is_correct": false, "explanation": "jìn 与 jing 韵尾不同（n／ng），且声调不同，意思是逐步发展、演变。"}, {"text": "眼镜", "is_correct": false, "explanation": "“镜”是 jìng（第四声），与“眼睛”的轻声 jing 只差声调，意思是眼镜。"}, {"text": "眼睑", "is_correct": false, "explanation": "jiǎn 与 jing 韵尾不同（n／ng），声调也不同，意思是眼皮。"}], "explanations": {"眼睛": "正确：眼睛（yǎn jing）指脸上用来看东西的器官。", "演进": "jìn 与 jing 韵尾不同（n／ng），且声调不同，意思是逐步发展、演变。", "眼镜": "“镜”是 jìng（第四声），与“眼睛”的轻声 jing 只差声调，意思是眼镜。", "眼睑": "jiǎn 与 jing 韵尾不同（n／ng），声调也不同，意思是眼皮。"}, "sentence_index": null, "correct_answer": "眼睛"}, "level_3": {"options": [{"text": "眼睛", "is_correct": true, "explanation": "正确：“眼睛看不清，就要去看医生”指视力不好，眼睛是看的器官。"}, {"text": "手指", "is_correct": false, "explanation": "语义：手指不是看东西的器官，“手指看不清”与句意不符。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“看不清”不与“脚步”搭配，不能说“脚步看不清”。"}, {"text": "膝盖", "is_correct": false, "explanation": "语义：膝盖不是视觉器官，“膝盖看不清”与句意不符。"}], "explanations": {"眼睛": "正确：“眼睛看不清，就要去看医生”指视力不好，眼睛是看的器官。", "手指": "语义：手指不是看东西的器官，“手指看不清”与句意不符。", "脚步": "搭配：“看不清”不与“脚步”搭配，不能说“脚步看不清”。", "膝盖": "语义：膝盖不是视觉器官，“膝盖看不清”与句意不符。"}, "sentence_index": 6, "correct_answer": "眼睛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶看书时，总把眼睛架在鼻子上。", "explanation": "这里应该用〈眼镜〉。“架”是用于眼镜的动作，“眼睛”是器官，不能架在鼻子上。"}, {"text": "锻炼了一段时间，他的眼睛提高了不少。", "explanation": "这里应该用〈视力〉。“提高”用于水平、能力，“眼睛”是器官，不说“眼睛提高”。"}, {"text": "她长期看电视，眼睛下降得很厉害。", "explanation": "这里应该用〈视力〉。“下降”用于视力、数量，说“眼睛下降”不自然，应说“视力下降”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25434, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她有两眼睛。", "corrected_sentence": "她有两只眼睛。", "error_description": "量词缺失：“眼睛”计数时要加“只”或“双”，不能直接说“两眼睛”，应说“两只眼睛”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25434, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们的眼睛们很亮。", "corrected_sentence": "孩子们的眼睛很亮。", "error_description": "复数错误：“眼睛”后不能加“们”。“孩子们”的“们”只用于指人，应说“孩子们的眼睛很亮”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
