INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25448, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "警察晚上去街上工作。", "primary_collocate": null, "pronunciation": "chū gēng", "ipa": "t͡ʂʰu˥ kɤŋ˥", "syllable_count": 2, "sentences": [{"text": "香港警察今晚要出更。", "target_word": "出更", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他爸爸是警察，常常晚上出更。", "target_word": "出更", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天夜里，小李出更了。", "target_word": "出更", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察出更的时候，街上很安静。", "target_word": "出更", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天晚上谁出更？", "target_word": "出更", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们两个警察一起出更，在街上走了很久。", "target_word": "出更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥是警察，每个星期都要出更。", "target_word": "出更", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他出更回来，已经是早上六点了。", "target_word": "出更", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨下得很大，警察还是要出更。", "target_word": "出更", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下个月他换了班，不用晚上出更了。", "target_word": "出更", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出更了", "label": "体标"}], "register": "口语", "sense_fingerprint": "警察夜间外出执勤", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82fc455b-0366-4ce7-88da-88494763821a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25448, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出更", "is_correct": true, "explanation": "正确答案。“今晚要出更”指今晚外出执勤，符合警察的工作。"}, {"text": "上学", "is_correct": false, "explanation": "语义：警察是职业，“警察今晚要上学”与人物身份不合，句意不通。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”指人刚降生，不能用于“今晚要……”这样的安排。"}, {"text": "出版", "is_correct": false, "explanation": "配价：“出版”的对象应是书报等出版物，不能说“警察今晚要出版”。"}], "explanations": {"出更": "正确答案。“今晚要出更”指今晚外出执勤，符合警察的工作。", "上学": "语义：警察是职业，“警察今晚要上学”与人物身份不合，句意不通。", "出生": "语义：“出生”指人刚降生，不能用于“今晚要……”这样的安排。", "出版": "配价：“出版”的对象应是书报等出版物，不能说“警察今晚要出版”。"}, "sentence_index": 0, "correct_answer": "出更"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这周在警局出更，负责接电话。", "explanation": "这里应该用〈值班〉。出更指夜里外出值勤，不在室内接电话；在室内值班才说“值班”。"}, {"text": "他下周要出更去北京开会。", "explanation": "这里应该用〈出差〉。出更指夜间外出执勤，不能用于出远门开会。"}, {"text": "他在家里出更，负责守门。", "explanation": "这里应该用〈守门〉。出更指外出值勤，在家里守门不能说出更。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba62c99f-b3cf-4f52-97be-4f8fbbc49ada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25448, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出更", "is_correct": true, "explanation": "正确答案。“每个星期都要出更”说的是有规律的值勤，符合警察的工作。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”不是可以安排的事，不能说“每个星期都要生病”。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”通常只发生一次，不能说每个星期进行。"}, {"text": "降雨", "is_correct": false, "explanation": "配价：“降雨”的主语应是天气，不能用于“我哥哥”。"}], "explanations": {"出更": "正确答案。“每个星期都要出更”说的是有规律的值勤，符合警察的工作。", "生病": "语义：“生病”不是可以安排的事，不能说“每个星期都要生病”。", "结婚": "语义：“结婚”通常只发生一次，不能说每个星期进行。", "降雨": "配价：“降雨”的主语应是天气，不能用于“我哥哥”。"}, "sentence_index": 6, "correct_answer": "出更"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上出更，九点才回家。", "explanation": "这里应该用〈上班〉。出更是夜里外出执勤，早上在单位工作应说“上班”，不说出更。"}, {"text": "为了写报告，他出更写到凌晨三点。", "explanation": "这里应该用〈熬夜〉。出更是因执勤而夜间外出，不用于写报告熬夜的情形。"}, {"text": "奶奶在床边出更，怕孩子醒来哭。", "explanation": "这里应该用〈守夜〉。守夜指在床边或家中守候，出更指外出值勤，不能用于床边守候。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba62c99f-b3cf-4f52-97be-4f8fbbc49ada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25448, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨晚很出更，一直走到天亮。", "corrected_sentence": "我昨晚出更，一直走到天亮。", "error_description": "错误：“很出更”，正确：“出更”。“很”是程度副词，只能修饰形容词或状态性词语，不能修饰“出更”这样的动作动词，应删去“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba62c99f-b3cf-4f52-97be-4f8fbbc49ada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25448, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨晚在街上太出更，一直走到天亮。", "corrected_sentence": "他昨晚在街上出更，一直走到天亮。", "error_description": "错误：“太出更”，正确：“出更”。“太”是程度副词，只能修饰形容词或状态性词语，不能修饰“出更”这样的动作动词，应删去“太”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba62c99f-b3cf-4f52-97be-4f8fbbc49ada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
