INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25450, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种黄色的、可以煮着吃的粮食，一粒一粒的。", "primary_collocate": null, "pronunciation": "yù mǐ", "ipa": "y⁵¹ mi²¹⁴", "syllable_count": 2, "sentences": [{"text": "我早饭吃了一根热玉米。", "target_word": "玉米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个玉米是黄色的，一粒一粒很整齐。", "target_word": "玉米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子手里拿着一个煮好的玉米。", "target_word": "玉米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边有人在卖烤玉米。", "target_word": "玉米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不爱吃米饭，只爱啃玉米。", "target_word": "玉米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玉米煮二十分钟就可以吃了。", "target_word": "玉米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶从菜市场买回了两根玉米。", "target_word": "玉米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个玉米很甜，孩子们都爱吃。", "target_word": "玉米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里，小女孩正在吃玉米。", "target_word": "玉米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把玉米放进锅里煮。", "target_word": "玉米", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "根", "label": "量词"}, {"form": "玉米面", "label": "复合"}, {"form": "玉米粒", "label": "复合"}], "register": "中性", "sense_fingerprint": "黄色、一粒一粒、可以煮着吃的粮食", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc9b4b69-ef94-4dfb-a579-4a5298524f1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25450, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "玉米", "is_correct": true, "explanation": "正确：“一根”计量细长的玉米棒，“热”与“吃”都与食用相合。"}, {"text": "米饭", "is_correct": false, "explanation": "搭配：“根”用于细长条状的东西，米饭应该用“碗”或“份”计量。"}, {"text": "汤", "is_correct": false, "explanation": "搭配：汤是液体，不能用“根”计量，应说“一碗汤”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能吃，与句中“吃了”的动作相冲突。"}], "explanations": {"玉米": "正确：“一根”计量细长的玉米棒，“热”与“吃”都与食用相合。", "米饭": "搭配：“根”用于细长条状的东西，米饭应该用“碗”或“份”计量。", "汤": "搭配：汤是液体，不能用“根”计量，应说“一碗汤”。", "石头": "语义：石头不能吃，与句中“吃了”的动作相冲突。"}, "sentence_index": 0, "correct_answer": "玉米"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们用玉米给手机充电。", "explanation": "这里应该用〈充电宝〉。玉米是可以煮着吃的粮食，不能用来给手机充电；充电要用充电宝或充电器。"}, {"text": "我们用玉米拧开了瓶盖。", "explanation": "这里应该用〈开瓶器〉。玉米是可以煮着吃的食物，不能当作开瓶的工具。"}, {"text": "妈妈用玉米做了一件外套。", "explanation": "这里应该用〈布料〉。玉米是食物，不能作衣服的材料；做衣服要用布料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25450, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "玉米", "is_correct": true, "explanation": "正确：菜市场买的是蔬菜粮食，“根”计量的正是玉米棒。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：菜市场不卖钢笔，与句中的购买场所相冲突。"}, {"text": "猪肉", "is_correct": false, "explanation": "搭配：“根”用于细长条状的东西，猪肉应说“块”或“斤”。"}, {"text": "书", "is_correct": false, "explanation": "语义：菜市场不卖书，与句中的购买场所相冲突。"}], "explanations": {"玉米": "正确：菜市场买的是蔬菜粮食，“根”计量的正是玉米棒。", "钢笔": "语义：菜市场不卖钢笔，与句中的购买场所相冲突。", "猪肉": "搭配：“根”用于细长条状的东西，猪肉应说“块”或“斤”。", "书": "语义：菜市场不卖书，与句中的购买场所相冲突。"}, "sentence_index": 6, "correct_answer": "玉米"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们骑着玉米去郊游。", "explanation": "这里应该用〈自行车〉。玉米不是交通工具，骑车要用自行车。"}, {"text": "他每天看玉米就知道几点了。", "explanation": "这里应该用〈钟表〉。玉米不能用来计时，看时间要用钟表。"}, {"text": "他每天用玉米写作业。", "explanation": "这里应该用〈铅笔〉。玉米是可以煮着吃的粮食，不能用来写字；写作业要用铅笔或笔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25450, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "玉米煮了好，就能吃了。", "corrected_sentence": "玉米煮好了，就能吃了。", "error_description": "错误形式：“煮了好”；正确形式：“煮好了”。结果补语“好”要紧跟动词，“了”放在补语之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25450, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我过吃煮玉米。", "corrected_sentence": "我吃过煮玉米。", "error_description": "错误形式：“过吃煮玉米”；正确形式：“吃过煮玉米”。“过”表示曾经的经历，要紧跟动词“吃”，放在动词之前是错误语序。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
