INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25454, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "海洋是很大很大的水。", "primary_collocate": null, "pronunciation": "hǎi yáng", "ipa": "xaɪ˨˩˦ jɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "地球表面大部分是海洋。", "target_word": "海洋", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这条河最后会流进海洋。", "target_word": "海洋", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "鲸是生活在海洋里的大动物。", "target_word": "海洋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂的脏水流进海洋，鱼会生病。", "target_word": "海洋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家坐船去研究海洋。", "target_word": "海洋", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "海洋的颜色会随着天气变化。", "target_word": "海洋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳照着海洋，水面亮亮的。", "target_word": "海洋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想学潜水，看看海洋下面的世界。", "target_word": "海洋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "陆地上有山和河，海洋里有很多鱼。", "target_word": "海洋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在海洋里的塑料垃圾越来越多。", "target_word": "海洋", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "海洋生物", "label": "复合"}], "register": "中性", "sense_fingerprint": "地球上连成一片的广大咸水水域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e373b1f0-8529-4f99-bdb4-29789ab94d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25454, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海洋", "is_correct": true, "explanation": "正确。“地球表面大部分是海洋”符合事实，地球表面约七成被海洋覆盖。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠只是陆地的一部分，地球表面大部分不是沙漠。"}, {"text": "城市", "is_correct": false, "explanation": "语义：城市只占地表很小的面积，不能说地球表面大部分是城市。"}, {"text": "地面", "is_correct": false, "explanation": "语义：地面指陆地表面，地球表面大部分其实是海洋，说“大部分是地面”与事实不符。"}], "explanations": {"海洋": "正确。“地球表面大部分是海洋”符合事实，地球表面约七成被海洋覆盖。", "沙漠": "语义：沙漠只是陆地的一部分，地球表面大部分不是沙漠。", "城市": "语义：城市只占地表很小的面积，不能说地球表面大部分是城市。", "地面": "语义：地面指陆地表面，地球表面大部分其实是海洋，说“大部分是地面”与事实不符。"}, "sentence_index": 0, "correct_answer": "海洋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我坐船去看了一只海洋。", "explanation": "这里应该用〈片〉。“只”多用于动物，大片水域要说“一片海洋”。"}, {"text": "我不能喝海洋，它太咸了。", "explanation": "这里应该用〈海水〉。“海洋”指整片大水域，不能说“喝海洋”；说喝的、咸的水要用“海水”。"}, {"text": "他在那么大的城市里找人，真是海洋捞针。", "explanation": "这里应该用〈大海〉。“大海捞针”是固定说法，比喻很难找到，不能把“大海”换成“海洋”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25454, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海洋", "is_correct": true, "explanation": "正确。“太阳照着海洋，水面亮亮的”，海洋的水面在阳光下发亮。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是平整的固体，上面不会有水面，句子无法成立。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠里没有大片的水，“水面亮亮的”不能用来描写沙漠。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：书桌上没有大片水面，“水面亮亮的”无法用来描写书桌。"}], "explanations": {"海洋": "正确。“太阳照着海洋，水面亮亮的”，海洋的水面在阳光下发亮。", "黑板": "语义：黑板是平整的固体，上面不会有水面，句子无法成立。", "沙漠": "语义：沙漠里没有大片的水，“水面亮亮的”不能用来描写沙漠。", "书桌": "语义：书桌上没有大片水面，“水面亮亮的”无法用来描写书桌。"}, "sentence_index": 6, "correct_answer": "海洋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在山顶看到了一座海洋。", "explanation": "这里应该用〈片〉。“座”多用于山、房屋等，大片水域要说“一片海洋”。"}, {"text": "傍晚的海洋吹在脸上，很凉快。", "explanation": "这里应该用〈海风〉。“吹”的是风，海洋本身吹不了风；从海上吹来的风要说“海风”。"}, {"text": "我们在饭店点了一盘海洋。", "explanation": "这里应该用〈海鲜〉。“一盘”后面通常是菜，“海洋”不能当作菜点，应该说“一盘海鲜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25454, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地球上有一片很大地海洋。", "corrected_sentence": "地球上有一片很大的海洋。", "error_description": "结构助词：修饰名词“海洋”要用“的”，“地”用于修饰动词，应说“很大的海洋”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25454, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鱼生活海洋里。", "corrected_sentence": "鱼生活在海洋里。", "error_description": "介词缺失。“生活在……里”中的“在”不能省，应说“鱼生活在海洋里”，不能说“鱼生活海洋里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
