INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25462, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "自然环境就是人们生活的地方，有山、有水、有树和动物。", "primary_collocate": null, "pronunciation": "zì rán huán jìng", "ipa": "tsɨ ʐan xwan tɕiŋ", "syllable_count": 4, "sentences": [{"text": "这里的自然环境真美，有山有水。", "target_word": "自然环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我喜欢住在自然环境好的地方。", "target_word": "自然环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们村的自然环境很好，有山有树。", "target_word": "自然环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们去郊外，享受自然环境。", "target_word": "自然环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子在自然环境中长大，身体很好。", "target_word": "自然环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个公园里有水有树，自然环境不错。", "target_word": "自然环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷喜欢安静的自然环境。", "target_word": "自然环境", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "住在山里，自然环境让人很放松。", "target_word": "自然环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那儿的自然环境很美，我拍了很多照片。", "target_word": "自然环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟和小鹿在自然环境里自由生活。", "target_word": "自然环境", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自然環境", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人们生活的地方，有山水树木和动物的自然景象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3728d7ac-a5c9-42ec-9c46-36da5936aa49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25462, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自然环境", "is_correct": true, "explanation": "正确。“自然环境”指有山有水的地方，符合“真美，有山有水”的描述。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间里不会“有山有水”，与句意不符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不会“有山有水”，句子说的是户外的景象。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“课本”不能用“真美”形容山水景色，“有山有水”也与课本无关。"}], "explanations": {"自然环境": "正确。“自然环境”指有山有水的地方，符合“真美，有山有水”的描述。", "房间": "语义：房间里不会“有山有水”，与句意不符。", "厨房": "语义：厨房不会“有山有水”，句子说的是户外的景象。", "课本": "搭配：“课本”不能用“真美”形容山水景色，“有山有水”也与课本无关。"}, "sentence_index": 0, "correct_answer": "自然环境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班的自然环境很好，同学们都很友好。", "explanation": "这里应该用〈班级氛围〉。“自然环境”指山水树木等自然条件，不指人和人的关系。"}, {"text": "这台电脑的自然环境坏了，打不开。", "explanation": "这里应该用〈系统〉。“自然环境”指自然界的山水草木，不指电脑。"}, {"text": "他们家的自然环境很温暖，大家都很爱对方。", "explanation": "这里应该用〈家庭氛围〉。“自然环境”指自然条件，不指家人之间的感情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1071fff-adda-4667-bf15-73a50625d246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25462, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自然环境", "is_correct": true, "explanation": "正确。“安静的自然环境”指宁静的山水环境，符合“爷爷喜欢”的语境。"}, {"text": "集市", "is_correct": false, "explanation": "语义：集市通常热闹，与“安静的”相矛盾。"}, {"text": "夜市", "is_correct": false, "explanation": "语义：夜市是热闹的场所，与“安静”相矛盾。"}, {"text": "菜市场", "is_correct": false, "explanation": "搭配：“安静的”一般不修饰菜市场这类热闹场所，搭配不当。"}], "explanations": {"自然环境": "正确。“安静的自然环境”指宁静的山水环境，符合“爷爷喜欢”的语境。", "集市": "语义：集市通常热闹，与“安静的”相矛盾。", "夜市": "语义：夜市是热闹的场所，与“安静”相矛盾。", "菜市场": "搭配：“安静的”一般不修饰菜市场这类热闹场所，搭配不当。"}, "sentence_index": 6, "correct_answer": "自然环境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间教室的自然环境很安静。", "explanation": "这里应该用〈学习环境〉。“自然环境”指自然界的山水草木，不指教室的学习条件。"}, {"text": "这家医院的自然环境很先进，医生的技术也很好。", "explanation": "这里应该用〈医疗环境〉。“自然环境”指山水、树木和动物等自然条件，不指医院的设备和技术。"}, {"text": "这家电视台的自然环境很严格，领导对员工要求很高。", "explanation": "这里应该用〈工作环境〉。“自然环境”指山水草木等自然条件，不指单位的管理和工作条件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1071fff-adda-4667-bf15-73a50625d246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25462, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山里的自然环境们很好。", "corrected_sentence": "山里的自然环境很好。", "error_description": "词缀错误：“自然环境”后不能加“们”，“们”只用于人。正确形式是“自然环境”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1071fff-adda-4667-bf15-73a50625d246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25462, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那里有一条美丽的自然环境。", "corrected_sentence": "那里有美丽的自然环境。", "error_description": "量词错误：“自然环境”是抽象的整体，不能用“一条”来数，应去掉“一条”，说“美丽的自然环境”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1071fff-adda-4667-bf15-73a50625d246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25464, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25464, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25464, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可以控制的。", "primary_collocate": null, "pronunciation": "kě kòng", "ipa": "kʰɤ˨˩˦ kʰʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "房间里的灯光亮度是可控的。", "target_word": "可控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "情绪可控的人，做事更冷静。", "target_word": "可控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机器人的动作完全可控。", "target_word": "可控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得自己的压力还可控。", "target_word": "可控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河的水位现在是可控的。", "target_word": "可控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的开支很可控，不会花太多。", "target_word": "可控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种火是可控的，不会烧到别处。", "target_word": "可控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气我们管不了，但自己的计划可控。", "target_word": "可控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说这个项目的风险可控。", "target_word": "可控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的体重一直可控，没有变胖。", "target_word": "可控", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "可控性", "label": "复合"}, {"form": "不可控", "label": "复合"}], "register": "书面", "sense_fingerprint": "人可以控制的，不会失去掌握", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e9585d0-18df-4185-ab2e-1482e7a5a6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25464, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可控", "is_correct": true, "explanation": "“可控”指灯光亮度能被人调节，与句意相符。"}, {"text": "甜美", "is_correct": false, "explanation": "语义：“甜美”形容味道或声音，灯光亮度不能说甜美，与句意不符。"}, {"text": "易碎", "is_correct": false, "explanation": "语义：亮度不会碎，“易碎”与句意不符。"}, {"text": "可笑", "is_correct": false, "explanation": "语义：灯光亮度不可笑，这个词与句子的意思无关。"}], "explanations": {"可控": "“可控”指灯光亮度能被人调节，与句意相符。", "甜美": "语义：“甜美”形容味道或声音，灯光亮度不能说甜美，与句意不符。", "易碎": "语义：亮度不会碎，“易碎”与句意不符。", "可笑": "语义：灯光亮度不可笑，这个词与句子的意思无关。"}, "sentence_index": 0, "correct_answer": "可控"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一个非常可控的朋友，有事都会找他。", "explanation": "这里应该用〈可靠〉。“可靠”形容人值得信赖；“可控”指能被控制，不用来说人的可信度。"}, {"text": "这个想法很可控，我们下周就去做。", "explanation": "这里应该用〈可行〉。“可行”指方案能够实施；“可控”说能被控制，不用来评价想法能否实施。"}, {"text": "这家店的菜很可控，我常常去吃。", "explanation": "这里应该用〈好吃〉。“好吃”形容味道好；“可控”指能被控制，不能用来评价饭菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25464, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可控", "is_correct": true, "explanation": "“可控”指火能被控制，与“不会烧到别处”的意思相符。"}, {"text": "易碎", "is_correct": false, "explanation": "语义：火不会“易碎”，与“不会烧到别处”的意思无关。"}, {"text": "易燃", "is_correct": false, "explanation": "语义：“易燃”说明火容易蔓延，与“不会烧到别处”的意思相反。"}, {"text": "可爱", "is_correct": false, "explanation": "语义：火不具有“可爱”的特征，与句意不符。"}], "explanations": {"可控": "“可控”指火能被控制，与“不会烧到别处”的意思相符。", "易碎": "语义：火不会“易碎”，与“不会烧到别处”的意思无关。", "易燃": "语义：“易燃”说明火容易蔓延，与“不会烧到别处”的意思相反。", "可爱": "语义：火不具有“可爱”的特征，与句意不符。"}, "sentence_index": 6, "correct_answer": "可控"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的身体很可控，很少生病。", "explanation": "这里应该用〈健康〉。“健康”形容身体状况好；“可控”说能被控制，不用来形容身体好坏。"}, {"text": "这个问题他解释得很可控。", "explanation": "这里应该用〈清楚〉。“清楚”形容说明得明白；“可控”不表示说明的效果。"}, {"text": "这次比赛的胜负很可控，谁也猜不到结果。", "explanation": "这里应该用〈难料〉。“难料”指难以预料；“可控”说能被控制，与“谁也猜不到”的意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25464, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个机器人的速度被可控。", "corrected_sentence": "这个机器人的速度可控。", "error_description": "“可控”前多加了“被”。“可控”是形容词，表示“能被控制”，本身不是被动动词，不能再用“被”。应改为“这个机器人的速度可控”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25464, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次实验的温度没可控，结果不准。", "corrected_sentence": "这次实验的温度不可控，结果不准。", "error_description": "否定形式错误：修饰形容词“可控”应用“不”，不能用“没”。应改为“不可控”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25466, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "中断", "is_correct": true, "explanation": "正确：“继续”与“中断”相对，“继续”指不中断地接着做，“中断”指停下来。"}, {"text": "漂亮", "is_correct": false, "explanation": "与“继续”没有反义关系，“漂亮”形容外貌或事物好看。"}, {"text": "安静", "is_correct": false, "explanation": "与“继续”没有反义关系，“安静”形容没有声音或不吵闹。"}, {"text": "明亮", "is_correct": false, "explanation": "与“继续”没有反义关系，“明亮”形容光线充足。"}], "correct_answer": "中断", "explanations": {"中断": "正确：“继续”与“中断”相对，“继续”指不中断地接着做，“中断”指停下来。", "漂亮": "与“继续”没有反义关系，“漂亮”形容外貌或事物好看。", "安静": "与“继续”没有反义关系，“安静”形容没有声音或不吵闹。", "明亮": "与“继续”没有反义关系，“明亮”形容光线充足。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25466, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "停止", "is_correct": true, "explanation": "正确：“继续”与“停止”相对，“继续”指接着做下去，“停止”指不再做下去。"}, {"text": "复杂", "is_correct": false, "explanation": "与“继续”没有反义关系，“复杂”形容事情或结构多而难懂。"}, {"text": "好看", "is_correct": false, "explanation": "与“继续”没有反义关系，“好看”形容外表或样子美观。"}, {"text": "可靠", "is_correct": false, "explanation": "与“继续”没有反义关系，“可靠”形容值得信任。"}], "correct_answer": "停止", "explanations": {"停止": "正确：“继续”与“停止”相对，“继续”指接着做下去，“停止”指不再做下去。", "复杂": "与“继续”没有反义关系，“复杂”形容事情或结构多而难懂。", "好看": "与“继续”没有反义关系，“好看”形容外表或样子美观。", "可靠": "与“继续”没有反义关系，“可靠”形容值得信任。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25466, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "继续就是不停下来，一直做。", "primary_collocate": null, "pronunciation": "jì xù", "ipa": "tɕi˥˩ ɕy˥˩", "syllable_count": 2, "sentences": [{"text": "雨停了，比赛继续进行。", "target_word": "继续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "休息一下，然后继续工作。", "target_word": "继续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃完饭，继续看书。", "target_word": "继续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你继续说，我在听。", "target_word": "继续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然很累，她还是继续往前走。", "target_word": "继续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们继续练习写汉字。", "target_word": "继续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别停，继续跑，终点就在前面。", "target_word": "继续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想继续在这个城市生活。", "target_word": "继续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他接完电话，继续做饭。", "target_word": "继续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你继续努力，一定能成功。", "target_word": "继续", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "继续了", "label": "体标"}, {"form": "继续下去", "label": "复合"}], "register": "中性", "sense_fingerprint": "不中断地接着做下去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a7a008-8700-472e-9416-a17e42e54d73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25466, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "继续", "is_correct": true, "explanation": "正确答案：jì xù，意思是不停下来，接着做下去。"}, {"text": "积蓄", "is_correct": false, "explanation": "jī（第一声）与 jì（第四声）声调不同，积蓄指存下的钱。"}, {"text": "次序", "is_correct": false, "explanation": "cì 与 jì 声母不同（c 与 j），次序指先后的顺序。"}, {"text": "技术", "is_correct": false, "explanation": "shù 与 xù 声母不同（sh 与 x），技术指专业的方法或手段。"}], "explanations": {"继续": "正确答案：jì xù，意思是不停下来，接着做下去。", "积蓄": "jī（第一声）与 jì（第四声）声调不同，积蓄指存下的钱。", "次序": "cì 与 jì 声母不同（c 与 j），次序指先后的顺序。", "技术": "shù 与 xù 声母不同（sh 与 x），技术指专业的方法或手段。"}, "sentence_index": null, "correct_answer": "继续"}, "level_3": {"options": [{"text": "继续", "is_correct": true, "explanation": "正确：“雨停了”之后比赛接着进行，“继续”表示接着做下去。"}, {"text": "停止", "is_correct": false, "explanation": "语义：“雨停了”提示比赛应当恢复，“停止”与这一语境矛盾。"}, {"text": "便宜", "is_correct": false, "explanation": "语法：“便宜”是形容词，不能修饰动词“进行”，“比赛便宜进行”不通。"}, {"text": "取消", "is_correct": false, "explanation": "搭配：“取消”要带宾语“比赛”，不能直接接“进行”，应说“取消比赛”。"}], "explanations": {"继续": "正确：“雨停了”之后比赛接着进行，“继续”表示接着做下去。", "停止": "语义：“雨停了”提示比赛应当恢复，“停止”与这一语境矛盾。", "便宜": "语法：“便宜”是形容词，不能修饰动词“进行”，“比赛便宜进行”不通。", "取消": "搭配：“取消”要带宾语“比赛”，不能直接接“进行”，应说“取消比赛”。"}, "sentence_index": 0, "correct_answer": "继续"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "手机摔坏以后，我只好继续买一部。", "explanation": "这里应该用〈重新〉。“继续”要接着原来的动作往下做，手机摔坏后再买一部是新的动作，应说“重新买”。"}, {"text": "电影还没开始，我们就继续看吧。", "explanation": "这里应该用〈开始〉。“继续”要接着原来的动作往下做，电影还没开始，没有可以接着做的动作。"}, {"text": "他刚出院，就继续住进了医院。", "explanation": "这里应该用〈又〉。“住进医院”是一次性的动作，不能用“继续”来接着做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25466, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "继续", "is_correct": true, "explanation": "正确答案：jì xù，意思是不停下来，接着做下去。"}, {"text": "寄宿", "is_correct": false, "explanation": "sù 与 xù 声母不同（s 与 x），寄宿指在别处临时住下。"}, {"text": "秩序", "is_correct": false, "explanation": "zhì 与 jì 声母不同（zh 与 j），秩序指有条理的次序。"}, {"text": "记述", "is_correct": false, "explanation": "shù 与 xù 声母不同（sh 与 x），记述指记下并叙述事情。"}], "explanations": {"继续": "正确答案：jì xù，意思是不停下来，接着做下去。", "寄宿": "sù 与 xù 声母不同（s 与 x），寄宿指在别处临时住下。", "秩序": "zhì 与 jì 声母不同（zh 与 j），秩序指有条理的次序。", "记述": "shù 与 xù 声母不同（sh 与 x），记述指记下并叙述事情。"}, "sentence_index": null, "correct_answer": "继续"}, "level_3": {"options": [{"text": "继续", "is_correct": true, "explanation": "正确：“别停”之后接着跑，“继续”表示不停下来地接着做。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“别停”要求坚持下去，“放弃”与此相反。"}, {"text": "中断", "is_correct": false, "explanation": "语义：“别停”不允许停下，“中断”就是停下，与语境矛盾。"}, {"text": "歇", "is_correct": false, "explanation": "搭配：“歇”指休息，不能直接接“跑”，说“歇跑”不通。"}], "explanations": {"继续": "正确：“别停”之后接着跑，“继续”表示不停下来地接着做。", "放弃": "语义：“别停”要求坚持下去，“放弃”与此相反。", "中断": "语义：“别停”不允许停下，“中断”就是停下，与语境矛盾。", "歇": "搭配：“歇”指休息，不能直接接“跑”，说“歇跑”不通。"}, "sentence_index": 6, "correct_answer": "继续"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他刚坐下，就继续站了起来。", "explanation": "这里应该用〈又〉。“继续”只能接着同一动作往下做，“坐下”后再“站起来”是另一个动作，应说“又站了起来”。"}, {"text": "我把那本书弄丢了，只好继续借一本。", "explanation": "这里应该用〈再〉。书丢了以后另借一本是新的动作，不是接着原来的动作做下去，应说“再借一本”。"}, {"text": "他刚入学，就继续毕业了。", "explanation": "这里不能用“继续”。“继续”要接着原来的动作往下做，刚入学还谈不上接着毕业；“毕业”是一次性的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25466, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他喝完咖啡，继续了工作了。", "corrected_sentence": "他喝完咖啡，继续工作了。", "error_description": "体标误用：同一句中“了”重复出现（“继续了工作了”），句末只保留一个“了”。正确：“继续工作了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25466, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场讨论还要继续下来。", "corrected_sentence": "这场讨论还要继续下去。", "error_description": "错误：表示接着做下去要用趋向补语“下去”，“下来”不对。正确：“继续下去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
