INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25470, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "两个东西很不一样，一眼就能看出来。", "primary_collocate": null, "pronunciation": "xiān míng duì bǐ", "ipa": "ɕjɛn˥ miŋ˧˥ twei˥˩ pi˨˩˦", "syllable_count": 4, "sentences": [{"text": "白雪和黑石头形成鲜明对比。", "target_word": "鲜明对比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥很高，弟弟很矮，这是鲜明对比。", "target_word": "鲜明对比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天很热，冬天很冷，形成鲜明对比。", "target_word": "鲜明对比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红衣服和白墙形成了鲜明对比。", "target_word": "鲜明对比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的房间很乱，我的房间很干净，真是鲜明对比。", "target_word": "鲜明对比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个孩子的性格形成鲜明对比。", "target_word": "鲜明对比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新楼很高，旧房子很矮，两者是鲜明对比。", "target_word": "鲜明对比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白天很吵，晚上很安静，是一个鲜明对比。", "target_word": "鲜明对比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两杯水一冷一热，形成鲜明对比。", "target_word": "鲜明对比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑着说话，她哭着回答，形成了鲜明对比。", "target_word": "鲜明对比", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "两个东西很不一样，一眼就看得出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e9585d0-18df-4185-ab2e-1482e7a5a6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25470, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鲜明对比", "is_correct": true, "explanation": "“鲜明对比”指两个事物差别清楚，正符合白雪与黑石头的反差。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“形成”后接的是关系或结果，不说“形成颜色”。"}, {"text": "共鸣", "is_correct": false, "explanation": "语义：“共鸣”表示同频回应或认同，与白与黑的对照不符。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”是可称量的数值，不能与“形成”搭配。"}], "explanations": {"鲜明对比": "“鲜明对比”指两个事物差别清楚，正符合白雪与黑石头的反差。", "颜色": "搭配：“形成”后接的是关系或结果，不说“形成颜色”。", "共鸣": "语义：“共鸣”表示同频回应或认同，与白与黑的对照不符。", "体重": "搭配：“体重”是可称量的数值，不能与“形成”搭配。"}, "sentence_index": 0, "correct_answer": "鲜明对比"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两件外套的颜色几乎一样，却形成了鲜明对比。", "explanation": "“鲜明对比”强调两者差别明显；颜色几乎一样时没有对比，句子前后矛盾。"}, {"text": "这个花园只有一种颜色，却形成了鲜明对比。", "explanation": "“鲜明对比”需要两个或更多事物互相衬托；只有一种颜色时不能形成鲜明对比。"}, {"text": "这两个数字只差了一点，却被说成鲜明对比。", "explanation": "“鲜明对比”强调差别明显；只差一点的差别很细微，不能说是鲜明对比。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25470, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鲜明对比", "is_correct": true, "explanation": "“鲜明对比”说明两者差别明显，符合新楼与旧房子一高一矮的描述。"}, {"text": "联系", "is_correct": false, "explanation": "语义：“联系”说明事物相关，不说明高矮的反差。"}, {"text": "相等", "is_correct": false, "explanation": "语义：“相等”指数量或程度一样，与句中一高一矮相冲突。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”用于人或动物，不能用来描述新楼和旧房子。"}], "explanations": {"鲜明对比": "“鲜明对比”说明两者差别明显，符合新楼与旧房子一高一矮的描述。", "联系": "语义：“联系”说明事物相关，不说明高矮的反差。", "相等": "语义：“相等”指数量或程度一样，与句中一高一矮相冲突。", "体重": "搭配：“体重”用于人或动物，不能用来描述新楼和旧房子。"}, "sentence_index": 6, "correct_answer": "鲜明对比"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这对双胞胎长得一模一样，形成了鲜明对比。", "explanation": "“鲜明对比”强调两者差别很明显；长得一模一样没有差别，不能说形成鲜明对比。"}, {"text": "两个同学的答案完全相同，形成了鲜明对比。", "explanation": "“鲜明对比”指差别明显；答案完全相同时没有对比，应说“答案一致”。"}, {"text": "这首歌只有一种旋律，却被说成鲜明对比。", "explanation": "这里应该用〈单一〉。“鲜明对比”需要两个或更多事物互相衬托，只有一种东西时不能说形成鲜明对比。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25470, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两幅画的颜色形成了一只鲜明对比。", "corrected_sentence": "这两幅画的颜色形成了一个鲜明对比。", "error_description": "量词错误：“鲜明对比”是抽象名词，应该用“个”或“种”，不用“只”。“只”多用于动物或成对物品中的一个。正确说法是“一个鲜明对比”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25470, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们两人的性格形成很鲜明对比。", "corrected_sentence": "他们两人的性格形成鲜明对比。", "error_description": "程度副词误用：“鲜明对比”是固定的名词性短语，不能再受“很”修饰。应说“形成鲜明对比”，不说“形成很鲜明对比”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
