INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25476, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "东西会变，不会一直一样。", "primary_collocate": null, "pronunciation": "bù wěn dìng xìng", "ipa": "pu˥˩ wən˨˩˦ tiŋ˥˩ ɕiŋ˥˩", "syllable_count": 4, "sentences": [{"text": "这座桥的不稳定性让工人很担心。", "target_word": "不稳定性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水温的不稳定性影响了实验结果。", "target_word": "不稳定性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机信号的不稳定性让我非常困扰。", "target_word": "不稳定性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生发现病人的心跳有明显的不稳定性。", "target_word": "不稳定性", "complexity_tier": "T3", "furigana": "yī shēng fā xiàn bìng rén de xīn tiào yǒu míng xiǎn de bù wěn dìng xìng", "sentence_source": "generated"}, {"text": "这个公司收入的不稳定性很大。", "target_word": "不稳定性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的情绪有一定的不稳定性。", "target_word": "不稳定性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲了这种液体的不稳定性。", "target_word": "不稳定性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电的不稳定性会导致机器损坏。", "target_word": "不稳定性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要想办法降低价格的不稳定性。", "target_word": "不稳定性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上天气的不稳定性很大，应当携带雨具。", "target_word": "不稳定性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不稳定", "label": "复合"}, {"form": "不穩定性", "label": "繁体"}], "register": "书面", "sense_fingerprint": "东西经常变化、不能一直保持原样的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e9585d0-18df-4185-ab2e-1482e7a5a6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25476, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不稳定性", "is_correct": true, "explanation": "“不稳定性”指东西容易变化，能让工人担心，与句意相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不会让工人担心桥的安全，这样说句意不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”与桥的状况无关，不符合句子的意思。"}, {"text": "美观程度", "is_correct": false, "explanation": "语义：“美观”说外观漂亮，与工人担心的情况无关。"}], "explanations": {"不稳定性": "“不稳定性”指东西容易变化，能让工人担心，与句意相符。", "颜色": "语义：“颜色”不会让工人担心桥的安全，这样说句意不通。", "价格": "语义：“价格”与桥的状况无关，不符合句子的意思。", "美观程度": "语义：“美观”说外观漂亮，与工人担心的情况无关。"}, "sentence_index": 0, "correct_answer": "不稳定性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块大石头一千年都没动过，有很大的不稳定性。", "explanation": "这里应该用〈稳定性〉。一千年都没动说明很稳，“不稳定性”指容易变化，与句意相反。"}, {"text": "这台仪器的不稳定性很好，数据很可靠。", "explanation": "这里应该用〈稳定性〉。数据可靠说明仪器很稳，“不稳定性”指容易变化，不能说“很好”。"}, {"text": "他每天都按时睡觉、按时起床，生活很有不稳定性。", "explanation": "这里应该用〈规律〉。按时作息说明生活有规律，“不稳定性”指容易变化，与句意相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25476, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不稳定性", "is_correct": true, "explanation": "“不稳定性”指东西容易变化，符合“老师讲了这种液体的……”这一语境。"}, {"text": "节拍", "is_correct": false, "explanation": "语义：“节拍”是音乐的时间单位，不能用来指液体的性质，句子不通。"}, {"text": "高潮", "is_correct": false, "explanation": "语义：“高潮”指情节或活动的最高点，与液体的性质无关。"}, {"text": "颜值", "is_correct": false, "explanation": "搭配：“颜值”指外貌的好看程度，不能用来形容液体。"}], "explanations": {"不稳定性": "“不稳定性”指东西容易变化，符合“老师讲了这种液体的……”这一语境。", "节拍": "语义：“节拍”是音乐的时间单位，不能用来指液体的性质，句子不通。", "高潮": "语义：“高潮”指情节或活动的最高点，与液体的性质无关。", "颜值": "搭配：“颜值”指外貌的好看程度，不能用来形容液体。"}, "sentence_index": 6, "correct_answer": "不稳定性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "早起锻炼是他的不稳定性，一直坚持。", "explanation": "这里应该用〈习惯〉。“习惯”指长期形成的行为；“不稳定性”指事物易变，不能说是习惯。"}, {"text": "天气预报的不稳定性很高，我们每天都相信它。", "explanation": "这里应该用〈准确性〉。大家相信预报是因为它准确，“不稳定性”指容易变化，与句意相反。"}, {"text": "老师傅的手艺很有不稳定性，大家都夸他。", "explanation": "这里应该用〈水平〉。大家夸他说明手艺很好，“不稳定性”指容易变化，不能用来夸赞手艺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25476, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座桥有一本明显的不稳定性。", "corrected_sentence": "这座桥有一种明显的不稳定性。", "error_description": "量词错误：“不稳定性”应搭配“种”，“本”用于书册，不能用来修饰这个抽象名词。应改为“一种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25476, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这颗电压的不稳定性让我很担心。", "corrected_sentence": "这种电压的不稳定性让我很担心。", "error_description": "量词错误：“电压”应该用量词“种”，不能用“颗”。“颗”用于小而圆的东西。应改为“这种电压”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
