INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25478, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25478, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西断开了，变成两块。", "primary_collocate": null, "pronunciation": "duàn liè", "ipa": "twan˥˩ ljɛ˥˩", "syllable_count": 2, "sentences": [{"text": "绳子太旧了，一拉就断裂了。", "target_word": "断裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风太大，旗杆从中间断裂了。", "target_word": "断裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块饼干很脆，一掰就断裂成两块。", "target_word": "断裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钢尺弯得太厉害，断裂成了两段。", "target_word": "断裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树枝断裂的声音把小鸟吓跑了。", "target_word": "断裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根铁棒很结实，不会轻易断裂。", "target_word": "断裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁链断裂以后，小船漂走了。", "target_word": "断裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子腿断裂了，我们只好换一张。", "target_word": "断裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弹弓的橡皮筋拉得太长，断裂了。", "target_word": "断裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老木梁承受不了雪的重量，断裂了。", "target_word": "断裂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "断裂了", "label": "体标"}, {"form": "断裂过", "label": "体标"}, {"form": "断裂带", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西断开变成两块", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e9585d0-18df-4185-ab2e-1482e7a5a6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25478, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "断裂", "is_correct": true, "explanation": "断裂指东西断开变成两块，符合绳子一拉就断的语境。"}, {"text": "融化", "is_correct": false, "explanation": "语义：“融化”指固体受热变成液体，绳子一拉不会融化，与语境不符。"}, {"text": "生锈", "is_correct": false, "explanation": "搭配：“生锈”只用于金属，绳子不能生锈而断开。"}, {"text": "开花", "is_correct": false, "explanation": "语义：“开花”只用于植物，绳子一拉不会开花。"}], "explanations": {"断裂": "断裂指东西断开变成两块，符合绳子一拉就断的语境。", "融化": "语义：“融化”指固体受热变成液体，绳子一拉不会融化，与语境不符。", "生锈": "搭配：“生锈”只用于金属，绳子不能生锈而断开。", "开花": "语义：“开花”只用于植物，绳子一拉不会开花。"}, "sentence_index": 0, "correct_answer": "断裂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件毛衣洗了一次，颜色就断裂了。", "explanation": "这里应该用〈褪色〉。“断裂”指物体断成几段，颜色变淡要说褪色。"}, {"text": "墙上的一幅画，被风吹得断裂了。", "explanation": "这里应该用〈破损〉。画纸被风吹坏、划破要说破损，断裂不用于平面纸张。"}, {"text": "他的衬衫一被钩子勾住，就断裂了。", "explanation": "这里应该用〈破〉。衣服被勾破要说破；断裂只用于受力后断成两块的硬物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25478, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "断裂", "is_correct": true, "explanation": "断裂指铁链断开，才会使小船漂走，符合句子的因果关系。"}, {"text": "歌唱", "is_correct": false, "explanation": "搭配：“歌唱”只用于人或鸟，铁链不能歌唱。"}, {"text": "膨胀", "is_correct": false, "explanation": "语义：“膨胀”指体积变大，与“小船漂走”的结果没有因果关系。"}, {"text": "燃烧", "is_correct": false, "explanation": "语义：“燃烧”指物体着火，铁链燃烧与小船漂走不构成合理的因果。"}], "explanations": {"断裂": "断裂指铁链断开，才会使小船漂走，符合句子的因果关系。", "歌唱": "搭配：“歌唱”只用于人或鸟，铁链不能歌唱。", "膨胀": "语义：“膨胀”指体积变大，与“小船漂走”的结果没有因果关系。", "燃烧": "语义：“燃烧”指物体着火，铁链燃烧与小船漂走不构成合理的因果。"}, "sentence_index": 6, "correct_answer": "断裂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河的水流很急，河水突然断裂了。", "explanation": "这里应该用〈断流〉。河水停止流动要说断流；断裂只用于物体断成几段。"}, {"text": "盐放进热水里，断裂了。", "explanation": "这里应该用〈溶解〉。盐在水中化开属于溶解，断裂只表示受力后分成几段。"}, {"text": "苹果放久了，断裂了。", "explanation": "这里应该用〈腐烂〉。水果放久变质要说腐烂，断裂只用于受力断成几段的物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25478, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这根铁丝一弯就断裂两段。", "corrected_sentence": "这根铁丝一弯就断裂成两段。", "error_description": "“断裂”后要用“成”引出结果，应说“断裂成两段”；直接接数量词是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25478, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "木桶的底板被断裂了，水全漏光了。", "corrected_sentence": "木桶的底板断裂了，水全漏光了。", "error_description": "“断裂”是不及物动词，前面不能加“被”，应说“木桶的底板断裂了”；加“被”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
