INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25488, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种由很少的小分子连在一起组成的短链。", "primary_collocate": null, "pronunciation": "dī jù wù", "ipa": "ti˥ tɕy˥˩ u˥˩", "syllable_count": 3, "sentences": [{"text": "这种低聚物只有几个小分子连在一起。", "target_word": "低聚物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "低聚物比塑料的分子小得多。", "target_word": "低聚物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了低聚物的图片。", "target_word": "低聚物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瓶子里的低聚物像一层透明的油。", "target_word": "低聚物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在实验室里做出了一点低聚物。", "target_word": "低聚物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "低聚物再连下去，就会变成大分子。", "target_word": "低聚物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几个小分子连成了低聚物。", "target_word": "低聚物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "低聚物的分子不大，也不太重。", "target_word": "低聚物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "课本上说，低聚物是很短的链。", "target_word": "低聚物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把低聚物放进了另一个瓶子里。", "target_word": "低聚物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "低聚物|由很少的小分子连成的短链", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d87bd1f-744f-4914-a5d1-ee173b9f4aec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25488, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "低聚物", "is_correct": true, "explanation": "低聚物：由很少的小分子连在一起组成的短链，与“只有几个小分子连在一起”相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是矿物，不是由几个小分子连成的分子，与句意不符。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：空气是混合物，其中的分子并不相连，不能说“连在一起”。"}, {"text": "面粉", "is_correct": false, "explanation": "语义：面粉是食物原料，不是由几个小分子连成的分子。"}], "explanations": {"低聚物": "低聚物：由很少的小分子连在一起组成的短链，与“只有几个小分子连在一起”相符。", "石头": "语义：石头是矿物，不是由几个小分子连成的分子，与句意不符。", "空气": "搭配：空气是混合物，其中的分子并不相连，不能说“连在一起”。", "面粉": "语义：面粉是食物原料，不是由几个小分子连成的分子。"}, "sentence_index": 0, "correct_answer": "低聚物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "低聚物是一个个独立的小分子。", "explanation": "这里应该用〈单体〉。低聚物是由少量小分子连在一起的短链，不是独立的小分子。"}, {"text": "低聚物由成千上万个小分子连在一起。", "explanation": "这里应该用〈高分子〉。低聚物只由很少的小分子连在一起，成千上万个小分子连成的是高分子。"}, {"text": "这种低聚物是一块金属，导电性很好。", "explanation": "这里误把低聚物说成了金属。低聚物是由少量小分子连成的短链，不是金属单质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25488, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "低聚物", "is_correct": true, "explanation": "低聚物：由几个小分子连成的短链，与句意相符。"}, {"text": "单体", "is_correct": false, "explanation": "语义：单体是单个的基本单元，不能由几个小分子“连成”。"}, {"text": "面粉", "is_correct": false, "explanation": "语义：面粉不是分子，不能由几个小分子连成。"}, {"text": "颜料", "is_correct": false, "explanation": "搭配：“连成”多用于链状、片状结构，不能说“连成颜料”。"}], "explanations": {"低聚物": "低聚物：由几个小分子连成的短链，与句意相符。", "单体": "语义：单体是单个的基本单元，不能由几个小分子“连成”。", "面粉": "语义：面粉不是分子，不能由几个小分子连成。", "颜料": "搭配：“连成”多用于链状、片状结构，不能说“连成颜料”。"}, "sentence_index": 6, "correct_answer": "低聚物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "低聚物的强度很高，不容易断裂。", "explanation": "这里应该用〈聚合物〉。低聚物分子很小，强度不高，不能说它不容易断裂。"}, {"text": "低聚物是一条很长的链。", "explanation": "这里应该用〈大分子〉。低聚物是很短的链，很长的链是大分子的特点。"}, {"text": "低聚物的分子很大，所以很硬。", "explanation": "这里应该用〈树脂〉。低聚物的分子很小，不能说分子很大、很硬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25488, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只低聚物是由两个小分子连成的。", "corrected_sentence": "这种低聚物是由两个小分子连成的。", "error_description": "量词错误：“低聚物”是物质名称，应用“种”，“只”用于动物或单个器物，不能说“这只低聚物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25488, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把一张低聚物装进了小瓶子。", "corrected_sentence": "我把一种低聚物装进了小瓶子。", "error_description": "量词错误：“张”用于纸、桌子等平面的东西，低聚物是物质，应说“一种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
