INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25490, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "动物和植物生活需要的东西，比如水、阳光和空气。", "primary_collocate": null, "pronunciation": "shēng tài tiáo jiàn", "ipa": "ʂɤŋ˥ tʰaɪ˥˩ tʰjaʊ˧˥ tɕjɛn˥˩", "syllable_count": 4, "sentences": [{"text": "水、阳光和空气是植物的生态条件。", "target_word": "生态条件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鱼需要干净的水，这是它的生态条件。", "target_word": "生态条件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "花园里的生态条件不错，花开得很好。", "target_word": "生态条件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个鱼缸的生态条件太差，鱼都死了。", "target_word": "生态条件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要给小鸟提供好的生态条件。", "target_word": "生态条件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水少了，动物的生态条件就不好了。", "target_word": "生态条件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说动物的生态条件有水和空气。", "target_word": "生态条件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山上有水有阳光，生态条件很好。", "target_word": "生态条件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的空气和水都很好，生态条件不错。", "target_word": "生态条件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "树要长大，需要合适的生态条件。", "target_word": "生态条件", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "动植物生活所需的水、阳光、空气等东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1464a407-3635-4c26-9c56-965320c82102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25490, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学历", "is_correct": false, "explanation": "语义：“学历”指人受教育的程度，植物没有学历。"}, {"text": "生态条件", "is_correct": true, "explanation": "正确。指动植物生活所需的水、阳光、空气等，与句中所列内容一致。"}, {"text": "收入", "is_correct": false, "explanation": "搭配：“收入”用于人或单位的钱财，不能说植物的收入。"}, {"text": "人口", "is_correct": false, "explanation": "语义：“人口”指人的数量，与植物无关。"}], "explanations": {"学历": "语义：“学历”指人受教育的程度，植物没有学历。", "生态条件": "正确。指动植物生活所需的水、阳光、空气等，与句中所列内容一致。", "收入": "搭配：“收入”用于人或单位的钱财，不能说植物的收入。", "人口": "语义：“人口”指人的数量，与植物无关。"}, "sentence_index": 0, "correct_answer": "生态条件"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司的生态条件很好，员工都很满意。", "explanation": "这里应该用〈工作条件〉。生态条件指生物生存的自然环境，公司的工作环境应说“工作条件”。"}, {"text": "她的生态条件很好，身体很结实。", "explanation": "这里应该用〈身体条件〉。生态条件指生物生存的环境因素，不能用来形容人的身体状况。"}, {"text": "这个周末的生态条件很好，我们去郊游吧。", "explanation": "这里应该用〈天气条件〉。生态条件指动植物生存所需的东西，周末去郊游看的是天气，应说“天气条件”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25490, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "语义：“价格”指商品的钱数，动物的价格与“有水和空气”无关。"}, {"text": "生态条件", "is_correct": true, "explanation": "正确。指动物生活所需的环境条件，与“有水和空气”一致。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”只说大小，不能说动物的年龄有水和空气。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是体格特征，与水和空气无关。"}], "explanations": {"价格": "语义：“价格”指商品的钱数，动物的价格与“有水和空气”无关。", "生态条件": "正确。指动物生活所需的环境条件，与“有水和空气”一致。", "年龄": "搭配：“年龄”只说大小，不能说动物的年龄有水和空气。", "身高": "体貌：“身高”是体格特征，与水和空气无关。"}, "sentence_index": 6, "correct_answer": "生态条件"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子的生态条件很好，他有独立的书房。", "explanation": "这里应该用〈学习条件〉。生态条件指生物生存的自然环境，不用来形容孩子的学习环境。"}, {"text": "这辆车的生态条件很好，跑得很快。", "explanation": "这里应该用〈硬件条件〉。生态条件指生物的自然环境，汽车的配置要说“硬件条件”。"}, {"text": "这家超市的生态条件很好，顾客很多。", "explanation": "这里应该用〈经营条件〉。生态条件指生物生存的环境因素，超市的经营状况要说“经营条件”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25490, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "湖里的生态条件了很好，鱼虾都很多。", "corrected_sentence": "湖里的生态条件很好，鱼虾都很多。", "error_description": "助词错误：“了”误加在“生态条件”之后。“生态条件”后不能直接接“了”，应去掉“了”，说“生态条件很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25490, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座山得生态条件很好，松树都长得很高。", "corrected_sentence": "这座山的生态条件很好，松树都长得很高。", "error_description": "助词错误：修饰名词“生态条件”的“的”误写成“得”。“得”用于动词后作补语，此处应用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25492, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "独立", "is_correct": true, "explanation": "正确：“独立”与“依赖于”构成反义，表示不需要别人或别的东西就能做成某事。"}, {"text": "分享", "is_correct": false, "explanation": "分享：与“依赖于”没有反义关系，说的是共同拥有。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论：与“依赖于”没有反义关系，表示交流意见。"}, {"text": "储存", "is_correct": false, "explanation": "储存：与“依赖于”没有反义关系，表示把东西保存起来。"}], "correct_answer": "独立", "explanations": {"独立": "正确：“独立”与“依赖于”构成反义，表示不需要别人或别的东西就能做成某事。", "分享": "分享：与“依赖于”没有反义关系，说的是共同拥有。", "讨论": "讨论：与“依赖于”没有反义关系，表示交流意见。", "储存": "储存：与“依赖于”没有反义关系，表示把东西保存起来。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25492, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "独立", "is_correct": true, "explanation": "正确：“独立”与“依赖于”构成反义，表示不需要别的东西就能做成某事。"}, {"text": "完成", "is_correct": false, "explanation": "完成：与“依赖于”没有反义关系，表示把事情做成。"}, {"text": "提供", "is_correct": false, "explanation": "提供：与“依赖于”没有反义关系，表示供给所需的东西。"}, {"text": "出发", "is_correct": false, "explanation": "出发：与“依赖于”没有反义关系，表示动身前往某地。"}], "correct_answer": "独立", "explanations": {"独立": "正确：“独立”与“依赖于”构成反义，表示不需要别的东西就能做成某事。", "完成": "完成：与“依赖于”没有反义关系，表示把事情做成。", "提供": "提供：与“依赖于”没有反义关系，表示供给所需的东西。", "出发": "出发：与“依赖于”没有反义关系，表示动身前往某地。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25492, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "需要别的东西才能做某事。", "primary_collocate": null, "pronunciation": "yī lài yú", "ipa": "i˥ laɪ˥˩ y˧˥", "syllable_count": 3, "sentences": [{"text": "小孩吃饭依赖于大人的帮助。", "target_word": "依赖于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我现在的生活依赖于这份工作。", "target_word": "依赖于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人走路依赖于拐杖。", "target_word": "依赖于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他学中文依赖于手机上的词典。", "target_word": "依赖于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器的运转依赖于电。", "target_word": "依赖于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人买东西依赖于网上商店。", "target_word": "依赖于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼的呼吸依赖于水里的氧气。", "target_word": "依赖于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写文章依赖于电脑，没有电脑就写不出来。", "target_word": "依赖于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的旅行依赖于朋友的车。", "target_word": "依赖于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小鸟还不会飞，生存依赖于妈妈的喂养。", "target_word": "依赖于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "依赖性", "label": "复合"}, {"form": "相互依赖", "label": "复合"}], "register": "书面", "sense_fingerprint": "要靠别的人或东西才能做成某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc05871b-dbfb-4323-99f2-f0bf55bd0d59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25492, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "依赖于", "is_correct": true, "explanation": "正确：“依赖于”表示吃饭这件事需要大人的帮助作为条件。"}, {"text": "属于", "is_correct": false, "explanation": "语义：“属于”表示归于某类或为某人所有，与吃饭需要别人帮助的意思不符。"}, {"text": "忙于", "is_correct": false, "explanation": "搭配：“忙于”接的是事务，不能接“帮助”，与句中的用法不搭。"}, {"text": "讲解", "is_correct": false, "explanation": "搭配：“讲解”接的是内容或知识，“大人的帮助”不能被讲解。"}], "explanations": {"依赖于": "正确：“依赖于”表示吃饭这件事需要大人的帮助作为条件。", "属于": "语义：“属于”表示归于某类或为某人所有，与吃饭需要别人帮助的意思不符。", "忙于": "搭配：“忙于”接的是事务，不能接“帮助”，与句中的用法不搭。", "讲解": "搭配：“讲解”接的是内容或知识，“大人的帮助”不能被讲解。"}, "sentence_index": 0, "correct_answer": "依赖于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在车站依赖于朋友。", "explanation": "这里应该用〈等待〉。等待是等人或事情到来；“依赖于”表示需要某事才能做成，不能表示等人。"}, {"text": "这张床依赖于墙壁摆放。", "explanation": "这里应该用〈靠着〉。表示物体挨着墙的位置，“依赖于”不用于描述物体的位置。"}, {"text": "他依赖于责任，总是不肯负责。", "explanation": "这里应该用〈逃避〉。逃避是躲开责任；“依赖于”表示以某事为必要条件，与“不肯负责”的意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25492, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "依赖于", "is_correct": true, "explanation": "正确：鱼的呼吸以水里的氧气为必要条件，符合“依赖于”的用法。"}, {"text": "关闭", "is_correct": false, "explanation": "语义：鱼的呼吸不能“关闭”水里的氧气，关闭与呼吸的需要相悖。"}, {"text": "排斥", "is_correct": false, "explanation": "语义：鱼需要氧气，不会排斥氧气，与句意相反。"}, {"text": "出售", "is_correct": false, "explanation": "搭配：“出售”接的是商品，氧气不能被鱼“出售”，与“呼吸”不搭。"}], "explanations": {"依赖于": "正确：鱼的呼吸以水里的氧气为必要条件，符合“依赖于”的用法。", "关闭": "语义：鱼的呼吸不能“关闭”水里的氧气，关闭与呼吸的需要相悖。", "排斥": "语义：鱼需要氧气，不会排斥氧气，与句意相反。", "出售": "搭配：“出售”接的是商品，氧气不能被鱼“出售”，与“呼吸”不搭。"}, "sentence_index": 6, "correct_answer": "依赖于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在公园里依赖于美景。", "explanation": "这里应该用〈欣赏〉。欣赏是观看并赞美景物；“依赖于”表示必要条件，不能表示欣赏。"}, {"text": "士兵们依赖于敌人的进攻。", "explanation": "这里应该用〈抵抗〉。抵抗是对抗敌人；“依赖于”表示依靠条件，不能表示对抗。"}, {"text": "我们周末去医院依赖于病人。", "explanation": "这里应该用〈看望〉。看望是探望病人；“依赖于”不表示探望，用在这里不合适。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25492, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的健康也依赖于也良好的睡眠。", "corrected_sentence": "他的健康也依赖于良好的睡眠。", "error_description": "“也”重复错误：“也”已经放在“依赖于”前面，不能再插在“于”和“良好”之间，应删去第二个“也”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25492, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小组的成功依赖于了每个人的努力。", "corrected_sentence": "这个小组的成功依赖于每个人的努力。", "error_description": "“了”的位置错误：“了”不能放在介词“于”和宾语之间，这句话不需要“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
