INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25494, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "生物质是动物、植物和它们的废物，可以变成能源。", "primary_collocate": null, "pronunciation": "shēng wù zhì", "ipa": "ʂɤŋ˥ u˥˩ ʈʂɻ̩˥˩", "syllable_count": 3, "sentences": [{"text": "树叶是一种生物质。", "target_word": "生物质", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "生物质可以用来做燃料。", "target_word": "生物质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他家用生物质烧水做饭。", "target_word": "生物质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "草和木头都是生物质。", "target_word": "生物质", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这些生物质可以变成电。", "target_word": "生物质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厨房里的剩菜也是生物质。", "target_word": "生物质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们应该多用生物质，少用煤。", "target_word": "生物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了什么是生物质。", "target_word": "生物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里用生物质发电已经三年了。", "target_word": "生物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物的废物也能当生物质用。", "target_word": "生物质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生物质能", "label": "复合"}, {"form": "生物质燃料", "label": "复合"}], "register": "中性", "sense_fingerprint": "动物、植物及其废物，能变成能源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc05871b-dbfb-4323-99f2-f0bf55bd0d59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25494, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生物质", "is_correct": true, "explanation": "正确：树叶属于动植物及其废弃物，可以作为能源，所以是生物质。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：树叶不是乐器，“一种乐器”与树叶的性质不符。"}, {"text": "矿物", "is_correct": false, "explanation": "语义：矿物是无机物，树叶是有机的植物部分，不是矿物。"}, {"text": "金属", "is_correct": false, "explanation": "语义：金属是无机物，树叶是植物的一部分，不是金属。"}], "explanations": {"生物质": "正确：树叶属于动植物及其废弃物，可以作为能源，所以是生物质。", "乐器": "语义：树叶不是乐器，“一种乐器”与树叶的性质不符。", "矿物": "语义：矿物是无机物，树叶是有机的植物部分，不是矿物。", "金属": "语义：金属是无机物，树叶是植物的一部分，不是金属。"}, "sentence_index": 0, "correct_answer": "生物质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用生物质给妈妈打了个电话。", "explanation": "这里应该用〈手机〉。打电话要用手机；生物质指可作能源的动植物及其废物，不能用来打电话。"}, {"text": "这座动物园里养了很多生物质。", "explanation": "这里应该用〈动物〉。养的是活的动物，应说“养了很多动物”；“生物质”指作为能源原料的动植物及其废物，不用于说饲养。"}, {"text": "这辆卡车的油箱里加满了生物质。", "explanation": "这里应该用〈燃料〉。油箱加的是燃料，生物质是原料，不能直接加进油箱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25494, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生物质", "is_correct": true, "explanation": "正确：生物质可替代煤作能源，与“少用煤”形成对比。"}, {"text": "水泥", "is_correct": false, "explanation": "语义：水泥是建筑材料，不能像煤一样作燃料，与“多用”的用途不合。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“多用”要接能源或材料，空气不能被当作燃料来“用”，与“少用煤”不搭。"}, {"text": "黄金", "is_correct": false, "explanation": "语义：黄金是贵重金属，不是能源，不能代替煤。"}], "explanations": {"生物质": "正确：生物质可替代煤作能源，与“少用煤”形成对比。", "水泥": "语义：水泥是建筑材料，不能像煤一样作燃料，与“多用”的用途不合。", "空气": "搭配：“多用”要接能源或材料，空气不能被当作燃料来“用”，与“少用煤”不搭。", "黄金": "语义：黄金是贵重金属，不是能源，不能代替煤。"}, "sentence_index": 6, "correct_answer": "生物质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汤里放了一勺生物质。", "explanation": "这里应该用〈食盐〉。汤里调味用食盐，生物质是能源或材料，不能当调料。"}, {"text": "学生用生物质写字。", "explanation": "这里应该用〈墨水〉。写字用墨水或笔，生物质不能用来写字。"}, {"text": "他的眼镜片是用生物质做的。", "explanation": "这里应该用〈玻璃〉。镜片用玻璃或树脂，生物质不能用来做镜片。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25494, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村里用生物质过取暖。", "corrected_sentence": "村里用生物质取暖。", "error_description": "“过”的位置错误：“过”不应放在宾语“生物质”后面；此句不表示经历，无需“过”，应删去，说“村里用生物质取暖”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25494, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个工厂每天都要买一只生物质。", "corrected_sentence": "这个工厂每天都要买一堆生物质。", "error_description": "量词错误：生物质是成堆的物料，应说“一堆”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
