INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25496, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "意思是把一个大东西分成几个小东西。", "primary_collocate": null, "pronunciation": "liè jiě", "ipa": "ljɛ˥˩ tɕjɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "大分子裂解成几个小分子。", "target_word": "裂解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高温能让大分子裂解。", "target_word": "裂解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料会慢慢裂解成小块。", "target_word": "裂解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个大分子裂解后变成三个小分子。", "target_word": "裂解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水加热后不会裂解。", "target_word": "裂解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，裂解就是把大的分成小的。", "target_word": "裂解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石油裂解后可以做很多东西。", "target_word": "裂解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大分子裂解以后，变得更小了。", "target_word": "裂解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用高温让这种塑料裂解。", "target_word": "裂解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小分子不会再裂解了。", "target_word": "裂解", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "裂解了", "label": "体标"}, {"form": "裂解过", "label": "体标"}, {"form": "热裂解", "label": "复合"}], "register": "通用", "sense_fingerprint": "大东西分成几个小东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d87bd1f-744f-4914-a5d1-ee173b9f4aec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25496, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "裂解", "is_correct": true, "explanation": "裂解：大东西分成几个小东西，与句意一致。"}, {"text": "合并", "is_correct": false, "explanation": "语义：“合并”指多个合为一个，与“大分子变成几个小分子”的方向相反。"}, {"text": "组装", "is_correct": false, "explanation": "搭配：“组装”多用于零件、机器，不能与“大分子”搭配。"}, {"text": "融合", "is_correct": false, "explanation": "语义：“融合”指两者结合成一体，与句中由大变小的方向相反。"}], "explanations": {"裂解": "裂解：大东西分成几个小东西，与句意一致。", "合并": "语义：“合并”指多个合为一个，与“大分子变成几个小分子”的方向相反。", "组装": "搭配：“组装”多用于零件、机器，不能与“大分子”搭配。", "融合": "语义：“融合”指两者结合成一体，与句中由大变小的方向相反。"}, "sentence_index": 0, "correct_answer": "裂解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这几个小分子在催化剂作用下裂解成了一个大分子。", "explanation": "这里应该用〈聚合〉。裂解是大东西分成小东西，这里是小分子结合成大分子，方向正好相反。"}, {"text": "两种颜料裂解成了一种新颜色。", "explanation": "这里应该用〈结合〉。裂解表示一个分成几个，不能说两种颜料分开后形成一种新颜色。"}, {"text": "两个轻原子核裂解成了一个重原子核。", "explanation": "这里应该用〈聚变〉。裂解是分开，这里是两个原子核合为一个，方向相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25496, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "裂解", "is_correct": true, "explanation": "裂解：石油在高温下裂解成小分子，可用来做很多产品，符合句意。"}, {"text": "种植", "is_correct": false, "explanation": "搭配：“种植”用于作物、植物，石油不能被种植。"}, {"text": "雕刻", "is_correct": false, "explanation": "语义：“雕刻”指用工具在固体上刻出形状，石油是液体，与句意不符。"}, {"text": "编织", "is_correct": false, "explanation": "语义：“编织”指用线、绳等交错做成物品，与石油加工的产物不符。"}], "explanations": {"裂解": "裂解：石油在高温下裂解成小分子，可用来做很多产品，符合句意。", "种植": "搭配：“种植”用于作物、植物，石油不能被种植。", "雕刻": "语义：“雕刻”指用工具在固体上刻出形状，石油是液体，与句意不符。", "编织": "语义：“编织”指用线、绳等交错做成物品，与石油加工的产物不符。"}, "sentence_index": 6, "correct_answer": "裂解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "铁块加热后裂解成了铁水。", "explanation": "这里应该用〈熔化〉。铁块受热只是变成液态，没有分成几个小东西，不能用裂解。"}, {"text": "湖水在低温下裂解成了冰。", "explanation": "这里应该用〈结冰〉。水变成冰是状态改变，并没有把一个大东西分成几个小东西。"}, {"text": "汽油在常温下裂解成了气体。", "explanation": "这里应该用〈挥发〉。汽油在常温下变为气体是挥发，不是大东西分成小东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25496, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "高温下，这种大分子裂解了成两个小分子。", "corrected_sentence": "高温下，这种大分子裂解成了两个小分子。", "error_description": "补语与体标错误：“了”应放在结果补语“成”之后，应说“裂解成了两个小分子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25496, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种大分子在常温下裂解了过。", "corrected_sentence": "这种大分子在常温下裂解过。", "error_description": "体标错误：“了”与“过”不能同用，同一动词后只能用其一，应说“裂解过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
