INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25498, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "变得不一样。", "primary_collocate": null, "pronunciation": "zhuǎn biàn", "ipa": "tʂwan˨˩˦ pjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这几年，我的生活转变了很多。", "target_word": "转变", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他长大后，性格转变了。", "target_word": "转变", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的想法转变得很快。", "target_word": "转变", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一切都转变了，我几乎认不出这里。", "target_word": "转变", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "时间一长，大家的关系转变了。", "target_word": "转变", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他来到新学校后，整个人都转变了。", "target_word": "转变", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "世界正在不停地转变。", "target_word": "转变", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "十年过去了，他对工作的态度转变了不少。", "target_word": "转变", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她结婚以后转变了很多。", "target_word": "转变", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市在转变着，老街越来越少了。", "target_word": "转变", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "转变了", "label": "完成体"}, {"form": "转变过", "label": "经历体"}, {"form": "转变着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "人或事物变得和以前不同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18b3f918-5c54-4472-be9f-e910ce51db7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25498, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "转变", "is_correct": true, "explanation": "「转变」指生活变成另一种样子，与「我的生活……了很多」相符。"}, {"text": "转动", "is_correct": false, "explanation": "语义：「转动」指物体旋转，生活不能转动。"}, {"text": "转播", "is_correct": false, "explanation": "搭配：「转播」指播送信号，不能与「生活」搭配。"}, {"text": "转身", "is_correct": false, "explanation": "语义：「转身」指人的身体动作，不能用来指生活的变化。"}], "explanations": {"转变": "「转变」指生活变成另一种样子，与「我的生活……了很多」相符。", "转动": "语义：「转动」指物体旋转，生活不能转动。", "转播": "搭配：「转播」指播送信号，不能与「生活」搭配。", "转身": "语义：「转身」指人的身体动作，不能用来指生活的变化。"}, "sentence_index": 0, "correct_answer": "转变"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月我的身高转变了五厘米。", "explanation": "这里应该用〈增加〉。转变指事物性质或状态的变化，身高的增长是数量变化，应用增加。"}, {"text": "他转变了作业的答案。", "explanation": "这里应该用〈修改〉。转变指事物自身形式或状态的变化，人为的改动应用修改。"}, {"text": "他把书转变到了桌子上。", "explanation": "这里应该用〈放〉。转变指事物性质或状态的变化，把东西放到某处不能说转变。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44a1f037-7793-4423-b2e9-2ec73afc657c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25498, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "转变", "is_correct": true, "explanation": "「转变」指事物变得和以前不同，与「世界正在不停地」相符。"}, {"text": "转播", "is_correct": false, "explanation": "搭配：「转播」指播送信号，不能与「世界」搭配。"}, {"text": "转手", "is_correct": false, "explanation": "语义：「转手」指把东西卖给别人，与世界的变化无关。"}, {"text": "转卖", "is_correct": false, "explanation": "语义：「转卖」指把买来的东西再卖出，不能用来指世界的变化。"}], "explanations": {"转变": "「转变」指事物变得和以前不同，与「世界正在不停地」相符。", "转播": "搭配：「转播」指播送信号，不能与「世界」搭配。", "转手": "语义：「转手」指把东西卖给别人，与世界的变化无关。", "转卖": "语义：「转卖」指把买来的东西再卖出，不能用来指世界的变化。"}, "sentence_index": 6, "correct_answer": "转变"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个月我的零花钱转变了五十元。", "explanation": "这里应该用〈减少〉。转变指事物性质或状态的变化，零花钱数额的减少是数量变化，应用减少。"}, {"text": "他转变了作文里的错别字。", "explanation": "这里应该用〈改正〉。转变指事物性质或状态的变化，错别字的纠正应用改正。"}, {"text": "他转变了屏幕的亮度。", "explanation": "这里应该用〈调节〉。转变指事物性质或状态的变化，屏幕亮度的高低调整应用调节。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44a1f037-7793-4423-b2e9-2ec73afc657c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25498, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的态度从反对转变在支持。", "corrected_sentence": "他的态度从反对转变为支持。", "error_description": "「转变」的结果要用「为」或「成」引出，这里误用「在」。正确：「从反对转变为支持」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44a1f037-7793-4423-b2e9-2ec73afc657c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25498, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的风格一直没有转变了。", "corrected_sentence": "这家店的风格一直没有转变。", "error_description": "「没有」否定动作，不能再加表示完成的「了」。正确：「一直没有转变」，去掉「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44a1f037-7793-4423-b2e9-2ec73afc657c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
