INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25500, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "东西里面亮晶晶的小块有多少。", "primary_collocate": null, "pronunciation": "jié jīng dù", "ipa": "tɕjɛ˧˥ tɕiŋ˥ tu˥˩", "syllable_count": 3, "sentences": [{"text": "这块糖的结晶度很高，里面全是小亮块。", "target_word": "结晶度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盐的结晶度高，看起来亮晶晶的。", "target_word": "结晶度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜂蜜放久了，结晶度会变高。", "target_word": "结晶度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你看，这杯蜂蜜的结晶度比那杯低。", "target_word": "结晶度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰糖的结晶度比白糖高得多。", "target_word": "结晶度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说，结晶度低的糖更软。", "target_word": "结晶度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种盐里亮块多，结晶度很高。", "target_word": "结晶度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "糖放进冰箱以后，结晶度变高了。", "target_word": "结晶度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想知道这块糖的结晶度是多少。", "target_word": "结晶度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "糖里的亮块越多，结晶度就越高。", "target_word": "结晶度", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "結晶度", "label": "繁体"}, {"form": "相对结晶度", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西里亮晶晶小块的多少，日常说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc05871b-dbfb-4323-99f2-f0bf55bd0d59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25500, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "结晶度", "is_correct": true, "explanation": "结晶度：指东西里亮晶晶小块的多少，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”一般说深浅，不说“很高”。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指性情，与糖里的亮块无关，句子说不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指存在的时间，与糖里的亮块无关。"}], "explanations": {"结晶度": "结晶度：指东西里亮晶晶小块的多少，符合句意。", "颜色": "搭配：“颜色”一般说深浅，不说“很高”。", "脾气": "语义：“脾气”指性情，与糖里的亮块无关，句子说不通。", "年龄": "语义：“年龄”指存在的时间，与糖里的亮块无关。"}, "sentence_index": 0, "correct_answer": "结晶度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯蜂蜜的结晶度比那杯甜。", "explanation": "这里应该用〈味道〉。结晶度指东西里亮晶小块的多少，不能用来比较甜不甜，要说“味道”。"}, {"text": "这块糖的结晶度很硬，不容易咬碎。", "explanation": "这里应该用〈硬度〉。结晶度说的是亮晶小块的多少，不能用来说软硬，要说“硬度”。"}, {"text": "这袋糖的结晶度太大，我拿不动。", "explanation": "这里应该用〈重量〉。结晶度指东西里亮晶小块的多少，不能用来说轻重，拿不动要说“重量”太大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25500, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "结晶度", "is_correct": true, "explanation": "结晶度：指东西里亮晶晶小块的多少，符合“亮块多，……很高”的句意。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指人或动物的重量，与盐里的亮块无关。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”说的是人的高矮，用于盐说不通。"}, {"text": "血压", "is_correct": false, "explanation": "语义：“血压”指人体血管中的压力，与盐里的亮块无关，句子说不通。"}], "explanations": {"结晶度": "结晶度：指东西里亮晶晶小块的多少，符合“亮块多，……很高”的句意。", "体重": "语义：“体重”指人或动物的重量，与盐里的亮块无关。", "身高": "语义：“身高”说的是人的高矮，用于盐说不通。", "血压": "语义：“血压”指人体血管中的压力，与盐里的亮块无关，句子说不通。"}, "sentence_index": 6, "correct_answer": "结晶度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "糖水里出现了结晶度。", "explanation": "这里应该用〈沉淀〉。结晶度是比例，不是能出现的东西，应说“出现了沉淀”。"}, {"text": "这块糖的结晶度很白。", "explanation": "这里应该用〈颜色〉。结晶度说的是亮晶小块的多少，不能用来形容颜色，颜色才说“很白”。"}, {"text": "蜂蜜放久了，结晶度会变香。", "explanation": "这里应该用〈香味〉。结晶度只说明亮晶小块的多少，不能说香不香；蜂蜜变香要说“香味”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25500, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这包盐的结晶度低很，颜色发白。", "corrected_sentence": "这包盐的结晶度很低，颜色发白。", "error_description": "程度副词“很”应放在“低”的前面作状语，说“很低”。放在“低”后面，句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25500, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块冰糖的结晶度比那块高多得。", "corrected_sentence": "这块冰糖的结晶度比那块高得多。", "error_description": "程度补语“得多”应放在形容词之后，说“高得多”。“高多得”的顺序是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
