INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25502, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西变得像玻璃一样又硬又透明。", "primary_collocate": null, "pronunciation": "bō li huà", "ipa": "pwo˥ li xwa˥˩", "syllable_count": 3, "sentences": [{"text": "如果糖水冷得很快，就会玻璃化。", "target_word": "玻璃化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块糖玻璃化以后，又硬又透明。", "target_word": "玻璃化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "树脂放久了，慢慢玻璃化了。", "target_word": "玻璃化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把糖加热再冷却，它会玻璃化。", "target_word": "玻璃化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜂蜜遇到极低的温度，会玻璃化。", "target_word": "玻璃化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些糖已经玻璃化，像小玻璃片。", "target_word": "玻璃化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "软软的胶一冻就玻璃化，变得很硬。", "target_word": "玻璃化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨师让糖浆玻璃化，做成透明的糖片。", "target_word": "玻璃化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "糖玻璃化以后，一敲就碎。", "target_word": "玻璃化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水果糖玻璃化时，颜色看起来像玻璃。", "target_word": "玻璃化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "玻璃化了", "label": "体标"}], "register": "中性", "sense_fingerprint": "东西变得像玻璃一样又硬又透明，日常说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc05871b-dbfb-4323-99f2-f0bf55bd0d59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25502, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "玻璃化", "is_correct": true, "explanation": "正确。“玻璃化”在句中指糖水冷却后变得像玻璃一样又硬又透明，符合动词义。"}, {"text": "沸腾", "is_correct": false, "explanation": "语义：沸腾需要加热，句中说的是冷却，方向相反。"}, {"text": "融化", "is_correct": false, "explanation": "语义：融化需要升温，句中是冷得很快，二者方向相反。"}, {"text": "生锈", "is_correct": false, "explanation": "搭配：“生锈”只用于金属，不能与“糖水”搭配。"}], "explanations": {"玻璃化": "正确。“玻璃化”在句中指糖水冷却后变得像玻璃一样又硬又透明，符合动词义。", "沸腾": "语义：沸腾需要加热，句中说的是冷却，方向相反。", "融化": "语义：融化需要升温，句中是冷得很快，二者方向相反。", "生锈": "搭配：“生锈”只用于金属，不能与“糖水”搭配。"}, "sentence_index": 0, "correct_answer": "玻璃化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些盐水蒸干后会玻璃化，留下白色的盐。", "explanation": "这里应该用〈结晶〉。玻璃化指东西变得又硬又透明，像玻璃一样；盐水蒸干后析出白色晶体要用结晶。"}, {"text": "冰块放在火上会玻璃化。", "explanation": "这里应该用〈融化〉。冰受热变成水要用融化；玻璃化指东西变得像玻璃一样又硬又透明，与此不符。"}, {"text": "天然气加压后会玻璃化。", "explanation": "这里应该用〈液化〉。天然气加压后变成液体要用液化；玻璃化指东西变得像玻璃一样又硬又透明，气体不会这样变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25502, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "玻璃化", "is_correct": true, "explanation": "正确。“玻璃化”在句中指软胶冷冻后变硬、变得像玻璃一样，符合动词义。"}, {"text": "发酵", "is_correct": false, "explanation": "语义：发酵是微生物作用下的变化，句中说的是遇冷变硬，二者不符。"}, {"text": "烧焦", "is_correct": false, "explanation": "语义：烧焦需要高温，与句中“一冻”所表示的降温相反。"}, {"text": "生锈", "is_correct": false, "explanation": "搭配：“生锈”只用于金属，胶不会生锈。"}], "explanations": {"玻璃化": "正确。“玻璃化”在句中指软胶冷冻后变硬、变得像玻璃一样，符合动词义。", "发酵": "语义：发酵是微生物作用下的变化，句中说的是遇冷变硬，二者不符。", "烧焦": "语义：烧焦需要高温，与句中“一冻”所表示的降温相反。", "生锈": "搭配：“生锈”只用于金属，胶不会生锈。"}, "sentence_index": 6, "correct_answer": "玻璃化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "铸铁冷却后会玻璃化。", "explanation": "这里应该用〈凝固〉。铸铁冷却变成固体要用凝固；玻璃化指东西变得像玻璃一样又硬又透明，与此不符。"}, {"text": "水蒸气遇冷会玻璃化成水珠。", "explanation": "这里应该用〈凝结〉。水蒸气遇冷变成水珠是凝结；玻璃化指东西变得像玻璃一样又硬又透明，与此不符。"}, {"text": "新浇的混凝土会慢慢玻璃化。", "explanation": "这里应该用〈硬化〉。混凝土变硬是硬化；玻璃化指东西变得又硬又透明，像玻璃一样，混凝土不会这样变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25502, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这锅糖放凉后玻璃化的很快。", "corrected_sentence": "这锅糖放凉后玻璃化得很快。", "error_description": "补语标记错误：表示程度的补语应用“得”，写成“玻璃化得很快”；“的”不能引出补语，“玻璃化的很快”不合语法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25502, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些糖浆放凉以后，已经玻璃化着。", "corrected_sentence": "这些糖浆放凉以后，已经玻璃化了。", "error_description": "体标误用：“已经”表示变化完成，应搭配“了”说“已经玻璃化了”；“着”表示持续状态，不能与“已经”加变化动词“玻璃化”连用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
